.cc-factor-icon svg{width:12px;height:12px;stroke-width:2.5}
.cc-factor-text{font-size:var(--fs-sm);color:var(--text);line-height:1.45}
.cc-factor-text strong{font-weight:600}
.cc-factor-text small{color:var(--text-subtle);font-size:var(--fs-xs);display:block;margin-top:2px}
.cc-factor-impact{
