}
.cc-factor-impact.pos{background:var(--green-soft);color:var(--green)}
.cc-factor-impact.neg{background:var(--red-soft);color:var(--red)}
.cc-factor-impact.warn{background:var(--amber-soft);color:var(--amber)}

.cc-action{
