}
.cc-action-text{font-size:var(--fs-sm);color:var(--text);line-height:1.4}
.cc-action-text strong{color:var(--accent-text)}

/* Make Coverage Confidence KPI clickable */
.kpi-card.coverage{cursor:pointer;transition:border-color var(--t-fast),box-shadow var(--t-fast)}
.kpi-card.coverage:hover{border-color:var(--green-border);box-shadow:var(--shadow-md-hover), var(--highlight-top)}

/* ─────────────────────────────────────────────────────────────
   REPORTS DETAIL VIEWS
   ───────────────────────────────────────────────────────────── */
.report-back{
  display:inline-flex;align-items:center;gap:6px;font-size:var(--fs-sm);color:var(--text-muted);
  background:transparent;border:none;cursor:pointer;font-family:inherit;padding:0;margin-bottom:10px;
}
.report-back:hover{color:var(--text)}
.report-back svg{width:14px;height:14px;stroke-width:2}

.report-stat-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:var(--s-3);margin-bottom:var(--s-5)}
.report-event-list{display:flex;flex-direction:column}
.report-event{
  display:grid;grid-template-columns:auto 1fr auto auto;gap:var(--s-3);align-items:center;
  padding:var(--s-3-5) var(--s-5);border-bottom:1px solid var(--border);
}
.report-event:last-child{border-bottom:none}
.report-event-icon{
  width:32px;height:32px;border-radius:50%;display:flex;align-items:center;justify-content:center;flex-shrink:0;
}
.report-event-icon svg{width:14px;height:14px;stroke-width:2}
.report-event-icon.safety{background:var(--red-soft);color:var(--red)}
.report-event-icon.coach{background:var(--accent-soft);color:var(--accent-text)}
.report-event-icon.payout{background:var(--green-soft);color:var(--green)}
.report-event-name{font-size:var(--fs-md);font-weight:600;color:var(--text)}
.report-event-meta{font-size:var(--fs-xs);color:var(--text-subtle);margin-top:2px}
.report-event-time{font-size:var(--fs-xs);color:var(--text-subtle);white-space:nowrap}

.retention-cohort{
  background:var(--surface);border:1px solid var(--border);border-radius:var(--r-md);
  padding:var(--s-4);
}
.retention-cohort-num{font-size:var(--fs-xxl);font-weight:700;color:var(--text);letter-spacing:-.01em}
.retention-cohort-label{font-size:var(--fs-xs);font-weight:600;color:var(--text-muted);letter-spacing:.06em;text-transform:uppercase;margin-bottom:4px}
.retention-cohort-detail{font-size:var(--fs-xs);color:var(--text-subtle);margin-top:4px}
.retention-bar{height:6px;background:var(--canvas);border-radius:var(--r-sm);margin-top:10px;overflow:hidden}
.retention-bar-fill{height:100%;background:var(--green);border-radius:var(--r-sm)}
.retention-bar-fill.warn{background:var(--amber)}

/* Report detail views — show only when active */
.report-detail-view{display:none}
.report-detail-view.active{display:block}
.reports-grid-wrap.hidden{display:none}

/* ─────────────────────────────────────────────────────────────
   SETTINGS SECTIONS
   ───────────────────────────────────────────────────────────── */
.settings-section.hidden{display:none}
.member-row{
  display:grid;grid-template-columns:auto 1fr auto auto;gap:var(--s-3);align-items:center;
  padding:var(--s-3) 0;
}
.member-row + .member-row{border-top:1px solid var(--border)}
.role-pill{
  font-size:var(--fs-xs);font-weight:600;padding:3px 10px;border-radius:var(--r-lg);
  background:var(--canvas);color:var(--text-muted);
}
.role-pill.owner{background:var(--accent-soft);color:var(--accent-text)}
.role-pill.coach{background:var(--info-soft);color:var(--info-dark)}
.role-pill-paid,
.role-pill-active{background:var(--green-soft);color:var(--green-dark)}

.question-row{
  display:grid;grid-template-columns:auto 1fr auto auto;gap:var(--s-3);align-items:center;
  padding:var(--s-3) 0;font-size:var(--fs-md);
}
.question-row + .question-row{border-top:1px solid var(--border)}
.question-text{color:var(--text)}
.question-text small{display:block;color:var(--text-subtle);font-size:var(--fs-xs);margin-top:2px}

.crit-band{
  display:grid;grid-template-columns:auto 1fr auto;gap:var(--s-3);align-items:center;
  padding:var(--s-3-5) var(--s-4);border:1px solid var(--border);border-radius:var(--r-md);margin-bottom:var(--s-2);
}
.crit-band-label{font-size:var(--fs-md);font-weight:600}
.crit-band-help{font-size:var(--fs-xs);color:var(--text-subtle);margin-top:2px}
.crit-band-color{width:8px;height:32px;border-radius:var(--r-sm)}
.crit-band-color.green{background:var(--green)}
.crit-band-color.amber{background:var(--amber)}
.crit-band-color.red{background:var(--red)}

.billing-card{
