#rr-cb-root .cb-iconbtn{appearance:none;background:transparent;border:1px solid transparent;border-radius:var(--r-md);color:var(--text-subtle);cursor:pointer;padding:6px;display:inline-flex;align-items:center;justify-content:center;transition:background var(--t-fast),color var(--t-fast),border-color .12s}
#rr-cb-root .cb-iconbtn:hover{background:var(--surface-hover);color:var(--text);border-color:var(--border)}
