/* Sections + items */
#rr-cb-root .cb-sections{display:flex;flex-direction:column;gap:var(--s-3-5)}
#rr-cb-root .cb-section{background:var(--surface);border:1px solid var(--border);border-radius:var(--r-xl);padding:var(--s-3-5) var(--s-4) 8px;transition:border-color var(--t-fast),box-shadow var(--t-fast),opacity .12s}
