#rr-cb-root .cb-section-head{display:flex;align-items:center;gap:var(--s-2)}
#rr-cb-root .cb-handle{flex:0 0 auto;color:var(--text-subtle);cursor:grab;display:inline-flex;align-items:center;justify-content:center;padding:var(--s-1);border-radius:var(--r-sm);transition:background var(--t-fast),color var(--t-fast);opacity:.55}
#rr-cb-root .cb-handle:hover{background:var(--surface-hover);color:var(--text);opacity:1}
#rr-cb-root .cb-handle:active{cursor:grabbing}
#rr-cb-root .cb-handle svg{width:14px;height:14px}
#rr-cb-root .cb-section-label{flex:1;min-width:0;font:inherit;font-family:"Inter","Segoe UI Variable","Segoe UI",system-ui,-apple-system,sans-serif;font-size:var(--fs-lg);font-weight:600;color:var(--text);letter-spacing:-.01em;line-height:1.3;background:transparent;border:1px solid transparent;border-radius:var(--r-md);padding:var(--s-1) 8px;margin:-4px -8px;outline:none;transition:background var(--t-fast),border-color var(--t-fast),box-shadow var(--t-fast)}
#rr-cb-root .cb-section-label:hover,#rr-cb-root .cb-section-label:focus{background:var(--canvas);border-color:var(--border)}
#rr-cb-root .cb-section-label:focus{border-color:var(--accent);box-shadow:0 0 0 3px var(--accent-soft);background:var(--surface)}
#rr-cb-root .cb-section-actions{display:flex;gap:2px;opacity:0;transition:opacity var(--t-fast)}
#rr-cb-root .cb-section:hover .cb-section-actions,#rr-cb-root .cb-section:focus-within .cb-section-actions{opacity:1}
#rr-cb-root .cb-section-desc{display:block;width:calc(100% + 16px);margin:6px -8px 0;font:inherit;font-size:var(--fs-sm);color:var(--text-subtle);background:transparent;border:1px solid transparent;border-radius:var(--r-md);padding:5px 8px;outline:none;resize:none;line-height:1.5;min-height:20px;transition:background var(--t-fast),border-color var(--t-fast),box-shadow var(--t-fast)}
#rr-cb-root .cb-section-desc:hover,#rr-cb-root .cb-section-desc:focus{background:var(--canvas);border-color:var(--border);color:var(--text)}
#rr-cb-root .cb-section-desc:focus{border-color:var(--accent);box-shadow:0 0 0 3px var(--accent-soft);background:var(--surface)}
#rr-cb-root .cb-items{display:flex;flex-direction:column;margin:10px 0 4px;border-top:1px solid var(--border)}
#rr-cb-root .cb-item{display:grid;grid-template-columns:auto 16px 1fr auto auto;gap:var(--s-2);align-items:center;padding:var(--s-2) 0;border-bottom:1px solid var(--border);transition:background var(--t-fast),opacity .12s}
#rr-cb-root .cb-item:last-child{border-bottom:0}
#rr-cb-root .cb-item.dragging{opacity:.55}
#rr-cb-root .cb-item.drop-target{background:var(--accent-soft)}
#rr-cb-root .cb-item-check{flex:0 0 auto;width:16px;height:16px;border-radius:var(--r-sm);border:1.5px solid var(--border-strong);background:var(--surface);display:inline-flex;align-items:center;justify-content:center;cursor:default}
#rr-cb-root .cb-item-check::after{content:"";width:6px;height:10px;border:solid var(--accent);border-width:0 2px 2px 0;transform:rotate(45deg) translate(-1px,-1px);opacity:0}
#rr-cb-root .cb-item-label{flex:1;min-width:0;font:inherit;font-size:var(--fs-md);color:var(--text);background:transparent;border:1px solid transparent;border-radius:var(--r-md);padding:3px 8px;margin:-3px -8px;outline:none;transition:background var(--t-fast),border-color var(--t-fast),box-shadow var(--t-fast);line-height:1.45}
#rr-cb-root .cb-item-label:hover,#rr-cb-root .cb-item-label:focus{background:var(--canvas);border-color:var(--border)}
