#rr-cb-root .cb-item-required{flex:0 0 auto;display:inline-flex;align-items:center;gap:5px;font-size:10.5px;font-weight:600;color:var(--text-subtle);background:transparent;border:1px solid var(--border);border-radius:var(--r-pill);padding:3px 9px;cursor:pointer;transition:background var(--t-fast),color var(--t-fast),border-color .12s;letter-spacing:.02em}
#rr-cb-root .cb-item-required:hover{border-color:var(--border-strong);color:var(--text-muted)}
#rr-cb-root .cb-item-required.on{background:var(--red-soft);color:var(--red);border-color:transparent}
#rr-cb-root .cb-item-required.on:hover{background:var(--red-soft);color:var(--red)}
#rr-cb-root .cb-item-actions{display:flex;gap:2px;opacity:0;transition:opacity var(--t-fast)}
#rr-cb-root .cb-item:hover .cb-item-actions,#rr-cb-root .cb-item:focus-within .cb-item-actions{opacity:1}
#rr-cb-root .cb-additem{display:flex;align-items:center;gap:var(--s-2);width:100%;padding:9px 0;background:transparent;border:0;color:var(--text-subtle);font:inherit;font-size:var(--fs-sm);font-weight:500;cursor:pointer;transition:color var(--t-fast);text-align:left}
