#rr-cb-root .cb-addsection:hover{border-color:var(--accent);color:var(--accent-text);background:var(--accent-soft)}
#rr-cb-root .cb-addsection svg{width:14px;height:14px}

/* Item-instructions inline popover */
#rr-cb-root .cb-item-inst{grid-column:3 / -1;margin-top:-2px;display:block;width:100%;font:inherit;font-size:var(--fs-xs);color:var(--text-subtle);background:transparent;border:1px solid transparent;border-radius:var(--r-md);padding:3px 8px;outline:none;resize:none;line-height:1.5;min-height:18px;transition:background var(--t-fast),border-color var(--t-fast),box-shadow var(--t-fast)}
#rr-cb-root .cb-item-inst:hover,#rr-cb-root .cb-item-inst:focus{background:var(--canvas);border-color:var(--border);color:var(--text)}
