/* ─── Analytics page · AI-first analytics workspace ──────────────────── */
.rr-an-page{max-width:1180px;margin:0 auto;padding:var(--s-6) var(--s-5) var(--s-7)}
.rr-an-hero{padding:var(--s-6) 0 var(--s-5);text-align:left}
.rr-an-hero-eyebrow{display:inline-flex;align-items:center;gap:6px;font-size:var(--fs-xs);font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--accent-text);background:var(--accent-soft);padding:5px 10px;border-radius:var(--r-pill);margin-bottom:var(--s-3)}
.rr-an-hero-eyebrow svg{width:11px;height:11px;stroke-width:2.4}
.rr-an-hero h1{font-size:32px;font-weight:600;color:var(--text);letter-spacing:-.02em;margin:0 0 10px;line-height:1.15}
.rr-an-hero-sub{font-size:var(--fs-md);color:var(--text-subtle);margin:0 0 var(--s-5);max-width:680px;line-height:1.55}
.rr-an-search{position:relative;max-width:780px;background:var(--surface);border:1px solid var(--border);border-radius:var(--r-xl);box-shadow:var(--shadow-xs);transition:border-color var(--t-smooth),box-shadow var(--t-smooth)}
.rr-an-search:focus-within{border-color:var(--accent);box-shadow:var(--ring-focus)}
.rr-an-search-row{display:flex;align-items:flex-end;gap:var(--s-2);padding:var(--s-3-5) 14px 12px}
.rr-an-search-icon{flex:0 0 auto;width:32px;height:32px;border-radius:var(--r-lg);background:var(--accent);display:flex;align-items:center;justify-content:center;color:#fff}
.rr-an-search-icon svg{width:16px;height:16px;stroke-width:2.2}
.rr-an-search-input{flex:1;border:0;outline:0;background:transparent;font-size:var(--fs-md);font-family:inherit;color:var(--text);resize:none;min-height:36px;max-height:160px;line-height:1.45;padding:6px 4px}
.rr-an-search-input::placeholder{color:var(--text-subtle)}
.rr-an-search-submit{flex:0 0 auto;border:0;background:var(--accent);color:#fff;font-size:var(--fs-md);font-weight:600;padding:9px 16px;border-radius:var(--r-lg);cursor:pointer;display:flex;align-items:center;gap:6px;transition:background var(--t-smooth),transform var(--t-fast);letter-spacing:.01em}
.rr-an-search-submit:hover{background:var(--accent-hover)}
.rr-an-search-submit:active{transform:translateY(.5px)}
.rr-an-search-submit:disabled{opacity:.55;cursor:not-allowed}
.rr-an-search-submit svg{width:13px;height:13px;stroke-width:2.4}
.rr-an-examples{display:flex;flex-wrap:wrap;gap:var(--s-2);margin-top:var(--s-3);max-width:780px}
.rr-an-example{font-size:var(--fs-sm);color:var(--text-muted);background:var(--surface);border:1px solid var(--border);padding:6px 11px;border-radius:var(--r-pill);cursor:pointer;transition:border-color var(--t-smooth),color var(--t-smooth),background var(--t-smooth);line-height:1.3}
.rr-an-example:hover{border-color:var(--accent-border);color:var(--accent-text);background:var(--accent-soft)}

.rr-an-section-title{font-size:var(--fs-xs);font-weight:700;color:var(--text-subtle);letter-spacing:.08em;text-transform:uppercase;margin:var(--s-6) 0 var(--s-3);display:flex;align-items:center;gap:var(--s-2)}
.rr-an-section-title .rr-an-section-count{font-weight:600;color:var(--text-subtle);letter-spacing:0;text-transform:none;background:var(--surface-hover,#F1F5F9);padding:2px 7px;border-radius:var(--r-pill);font-size:var(--fs-xs)}

/* Result card — both for live result and pinned items */
.rr-an-result{background:var(--surface);border:1px solid var(--border);border-radius:var(--r-xl);padding:var(--s-5);box-shadow:var(--shadow-xs);position:relative;transition:box-shadow var(--t-spring)}
.rr-an-result:hover{box-shadow:var(--shadow-md)}
.rr-an-result-head{display:flex;justify-content:space-between;align-items:flex-start;gap:var(--s-4);margin-bottom:var(--s-3)}
.rr-an-result-title{font-size:15px;font-weight:600;color:var(--text);letter-spacing:-.005em;margin:0;line-height:1.3}
.rr-an-result-subtitle{font-size:var(--fs-sm);color:var(--text-subtle);margin:3px 0 0;line-height:1.45}
.rr-an-result-meta{display:flex;flex-wrap:wrap;gap:var(--s-2);margin-top:var(--s-2);font-size:var(--fs-xs);color:var(--text-subtle)}
.rr-an-result-meta span{display:inline-flex;align-items:center;gap:var(--s-1);background:var(--canvas);border:1px solid var(--border);padding:2px 7px;border-radius:var(--r-md);line-height:1.4}
.rr-an-result-meta svg{width:10px;height:10px;stroke-width:2.4;opacity:.65}
.rr-an-result-actions{display:flex;gap:var(--s-1);flex-wrap:wrap;justify-content:flex-end}
.rr-an-iconbtn{width:28px;height:28px;border-radius:var(--r-md);border:1px solid transparent;background:transparent;cursor:pointer;display:inline-flex;align-items:center;justify-content:center;color:var(--text-subtle);transition:background var(--t-fast),color var(--t-fast),border-color .12s}
.rr-an-iconbtn:hover{background:var(--canvas);color:var(--text);border-color:var(--border)}
.rr-an-iconbtn svg{width:14px;height:14px;stroke-width:2}
.rr-an-iconbtn.is-pinned{color:var(--accent-text);background:var(--accent-soft);border-color:var(--accent-border)}
.rr-an-iconbtn.is-pinned:hover{background:var(--accent-soft-strong)}
.rr-an-result-body{margin-top:var(--s-3)}

/* KPI rendering */
.rr-an-kpi{display:flex;align-items:baseline;gap:var(--s-3-5);padding:var(--s-3) 0}
.rr-an-kpi-value{font-size:42px;font-weight:600;letter-spacing:-.025em;color:var(--text);line-height:1;font-variant-numeric:tabular-nums}
.rr-an-kpi-unit{font-size:18px;font-weight:500;color:var(--text-subtle);letter-spacing:-.005em}
.rr-an-kpi-label{font-size:var(--fs-md);font-weight:500;color:var(--text-subtle);margin-top:6px}
.rr-an-kpi-delta{display:inline-flex;align-items:center;gap:var(--s-1);font-size:var(--fs-sm);font-weight:600;padding:3px var(--s-2);border-radius:var(--r-md)}
.rr-an-kpi-delta.up   {background:var(--green-soft);color:var(--green-dark)}
.rr-an-kpi-delta.down {background:var(--red-soft);color:var(--red-dark)}
.rr-an-kpi-delta.flat {background:var(--canvas);color:var(--text-subtle)}
.rr-an-kpi-delta svg{width:11px;height:11px;stroke-width:2.4}

.rr-an-kpi-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:var(--s-4) var(--s-5);margin-top:var(--s-2)}
.rr-an-kpi-grid-cell{padding:var(--s-2) 0}
.rr-an-kpi-grid-cell .rr-an-kpi-label{margin-top:0;margin-bottom:6px;font-size:var(--fs-sm)}
.rr-an-kpi-grid-cell .rr-an-kpi-value{font-size:30px}
.rr-an-kpi-grid-cell .rr-an-kpi-unit{font-size:15px;margin-left:4px}

/* Table rendering */
.rr-an-table-wrap{overflow-x:auto;margin-top:var(--s-2)}
.rr-an-table{width:100%;border-collapse:collapse;font-size:var(--fs-md);color:var(--text)}
.rr-an-table thead th{text-align:left;font-weight:600;font-size:var(--fs-xs);letter-spacing:.04em;text-transform:uppercase;color:var(--text-subtle);padding:var(--s-2-5) var(--s-3);border-bottom:1px solid var(--border);background:var(--canvas);position:sticky;top:0}
.rr-an-table thead th:first-child{border-top-left-radius:8px}
.rr-an-table thead th:last-child{border-top-right-radius:8px}
.rr-an-table tbody td{padding:var(--s-2-5) var(--s-3);border-bottom:1px solid var(--border-subtle,#F1F5F9);vertical-align:middle}
.rr-an-table tbody tr:last-child td{border-bottom:0}
.rr-an-table tbody tr:hover{background:var(--canvas)}
.rr-an-table td.num{text-align:right;font-variant-numeric:tabular-nums}
.rr-an-table-badge{display:inline-block;padding:2px 8px;border-radius:var(--r-pill);font-size:var(--fs-xs);font-weight:600;background:var(--canvas);color:var(--text)}
.rr-an-table-badge.green{background:var(--green-soft-strong);color:var(--green-dark)}
.rr-an-table-badge.amber{background:var(--amber-soft-strong);color:var(--amber-dark)}
.rr-an-table-badge.red  {background:var(--red-soft-strong);color:var(--red-dark)}
.rr-an-table-badge.blue {background:var(--accent-soft);color:var(--accent-text)}

/* Text summary rendering */
.rr-an-text-body{font-size:var(--fs-base);line-height:1.55;color:var(--text);margin:0}
.rr-an-text-body p{margin:0 0 10px}
.rr-an-text-body p:last-child{margin-bottom:0}
.rr-an-bullets{list-style:none;padding:0;margin:var(--s-3) 0 0;display:flex;flex-direction:column;gap:var(--s-2)}
.rr-an-bullets li{padding-left:18px;position:relative;font-size:var(--fs-md);line-height:1.55;color:var(--text)}
.rr-an-bullets li::before{content:"";position:absolute;left:0;top:8px;width:6px;height:6px;border-radius:var(--r-pill);background:var(--accent)}

/* Clarification rendering */
.rr-an-clarify{padding:var(--s-3) 0}
.rr-an-clarify-msg{font-size:var(--fs-base);line-height:1.55;color:var(--text);margin:0 0 var(--s-3)}

/* Followup chips */
.rr-an-followups{display:flex;flex-wrap:wrap;gap:var(--s-2);margin-top:var(--s-4);padding-top:var(--s-4);border-top:1px dashed var(--border)}
.rr-an-followup-label{font-size:var(--fs-xs);font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--text-subtle);width:100%;margin-bottom:2px}
.rr-an-followup{font-size:var(--fs-sm);color:var(--text-muted);background:var(--canvas);border:1px solid var(--border);padding:5px 10px;border-radius:var(--r-pill);cursor:pointer;transition:border-color var(--t-smooth),color var(--t-smooth),background var(--t-smooth);line-height:1.3}
.rr-an-followup:hover{border-color:var(--accent-border);color:var(--accent-text);background:var(--accent-soft)}

/* Loading + error states */
.rr-an-loading{padding:var(--s-5);display:flex;align-items:center;gap:var(--s-3);color:var(--text-subtle);font-size:var(--fs-md)}
.rr-an-loading-dots{display:inline-flex;gap:var(--s-1)}
.rr-an-loading-dots span{width:6px;height:6px;border-radius:var(--r-pill);background:var(--accent);animation:rr-an-bounce 1s infinite ease-in-out}
.rr-an-loading-dots span:nth-child(2){animation-delay:.15s}
.rr-an-loading-dots span:nth-child(3){animation-delay:.30s}
@keyframes rr-an-bounce{0%,80%,100%{transform:scale(.6);opacity:.6}40%{transform:scale(1);opacity:1}}
.rr-an-error{margin:var(--s-3) 0;padding:var(--s-3) var(--s-4);background:var(--red-soft);border:1px solid var(--red-border);border-radius:var(--r-lg);color:var(--red-dark);font-size:var(--fs-md);line-height:1.5}

/* Pinned grid */
.rr-an-pinned-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(360px,1fr));gap:var(--s-4)}
.rr-an-pinned-grid .rr-an-result{cursor:default}

/* Empty state */
.rr-an-empty{padding:var(--s-8) var(--s-6);text-align:center;background:var(--surface);border:1px dashed var(--border);border-radius:var(--r-xl);color:var(--text-subtle)}
.rr-an-empty-icon{width:42px;height:42px;border-radius:var(--r-lg);display:inline-flex;align-items:center;justify-content:center;background:var(--accent-soft);color:var(--accent-text);margin-bottom:var(--s-3)}
.rr-an-empty-icon svg{width:20px;height:20px;stroke-width:2}
.rr-an-empty-title{font-size:var(--fs-base);font-weight:600;color:var(--text);margin:0 0 var(--s-1);letter-spacing:-.005em}
.rr-an-empty-sub{font-size:var(--fs-sm);color:var(--text-subtle);margin:0;line-height:1.55;max-width:480px;margin:0 auto}

/* Date-range editor inline popover */
.rr-an-range{display:inline-flex;align-items:center;gap:6px;font-size:var(--fs-xs);color:var(--text-subtle);cursor:pointer}
.rr-an-range:hover{color:var(--accent-text)}
.rr-an-range svg{width:10px;height:10px;stroke-width:2.4}

/* Tap-to-call icon + number — rendered everywhere we show a phone number
   so dispatchers can dial straight from any list, drawer, or report. */
.rr-call-link{display:inline-flex;align-items:center;justify-content:center;color:var(--accent-text);border-radius:var(--r-md);padding:3px;margin:-3px 4px -3px -3px;flex:0 0 auto;text-decoration:none;transition:background var(--t-fast)}
.rr-call-link:hover{background:var(--accent-soft)}
.rr-call-text{color:inherit}

/* Time off · Schedule sub-tab (loadTimeOffView in live.js).
   Uses the dashboard's section-head + card pattern so the layout
   matches Templates / Staff: a section banner across the top of a
   surface card, soft-canvas inset rows separated by --border-subtle,
   shared .status-pill / .btn / .form-input tokens for everything
   inside. No hardcoded colours — everything resolves through the
   palette tokens defined in :root. */
/* Requests sub-view (PTO / Time off, Availability) — Microsoft
   Fluent treatment: card surface with subtle elevation, Outlook-
   style head bar, calm hairlines. Same .to-* class names as the
   legacy #sched-sub-time-off scope so the renderer doesn't have
   to change — we just extend the selector to include the new
   #sched-sub-requests panel host. */

/* ── Requests · KPI drill-down panel ───────────────────────────
   Drops in below the KPI strip when a KPI pill is clicked.  Calm
   white card with a left accent rail and a row list; each row
   has a "View on driver →" link that opens the existing driver
   drawer. */
.rr-sched-req-drilldown{
  background:#FFFFFF;
  border:1px solid rgba(15,23,42,.08);
  border-left:3px solid var(--accent);
  border-radius:var(--r-lg);
  box-shadow:var(--shadow-sm);
  margin:0 0 var(--s-4) 0;
  overflow:hidden;
}
.rr-sched-req-dd-head{
  display:flex;align-items:flex-start;justify-content:space-between;
  gap:var(--s-3);padding:12px 18px;
  border-bottom:1px solid var(--border-subtle);
  background:var(--surface-secondary, #FAFBFD);
}
.rr-sched-req-dd-eyebrow{
  font-size:10.5px;font-weight:700;letter-spacing:.07em;text-transform:uppercase;
  color:var(--text-subtle);
}
.rr-sched-req-dd-title{
  font-size:14px;font-weight:600;color:var(--text);margin-top:2px;letter-spacing:-.005em;
}
.rr-sched-req-dd-close{
  background:none;border:0;cursor:pointer;color:var(--text-muted);
  font-size:20px;line-height:1;padding:4px 8px;border-radius:6px;
  transition:background var(--t-fast),color var(--t-fast);
}
.rr-sched-req-dd-close:hover{background:var(--canvas);color:var(--text)}
.rr-sched-req-dd-list{display:flex;flex-direction:column}
.rr-sched-req-dd-row{
  display:grid;
  grid-template-columns:90px 1fr auto auto;
  gap:var(--s-3);align-items:center;
  padding:10px 18px;
  border-top:1px solid var(--border-subtle);
}
.rr-sched-req-dd-row:first-child{border-top:0}
.rr-sched-req-dd-kind{
  font-size:10.5px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;
  color:var(--text-subtle);
}
.rr-sched-req-dd-body{min-width:0}
.rr-sched-req-dd-name{font-size:13px;font-weight:600;color:var(--text)}
.rr-sched-req-dd-line{font-size:12px;color:var(--text-subtle);margin-top:2px;line-height:1.4}
.rr-sched-req-dd-status{
  font-size:10.5px;font-weight:700;letter-spacing:.04em;text-transform:uppercase;
  padding:2px 8px;border-radius:var(--r-pill);
  background:var(--canvas);color:var(--text-muted);
}
.rr-sched-req-dd-status.is-approved{background:var(--green-soft);color:var(--green)}
.rr-sched-req-dd-status.is-denied{background:var(--red-soft);color:var(--red)}
.rr-sched-req-dd-status.is-cancelled{background:var(--canvas);color:var(--text-subtle)}
.rr-sched-req-dd-open{
  appearance:none;background:transparent;border:0;cursor:pointer;font:inherit;
  font-size:12px;font-weight:600;color:var(--accent-text);
  padding:4px 8px;border-radius:var(--r-md);
  transition:background var(--t-fast);
}
.rr-sched-req-dd-open:hover{background:var(--accent-soft)}
.rr-sched-req-dd-more{
  padding:8px 18px;font-size:11px;color:var(--text-subtle);
  border-top:1px solid var(--border-subtle);background:var(--surface-secondary, #FAFBFD);
}
.rr-sched-req-dd-empty{padding:24px 18px;font-size:13px;color:var(--text-subtle);text-align:center}
.rr-sched-req-dd-source{
  padding:8px 18px;font-size:11px;color:var(--text-subtle);
  background:var(--surface-secondary, #FAFBFD);border-top:1px solid var(--border-subtle);
}
/* Day-of-week histogram (topday drill-down) */
.rr-sched-req-dd-days{display:flex;flex-direction:column;gap:6px;padding:14px 18px}
.rr-sched-req-dd-day{
  display:grid;grid-template-columns:36px 1fr 36px;gap:10px;align-items:center;
  font-size:12px;color:var(--text);
}
.rr-sched-req-dd-day-lbl{font-weight:600;color:var(--text-muted);letter-spacing:.02em;text-transform:uppercase;font-size:10.5px}
.rr-sched-req-dd-day-bar{
  height:8px;border-radius:4px;background:var(--canvas);overflow:hidden;
}
.rr-sched-req-dd-day-bar > span{
  display:block;height:100%;background:var(--accent);border-radius:4px;
  transition:width var(--t-smooth);
}
.rr-sched-req-dd-day-n{font-variant-numeric:tabular-nums;font-weight:600;text-align:right;color:var(--text)}
.rr-sched-req-dd-split{display:flex;flex-direction:column;gap:10px;padding:14px 18px}
.rr-sched-req-dd-split-row{
  display:grid;grid-template-columns:90px 1fr 110px;gap:10px;align-items:center;
  font-size:12px;color:var(--text);
}
.rr-sched-req-dd-split-lbl{font-weight:600;color:var(--text-muted);letter-spacing:.02em;text-transform:uppercase;font-size:10.5px}

#sched-sub-time-off .to-page,
#sched-sub-requests .to-page{display:flex;flex-direction:column;gap:var(--s-4)}
#sched-sub-time-off .to-card,
#sched-sub-requests .to-card{
  background:#fff;
  border:1px solid var(--sch-line, var(--border));
  border-radius:var(--r-lg, 10px);
  overflow:hidden;
  box-shadow:0 1px 2px rgba(15,23,42,.04),0 1px 1px rgba(15,23,42,.02);
}
#sched-sub-time-off .to-card-head,
#sched-sub-requests .to-card-head{
  padding:var(--s-3-5) var(--s-5);
  background:var(--sch-surface-2, var(--canvas));
  border-bottom:1px solid var(--sch-line, var(--border-subtle));
  display:flex;align-items:center;justify-content:space-between;gap:var(--s-3);
}
#sched-sub-time-off .to-card-head-title,
#sched-sub-requests .to-card-head-title{
  font-size:var(--fs-md);font-weight:700;color:var(--text);
  line-height:1.25;letter-spacing:-.005em;
}
#sched-sub-time-off .to-card-head-count,
#sched-sub-requests .to-card-head-count{
  font-size:11px;font-weight:700;color:var(--text-subtle);
  text-transform:uppercase;letter-spacing:.06em;
}
#sched-sub-time-off .to-row,
#sched-sub-requests .to-row{
  padding:var(--s-4) var(--s-5);
  border-top:1px solid var(--sch-line-subtle, var(--border-subtle));
  transition:background var(--t-fast);
}
#sched-sub-time-off .to-row:hover,
#sched-sub-requests .to-row:hover{background:var(--sch-blue-softer, rgba(37,99,235,.04))}
#sched-sub-time-off .to-row:first-child,
#sched-sub-requests .to-row:first-child{border-top:0}
#sched-sub-time-off .to-row-head,
#sched-sub-requests .to-row-head{
  display:flex;align-items:flex-start;justify-content:space-between;gap:var(--s-3);
}
#sched-sub-time-off .to-row-name,
#sched-sub-requests .to-row-name{
  font-size:var(--fs-md);font-weight:600;color:var(--text);
  line-height:1.3;
}
#sched-sub-time-off .to-row-range,
#sched-sub-requests .to-row-range{
  font-size:var(--fs-sm);color:var(--text-subtle);
  margin-top:2px;
}
#sched-sub-time-off .to-row-reason,
#sched-sub-requests .to-row-reason{
  font-size:var(--fs-sm);color:var(--text-muted);
  margin-top:var(--s-2);line-height:1.45;
}
#sched-sub-time-off .to-row-reason-empty,
#sched-sub-requests .to-row-reason-empty{
  color:var(--text-subtle);font-style:italic;
}
#sched-sub-time-off .to-row-note-ro,
#sched-sub-requests .to-row-note-ro{
  margin-top:var(--s-2-5);
  background:var(--sch-surface-2, var(--canvas));border-radius:var(--r-md);
  padding:var(--s-2) var(--s-3);
  font-size:var(--fs-sm);color:var(--text);line-height:1.45;
}
#sched-sub-time-off .to-row-note-ro strong,
#sched-sub-requests .to-row-note-ro strong{color:var(--text-muted);font-weight:600}
#sched-sub-time-off textarea.form-input,
#sched-sub-requests textarea.form-input{
  margin-top:var(--s-2-5);
  max-width:none;min-height:64px;
  border-radius:var(--r-md);
  border:1px solid var(--sch-line, var(--border));
  padding:var(--s-2-5) var(--s-3);
  font-size:var(--fs-sm);
  transition:border-color var(--t-fast),box-shadow var(--t-fast);
}
#sched-sub-time-off textarea.form-input:focus,
#sched-sub-requests textarea.form-input:focus{
  outline:none;border-color:var(--req-accent, var(--accent));
  box-shadow:0 0 0 1px var(--req-accent, var(--accent));
}
#sched-sub-time-off .to-row-actions,
#sched-sub-requests .to-row-actions{
  display:flex;justify-content:flex-end;gap:var(--s-2);
  margin-top:var(--s-3);
}

/* Coverage verdict strip · painted into each pending row by
   _toPaintCoverage after the row mounts. Calm Outlook tone —
   8 px dot + sentence, color matches the verdict (green / amber
   / red). */
#sched-sub-time-off .to-row-coverage,
#sched-sub-requests .to-row-coverage{
  display:flex;align-items:center;gap:8px;
  margin-top:var(--s-2);
  padding:8px 12px;
  background:var(--sch-surface-2, #F9FAFB);
  border:1px solid var(--sch-line, var(--border));
  border-radius:var(--r-md);
  font-size:var(--fs-sm, 13px);line-height:1.45;
  color:var(--text);
}
#sched-sub-time-off .to-row-coverage .to-row-coverage-dot,
#sched-sub-requests .to-row-coverage .to-row-coverage-dot{
  flex:0 0 auto;
  width:8px;height:8px;border-radius:50%;
  background:var(--text-subtle);
}
#sched-sub-time-off .to-row-coverage.to-cov-ok,
#sched-sub-requests .to-row-coverage.to-cov-ok{
  background:rgba(22,163,74,.06);
  border-color:rgba(22,163,74,.28);
  color:#0F5C32;
}
#sched-sub-time-off .to-row-coverage.to-cov-ok .to-row-coverage-dot,
#sched-sub-requests .to-row-coverage.to-cov-ok .to-row-coverage-dot{
  background:#16A34A;
}
#sched-sub-time-off .to-row-coverage.to-cov-rule,
#sched-sub-requests .to-row-coverage.to-cov-rule{
  background:rgba(180,83,9,.06);
  border-color:rgba(180,83,9,.28);
  color:#9A4400;
}
#sched-sub-time-off .to-row-coverage.to-cov-rule .to-row-coverage-dot,
#sched-sub-requests .to-row-coverage.to-cov-rule .to-row-coverage-dot{
  background:#B45309;
}
#sched-sub-time-off .to-row-coverage.to-cov-blocked,
#sched-sub-requests .to-row-coverage.to-cov-blocked{
  background:rgba(196,43,28,.06);
  border-color:rgba(196,43,28,.28);
  color:#A11E13;
}
#sched-sub-time-off .to-row-coverage.to-cov-blocked .to-row-coverage-dot,
#sched-sub-requests .to-row-coverage.to-cov-blocked .to-row-coverage-dot{
  background:#DC2626;
}
#sched-sub-time-off .to-row-coverage.to-cov-empty,
#sched-sub-requests .to-row-coverage.to-cov-empty{
  color:var(--text-muted);
}
#sched-sub-time-off .to-row-coverage.to-cov-unknown,
#sched-sub-requests .to-row-coverage.to-cov-unknown{
  color:var(--text-muted);
}
#sched-sub-time-off .to-row-coverage .to-row-coverage-text,
#sched-sub-requests .to-row-coverage .to-row-coverage-text{
  color:inherit;
}
/* Coverage strip · verdict line + per-day staffing telemetry. */
#sched-sub-requests .to-row-coverage{
  flex-direction:column;align-items:stretch;gap:7px;
}
#sched-sub-requests .to-cov-head{
  display:flex;align-items:center;gap:8px;
}
#sched-sub-requests .to-cov-verdict{
  font-size:12px;line-height:1.4;color:inherit;
}
#sched-sub-requests .to-cov-days{
  display:flex;flex-direction:column;gap:3px;
  padding-left:16px;
}
#sched-sub-requests .to-cov-day{
  display:flex;align-items:flex-start;justify-content:space-between;gap:12px;
  font-size:11px;font-variant-numeric:tabular-nums;
}
#sched-sub-requests .to-cov-day-d{
  font-weight:600;color:var(--text-subtle);
}
#sched-sub-requests .to-cov-day-v{
  display:inline-flex;flex-direction:column;align-items:flex-end;gap:2px;
  white-space:nowrap;color:var(--text-muted);
}
#sched-sub-requests .to-cov-staff{display:inline-flex;align-items:baseline;gap:5px}
#sched-sub-requests .to-cov-by{font-size:11px;font-weight:600;color:#15803D}
#sched-sub-requests .to-cov-by-more{font-weight:500;color:var(--text-subtle)}
#sched-sub-requests .to-cov-now{font-weight:600;color:var(--text-muted)}
#sched-sub-requests .to-cov-arrow{color:var(--text-subtle)}
#sched-sub-requests .to-cov-after{font-weight:700;color:var(--text)}
#sched-sub-requests .to-cov-after.is-drop{color:#9F635B}
#sched-sub-requests .to-cov-day-muted{color:var(--text-subtle);font-weight:500}
/* Caption labelling the two staffing numbers around the arrow. */
#sched-sub-requests .to-cov-legend{font-size:11px;color:var(--text-subtle);margin:0 0 5px}
#sched-sub-requests .to-cov-rec{font-weight:700}
#sched-sub-requests .to-cov-rec-approve{color:#15803D}
#sched-sub-requests .to-cov-rec-deny{color:#B42318}
#sched-sub-requests .to-cov-legend b{font-weight:600;color:var(--text-muted)}
#sched-sub-requests .to-cov-frac{color:var(--text-subtle);font-weight:500}

/* Requests page · ONE operational coordination workspace — a unified
   request stream and an operational telemetry rail, joined as a
   single quiet panel. Microsoft Fluent restraint: hairline structure,
   typography-led hierarchy, low saturation, calm telemetry. */
#sched-sub-requests{
  --req-accent:var(--accent);             /* Microsoft Fluent communication blue */
  --req-telemetry:#6E83A6;          /* calm slate-blue · capacity bars */
  --req-below:#AD8A4F;              /* muted ochre · below staffing target */
  --req-track:rgba(15,23,42,.055);  /* bar track */
  --req-hairline:rgba(15,23,42,.05);
  --req-hairline-faint:rgba(15,23,42,.032);
}
/* Two calm panels — the request stream and the telemetry rail —
   set apart by quiet Fluent spacing. */
#sched-sub-requests .sched-requests-split{
  display:grid;
  grid-template-columns:1fr;
  gap:var(--s-4);
  align-items:stretch;
}
@media (max-width:1080px){
  #sched-sub-requests .sched-requests-card{max-height:none}
}
#sched-sub-requests .sched-requests-card{
  background:var(--surface-elevated, #FFFFFF);
  border:1px solid var(--req-hairline);
  border-radius:8px;
  box-shadow:0 1px 4px rgba(15,23,42,.04);
  overflow:hidden;min-width:0;
  display:flex;flex-direction:column;
  max-height:calc(100vh - 250px);
  min-height:380px;
}
#sched-sub-requests .sched-requests-card-head{
  display:flex;align-items:center;gap:8px;
  padding:12px 18px 11px;
  border-bottom:1px solid var(--req-hairline-faint);
  color:var(--text-subtle);
}
#sched-sub-requests .sched-requests-card-title{
  font-size:11px;font-weight:700;color:var(--text-subtle);
  letter-spacing:.07em;text-transform:uppercase;
}
#sched-sub-requests .sched-requests-card-body{
  padding:4px 18px 14px;flex:1;min-width:0;
  overflow-y:auto;
}

/* Section eyebrows · Pending / History — quiet operational labels. */
#sched-sub-requests .to-page{gap:10px}
#sched-sub-requests .to-card{
  background:transparent;border:0;border-radius:0;box-shadow:none;overflow:visible;
}
#sched-sub-requests .to-card-head{
  padding:13px 0 1px;background:transparent;border-bottom:0;
  display:flex;align-items:baseline;justify-content:space-between;gap:8px;
}
#sched-sub-requests .to-card-head-title{
  font-size:10px;font-weight:700;color:var(--text-subtle);
  letter-spacing:.07em;text-transform:uppercase;
}
#sched-sub-requests .to-card-head-count{
  font-size:10px;font-weight:600;color:var(--text-subtle);
  letter-spacing:.02em;text-transform:none;
}

/* Request rows · Outlook-inbox rhythm — compressed, hairline-faint,
   separated by tone + spacing rather than hard dividers. */
#sched-sub-requests .to-row{
  padding:8px;margin:0 -8px;
  border-top:0;
  border-radius:5px;
  transition:background var(--t-fast), box-shadow var(--t-fast);
}
#sched-sub-requests .to-row:hover{background:rgba(15,23,42,.025)}
/* A request just decided in this session — surfaced at the top of
   History with a calm tint so it reads as "your last action". */
#sched-sub-requests .to-row.req-row-fresh{
  background:rgba(37,99,235,.05);
  box-shadow:inset 2px 0 0 rgba(37,99,235,.45);
}
#sched-sub-requests .to-row.req-row-fresh:hover{background:rgba(37,99,235,.07)}
#sched-sub-requests .to-row .sched-req-days{margin-top:6px}
/* Driver name + date sub-line match the Schedule grid's row label
   (.cal-row-label-name 13px/700/-.005em/1.25 + .cal-row-label-meta 10px) —
   operator asked to align the Requests sub-view with the schedule. */
#sched-sub-requests .to-row-name{font-size:var(--fs-md);font-weight:700;letter-spacing:-.005em;line-height:1.25}
#sched-sub-requests .to-row-range{font-size:10px;color:var(--text-subtle);margin-top:1px}

/* State pills · restrained Microsoft treatment — a small tonal dot
   and a quiet label, no filled chip. */
#sched-sub-requests .status-pill{
  background:transparent;border:0;padding:0;
  gap:5px;font-size:10px;font-weight:600;letter-spacing:.04em;
  color:var(--text-subtle);
}
#sched-sub-requests .status-pill::before{
  content:"";width:5px;height:5px;border-radius:50%;
  background:currentColor;flex:0 0 auto;
}
#sched-sub-requests .status-pill-pending{color:#9A7438}
#sched-sub-requests .status-pill-approved{color:#4F7C61}
#sched-sub-requests .status-pill-denied{color:#9F635B}
#sched-sub-requests .status-pill-neutral{color:var(--text-subtle)}

/* Request-type badge · one consistent low-saturation chip. */
#sched-sub-requests .req-type-badge{
  display:inline-flex;align-items:center;
  font-size:9.5px;font-weight:600;letter-spacing:.05em;text-transform:uppercase;
  padding:1px 6px;border-radius:4px;
  margin-left:7px;vertical-align:middle;
}
#sched-sub-requests .req-type-badge.is-pto{background:rgba(60,111,102,.12);color:#3C6F66}
#sched-sub-requests .req-type-badge.is-unpaid{background:rgba(15,23,42,.05);color:var(--text-subtle)}
#sched-sub-requests .req-type-badge.is-availability{background:rgba(74,101,128,.12);color:#4A6580}

/* Right rail · three reports as continuous sections of one panel. */
#sched-sub-requests .sched-requests-reports{
  display:flex;flex-direction:column;min-width:0;
  background:var(--surface-elevated, #FFFFFF);
  border:1px solid var(--req-hairline);
  border-radius:8px;
  box-shadow:0 1px 4px rgba(15,23,42,.04);
  overflow:hidden;
}
#sched-sub-requests .sched-req-report{
  flex:1 1 0;min-height:0;
  display:flex;flex-direction:column;
  background:transparent;border:0;border-radius:0;box-shadow:none;
}
/* Reports read as continuous telemetry — separation comes from the
   eyebrow title and spacing, not a divider. */
#sched-sub-requests .sched-req-report + .sched-req-report{
  border-top:0;
}
#sched-sub-requests .sched-req-report-head{
  padding:13px 18px 0;border-bottom:0;
}
#sched-sub-requests .sched-req-report-title{
  display:block;font-size:10px;font-weight:700;color:var(--text-subtle);
  letter-spacing:.07em;text-transform:uppercase;
}
#sched-sub-requests .sched-req-report-sub{
  display:block;font-size:10.5px;color:var(--text-subtle);
  margin-top:3px;letter-spacing:.01em;opacity:.85;
}
#sched-sub-requests .sched-req-report-body{
  padding:10px 18px 14px;flex:1;
  display:flex;flex-direction:column;justify-content:center;gap:6px;
}
/* Capacity telemetry rows · weekday label, thin bar, share + delta. */
#sched-sub-requests .req-rpt-row{
  display:grid;grid-template-columns:30px 1fr 112px;
  gap:10px;align-items:center;
  font-size:10.5px;color:var(--text-muted);font-variant-numeric:tabular-nums;
}
#sched-sub-requests .req-rpt-row-lbl{
  font-weight:600;color:var(--text-subtle);letter-spacing:.02em;
}
#sched-sub-requests .req-rpt-bar{
  position:relative;height:4px;
  background:var(--req-track);border-radius:2px;
}
#sched-sub-requests .req-rpt-bar-fill{
  position:absolute;left:0;top:0;bottom:0;
  background:var(--req-telemetry);border-radius:2px;
}
#sched-sub-requests .req-rpt-bar-fill.is-below{background:var(--req-below)}
#sched-sub-requests .req-rpt-threshold{
  position:absolute;top:-2px;bottom:-2px;width:1px;
  background:rgba(15,23,42,.26);
}
#sched-sub-requests .req-rpt-row-n{
  display:inline-flex;align-items:baseline;justify-content:flex-end;gap:5px;
  font-weight:600;color:var(--text-muted);
}
#sched-sub-requests .req-rpt-pct{
  font-size:11.5px;font-weight:700;color:var(--text);letter-spacing:-.01em;
}
#sched-sub-requests .req-rpt-cnt{
  font-size:9.5px;font-weight:500;color:var(--text-subtle);
}
#sched-sub-requests .req-rpt-delta{
  font-size:9.5px;font-weight:600;
}
#sched-sub-requests .req-rpt-delta.is-over{color:#4F7C61}
#sched-sub-requests .req-rpt-delta.is-under{color:var(--req-below, #AD8A4F)}
/* FT/PT sub-sections. */
#sched-sub-requests .req-rpt-sect + .req-rpt-sect{margin-top:9px}
#sched-sub-requests .req-rpt-sect-lbl{
  font-size:9.5px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;
  color:var(--text-subtle);margin-bottom:5px;
}
#sched-sub-requests .req-rpt-split{
  display:flex;height:6px;border-radius:2px;overflow:hidden;
  background:var(--req-track);
}
#sched-sub-requests .req-rpt-split > span{display:block;height:100%}
#sched-sub-requests .req-rpt-split-ft{background:var(--req-telemetry)}
#sched-sub-requests .req-rpt-split-pt{background:rgba(15,23,42,.14)}
#sched-sub-requests .req-rpt-split-legend{
  display:flex;gap:14px;margin-top:5px;
  font-size:10.5px;color:var(--text-subtle);font-variant-numeric:tabular-nums;
}
#sched-sub-requests .req-rpt-split-legend b{color:var(--text-muted);font-weight:600}
#sched-sub-requests .req-rpt-legend-dot{
  display:inline-block;width:6px;height:6px;border-radius:50%;
  margin-right:5px;vertical-align:middle;
}
#sched-sub-requests .req-rpt-legend-ft{background:var(--req-telemetry)}
#sched-sub-requests .req-rpt-legend-pt{background:rgba(15,23,42,.20)}
/* Operational insight · the FT/PT misalignment read-out. */
#sched-sub-requests .req-rpt-insight{
  margin-top:9px;padding-top:9px;
  border-top:1px solid var(--req-hairline-faint);
  font-size:11px;color:var(--text-muted);line-height:1.45;
  display:flex;gap:8px;align-items:stretch;
}
#sched-sub-requests .req-rpt-insight::before{
  content:"";flex:0 0 auto;width:2px;border-radius:1px;
  background:var(--req-telemetry);opacity:.55;
}
#sched-sub-requests .req-rpt-insight b{color:var(--text);font-weight:600}
/* Reserve capacity · the headline elasticity number. */
#sched-sub-requests .req-rpt-hero{
  display:flex;align-items:baseline;gap:10px;
}
#sched-sub-requests .req-rpt-hero-num{
  font-size:40px;font-weight:700;line-height:.95;
  color:var(--sch-blue-text, #1E40AF);
  font-variant-numeric:tabular-nums;letter-spacing:-.03em;
}
#sched-sub-requests .req-rpt-hero-unit{
  font-size:11px;font-weight:600;color:var(--text-muted);
}
#sched-sub-requests .req-rpt-hero-lbl{
  font-size:9px;font-weight:700;letter-spacing:.09em;text-transform:uppercase;
  color:var(--text-subtle);margin-top:2px;
}
/* Operational readiness read-out · a dot + a calm status sentence. */
#sched-sub-requests .req-rpt-status{
  display:flex;align-items:center;gap:6px;margin-top:2px;
  font-size:11px;font-weight:600;color:var(--text-muted);
}
#sched-sub-requests .req-rpt-status-dot{
  width:6px;height:6px;border-radius:50%;flex-shrink:0;
  background:var(--text-subtle);
}
#sched-sub-requests .req-rpt-status.is-healthy .req-rpt-status-dot{background:#4F7C61}
#sched-sub-requests .req-rpt-status.is-moderate .req-rpt-status-dot{background:#AD8A4F}
#sched-sub-requests .req-rpt-status.is-low .req-rpt-status-dot{background:#9F635B}
#sched-sub-requests .req-rpt-note{
  font-size:10.5px;color:var(--text-subtle);line-height:1.5;
}
#sched-sub-requests .req-rpt-note b{color:var(--text-muted);font-weight:600}
#sched-sub-requests .req-rpt-names{
  display:flex;flex-wrap:wrap;gap:4px;margin-top:1px;
}
#sched-sub-requests .req-rpt-name{
  display:inline-flex;align-items:center;
  font-size:10px;font-weight:500;color:var(--text-muted);
  background:rgba(15,23,42,.045);
  padding:1px 7px;border-radius:4px;
}
#sched-sub-requests .req-rpt-empty{
  font-size:10.5px;color:var(--text-subtle);font-style:italic;
}
/* ─────────────────────────────────────────────────────────────
   DVIC compare modal — lifted out of an innerHTML <style> block
   so the CSS is parsed once at page load instead of every time a
   van's photo review opens.  Scope stays anchored to the modal
   ID so nothing leaks into the rest of the dashboard.
   ───────────────────────────────────────────────────────────── */
#rr-dvic-modal .rr-modal-panel{width:1200px;max-height:90vh}
/* Upper grid: Previous | Current | AI Review Summary */
#rr-dvic-modal .dvic-top{display:grid;grid-template-columns:1fr 1fr 1.25fr;gap:var(--s-3);margin-bottom:var(--s-4)}
#rr-dvic-modal .dvic-card{border:1px solid var(--border);border-radius:var(--r-lg);padding:var(--s-3-5) var(--s-4);background:var(--surface);box-shadow:var(--shadow-xs);display:flex;flex-direction:column;min-width:0}
#rr-dvic-modal .dvic-card-eyebrow{font-size:var(--fs-xs);font-weight:700;letter-spacing:.04em;text-transform:uppercase;color:var(--text-subtle);margin-bottom:var(--s-2)}
#rr-dvic-modal .dvic-card-when{font-size:var(--fs-md);font-weight:700;color:var(--text);letter-spacing:-.005em;line-height:1.3}
#rr-dvic-modal .dvic-card-when.dim{color:var(--text-subtle)}
#rr-dvic-modal .dvic-card-who{font-size:var(--fs-xs);color:var(--text-subtle);margin-top:3px;line-height:1.4}
#rr-dvic-modal .dvic-prev-row{display:flex;align-items:center;gap:var(--s-2-5);margin-top:var(--s-2-5)}
#rr-dvic-modal .dvic-prev-thumb{width:64px;height:48px;border-radius:var(--r-md);overflow:hidden;border:1px solid var(--border);flex:0 0 auto;background:var(--canvas);display:flex;align-items:center;justify-content:center}
#rr-dvic-modal .dvic-prev-thumb img{width:100%;height:100%;object-fit:cover}
#rr-dvic-modal .dvic-prev-thumb svg{color:var(--text-subtle)}
#rr-dvic-modal .dvic-prev-meta{font-size:var(--fs-xs);color:var(--text);line-height:1.4;min-width:0}
#rr-dvic-modal .dvic-prev-link{font-size:var(--fs-xs);color:var(--accent-text);font-weight:600;margin-top:6px;display:inline-block}
#rr-dvic-modal .dvic-cur-tag{margin-top:var(--s-2-5);align-self:flex-start;display:inline-flex;align-items:center;gap:5px;padding:3px 9px;border-radius:var(--r-pill);background:var(--accent-soft);color:var(--accent-text);font-size:var(--fs-xs);font-weight:700}
/* AI Review Summary card — tinted to the AI status. */
#rr-dvic-modal .dvic-ai-card{position:relative;padding:var(--s-3-5) var(--s-4);border-radius:var(--r-lg);border:1px solid transparent;box-shadow:var(--shadow-xs);display:flex;flex-direction:column;gap:var(--s-2)}
#rr-dvic-modal .dvic-ai-card.clean   {background:rgba(22,163,74,.06);border-color:rgba(22,163,74,.20)}
#rr-dvic-modal .dvic-ai-card.flagged {background:rgba(220,38,38,.06);border-color:rgba(220,38,38,.22)}
#rr-dvic-modal .dvic-ai-card.pending {background:var(--canvas);border-color:var(--border)}
#rr-dvic-modal .dvic-ai-card.error   {background:var(--amber-soft);border-color:var(--amber-border)}
#rr-dvic-modal .dvic-ai-card .eyebrow{display:flex;align-items:center;gap:7px;font-size:var(--fs-xs);font-weight:700;color:var(--text-muted);letter-spacing:.04em;text-transform:uppercase}
#rr-dvic-modal .dvic-ai-card .pill{display:inline-flex;align-items:center;padding:2px var(--s-2);border-radius:var(--r-pill);font-size:var(--fs-xs);font-weight:700;letter-spacing:.04em;text-transform:uppercase}
#rr-dvic-modal .dvic-ai-card.clean   .pill{background:rgba(22,163,74,.18);color:#15803D}
#rr-dvic-modal .dvic-ai-card.flagged .pill{background:rgba(220,38,38,.18);color:#991B1B}
#rr-dvic-modal .dvic-ai-card.pending .pill{background:var(--surface);color:var(--text-muted);border:1px solid var(--border)}
#rr-dvic-modal .dvic-ai-card.error   .pill{background:rgba(245,158,11,.20);color:var(--amber-dark)}
#rr-dvic-modal .dvic-ai-card .summary{font-size:var(--fs-md);color:var(--text);line-height:1.5}
#rr-dvic-modal .dvic-ai-card .summary.dim{color:var(--text-subtle)}
#rr-dvic-modal .dvic-ai-card .meta{font-size:var(--fs-xs);color:var(--text-subtle)}
#rr-dvic-modal .dvic-ai-card .meta b{color:var(--text);font-weight:600}
#rr-dvic-modal .dvic-ai-card .expand{appearance:none;background:transparent;border:0;cursor:pointer;padding:0;font:inherit;font-size:var(--fs-xs);font-weight:600;color:var(--accent-text);align-self:flex-start;margin-top:2px}
#rr-dvic-modal .dvic-ai-card .expand:hover{text-decoration:underline}
#rr-dvic-modal .dvic-ai-findings{margin:6px 0 0;padding-left:18px;font-size:var(--fs-sm);color:var(--text);line-height:1.55;display:flex;flex-direction:column;gap:3px}
/* Current inspection photos section */
#rr-dvic-modal .dvic-photos-section{margin-bottom:var(--s-4)}
#rr-dvic-modal .dvic-photos-head{display:flex;align-items:center;justify-content:space-between;gap:var(--s-2);margin-bottom:var(--s-2-5)}
#rr-dvic-modal .dvic-photos-title{font-size:var(--fs-sm);font-weight:700;color:var(--text);letter-spacing:-.005em}
#rr-dvic-modal .dvic-photos-count{font-size:var(--fs-xs);color:var(--text-subtle);font-weight:500}
#rr-dvic-modal .dvic-strip{display:grid;grid-template-columns:repeat(5,1fr);gap:var(--s-2)}
/* "View in comparison mode" toggle bar — sits under the current
   photo strip; expands a paired prev/current grid below. */
#rr-dvic-modal .dvic-compare-toggle{
  appearance:none;background:var(--canvas);border:1px solid var(--border);border-radius:var(--r-md);
  margin-top:var(--s-2-5);padding:10px var(--s-3-5);width:100%;cursor:pointer;
  display:flex;align-items:center;gap:var(--s-2);font:inherit;
  font-size:var(--fs-sm);font-weight:600;color:var(--text);
  transition:background var(--t-fast),border-color var(--t-fast);
}
#rr-dvic-modal .dvic-compare-toggle:hover{background:var(--surface-hover);border-color:var(--border-strong)}
#rr-dvic-modal .dvic-compare-toggle svg{color:var(--text-muted);flex:0 0 auto}
#rr-dvic-modal .dvic-compare-sub{font-weight:500;color:var(--text-subtle);font-size:var(--fs-xs);margin-left:auto}
#rr-dvic-modal .dvic-compare-toggle[aria-expanded="true"]{background:var(--accent-soft);border-color:var(--accent-border);color:var(--accent-text)}
#rr-dvic-modal .dvic-compare-toggle[aria-expanded="true"] svg{color:var(--accent-text)}
#rr-dvic-modal .dvic-compare-toggle[aria-expanded="true"] .dvic-compare-sub{color:var(--accent-text);opacity:.78}
#rr-dvic-modal .dvic-compare-pairs{display:flex;flex-direction:column;gap:var(--s-2-5);margin-top:var(--s-3)}
#rr-dvic-modal .dvic-compare-pairs[hidden]{display:none}
#rr-dvic-modal .dvic-compare-row{
  display:grid;grid-template-columns:1fr 22px 1fr;gap:var(--s-2-5);align-items:center;
}
#rr-dvic-modal .dvic-compare-row .dvic-thumb{cursor:zoom-in}
#rr-dvic-modal .dvic-compare-sep{display:flex;align-items:center;justify-content:center;color:var(--text-subtle)}
@media (max-width:680px){
  #rr-dvic-modal .dvic-compare-row{grid-template-columns:1fr;gap:var(--s-2)}
  #rr-dvic-modal .dvic-compare-sep{display:none}
}
@media (max-width:980px){
  #rr-dvic-modal .dvic-top{grid-template-columns:1fr 1fr}
  #rr-dvic-modal .dvic-ai-card{grid-column:1/-1}
  #rr-dvic-modal .dvic-strip{grid-template-columns:repeat(3,1fr)}
}
/* Inspection details block */
#rr-dvic-modal .dvic-details{border:1px solid var(--border);border-radius:var(--r-lg);background:var(--surface);box-shadow:var(--shadow-xs);margin-bottom:var(--s-4);overflow:hidden}
#rr-dvic-modal .dvic-details-head{padding:var(--s-3) var(--s-4);border-bottom:1px solid var(--border-subtle);font-size:var(--fs-sm);font-weight:700;color:var(--text)}
#rr-dvic-modal .dvic-details-row{display:grid;grid-template-columns:140px 1fr;align-items:center;gap:var(--s-3);padding:11px var(--s-4)}
#rr-dvic-modal .dvic-details-row + .dvic-details-row{border-top:1px solid var(--border-subtle)}
#rr-dvic-modal .dvic-details-label{font-size:var(--fs-xs);font-weight:600;color:var(--text-subtle);letter-spacing:.02em}
#rr-dvic-modal .dvic-details-value{font-size:var(--fs-sm);color:var(--text);font-weight:500;word-break:break-word}
#rr-dvic-modal .dvic-details-value .dim{color:var(--text-subtle);font-weight:400}
#rr-dvic-modal .dvic-thumb{position:relative;display:block;width:100%;aspect-ratio:4/3;border-radius:var(--r-md);overflow:hidden;border:1px solid var(--border);background:var(--canvas);cursor:zoom-in;transition:border-color var(--t-fast), transform var(--t-fast)}
#rr-dvic-modal .dvic-thumb:hover{border-color:var(--border-strong);transform:translateY(-1px)}
#rr-dvic-modal .dvic-thumb img{width:100%;height:100%;object-fit:cover;display:block}
#rr-dvic-modal .dvic-thumb.missing{display:flex;align-items:center;justify-content:center;color:var(--text-subtle);font-size:22px;aspect-ratio:4/3;cursor:default}
#rr-dvic-modal .dvic-thumb.missing:hover{transform:none;border-color:var(--border)}
#rr-dvic-modal .dvic-thumb .ix{position:absolute;left:6px;bottom:6px;background:rgba(15,23,42,.75);color:#fff;font-size:var(--fs-xs);font-weight:700;padding:2px 8px;border-radius:var(--r-sm)}
#rr-dvic-modal .dvic-empty{font-size:var(--fs-sm);color:var(--text-subtle);padding:var(--s-3-5) var(--s-3);border:1px dashed var(--border);border-radius:var(--r-md);background:var(--canvas)}
#rr-dvic-modal .dvic-checklist{border:1px solid var(--border);border-radius:var(--r-lg);padding:var(--s-3) var(--s-4);background:var(--surface);box-shadow:var(--shadow-xs)}
#rr-dvic-modal .dvic-checklist-head{display:flex;align-items:center;justify-content:space-between;gap:var(--s-2);flex-wrap:wrap}
#rr-dvic-modal .dvic-checklist-title{font-size:var(--fs-sm);font-weight:700;color:var(--text);letter-spacing:-.005em}
#rr-dvic-modal .dvic-checklist-title.warn{color:var(--amber-dark)}
#rr-dvic-modal .dvic-ai{border:1px solid var(--border);border-radius:var(--r-lg);padding:var(--s-3-5) var(--s-4);background:var(--canvas)}
#rr-dvic-modal .dvic-ai-h{display:flex;align-items:center;gap:var(--s-2);flex-wrap:wrap;font-size:11.5px}
#rr-dvic-modal .sev-pill{display:inline-flex;align-items:center;padding:2px var(--s-2-5);border-radius:var(--r-pill);font-size:10.5px;font-weight:700;letter-spacing:.05em;text-transform:uppercase}
#rr-dvic-modal .dvic-ai-sum{margin:var(--s-2) 0 0;font-size:var(--fs-md);color:var(--text);line-height:1.55}
#rr-dvic-modal .review{border-top:1px dashed var(--border);padding-top:var(--s-3-5);display:flex;flex-direction:column;gap:var(--s-2)}
#rr-dvic-modal .review label{font-size:11.5px;font-weight:600;color:var(--text-subtle)}
#rr-dvic-modal .review textarea{width:100%;min-height:64px;font:inherit;font-size:var(--fs-sm);padding:var(--s-2) var(--s-2-5);border:1px solid var(--border);border-radius:var(--r-md);background:var(--surface);resize:vertical;transition:border-color var(--t-fast), box-shadow var(--t-fast)}
#rr-dvic-modal .review textarea:focus{outline:none;border-color:var(--accent);box-shadow:var(--ring-focus)}
#rr-dvic-modal .review-state{font-size:11.5px;color:var(--text-subtle)}
#rr-dvic-modal .review-state b{text-transform:capitalize}
/* Initial loading state — proper skeleton that mirrors the
   final 3-card + photo-grid layout so the modal doesn't visibly
   reflow when the RPC + photo-signing finish. */
#rr-dvic-modal .dvic-loading{display:flex;flex-direction:column;gap:var(--s-4)}
#rr-dvic-modal .dvic-loading-top{display:grid;grid-template-columns:1fr 1fr 1.25fr;gap:var(--s-3)}
#rr-dvic-modal .dvic-loading-card{
  border:1px solid var(--border);border-radius:var(--r-lg);
  padding:var(--s-3-5) var(--s-4);background:var(--surface);
  display:flex;flex-direction:column;gap:var(--s-2);min-height:88px;
}
#rr-dvic-modal .dvic-loading-photos{
  display:grid;grid-template-columns:repeat(5,1fr);gap:var(--s-2);
}
#rr-dvic-modal .dvic-loading-photos .rr-skel{aspect-ratio:4/3;border-radius:var(--r-md)}
@media (max-width:980px){
  #rr-dvic-modal .dvic-loading-top{grid-template-columns:1fr 1fr}
  #rr-dvic-modal .dvic-loading-photos{grid-template-columns:repeat(3,1fr)}
}

/* ── Recognition row · shift edit modal ─────────────────────────── */
.rr-shift-edit-recognition{
  margin-top:4px;
  padding:8px 10px;
  background:var(--sch-surface-2, #F9FAFB);
  border:1px solid var(--sch-line);
  border-radius:6px;
}
.rr-shift-edit-recognition-row{
  display:flex;align-items:center;justify-content:space-between;gap:10px;
}
.rr-shift-edit-recognition-label{
  font-size:10px;font-weight:700;color:var(--text-subtle);
  text-transform:uppercase;letter-spacing:.06em;
}
.rr-shift-edit-recognition-help{
  font-size:12px;color:var(--text-muted);line-height:1.4;margin-top:2px;
}

/* ── Kudos quick-send modal ────────────────────────────────────────
   Triggered from the Schedule ribbon's Kudos icon (and the per-shift
   Recognition section, future). Calm centered card, single primary
   send button, quick-pick reason chips. Ambient — not a celebration
   surface; that lives in the driver app. */
.rr-kudos-overlay{
  position:fixed;inset:0;z-index:9999;
  /* Transparent, no blur — the card just floats over the page (it opens
     anchored near the Kudos button). The full-screen layer only catches
     outside-clicks to close. */
  background:transparent;
  display:flex;align-items:center;justify-content:center;
  padding:var(--s-6);
}
.rr-kudos-overlay .rr-kudos-card{
  background:#fff;
  border:1px solid var(--sch-line, var(--border));
  border-radius:12px;
  max-width:520px;width:100%;max-height:88vh;
  display:flex;flex-direction:column;
  box-shadow:0 8px 32px -8px rgba(15,23,42,.22),
             0 2px 4px rgba(15,23,42,.04);
  font-family:inherit;
}
.rr-kudos-overlay .rr-kudos-head{
  display:flex;align-items:flex-start;justify-content:space-between;
  gap:var(--s-3);
  padding:14px 18px;
  border-bottom:1px solid var(--sch-line, var(--border));
  background:var(--sch-surface-2, #F9FAFB);
  border-radius:12px 12px 0 0;
}
.rr-kudos-overlay .rr-kudos-eyebrow{
  font-size:11px;font-weight:700;color:var(--text-subtle);
  text-transform:uppercase;letter-spacing:.06em;
}
.rr-kudos-overlay .rr-kudos-title{
  font-size:15px;font-weight:600;color:var(--text);
  letter-spacing:-.005em;margin-top:3px;
}
.rr-kudos-overlay .rr-kudos-close{
  background:none;border:0;cursor:pointer;
  color:var(--text-muted);
  padding:4px;border-radius:6px;line-height:0;
  display:inline-flex;align-items:center;justify-content:center;
  transition:background var(--t-fast, 150ms), color var(--t-fast, 150ms);
}
.rr-kudos-overlay .rr-kudos-close:hover{
  background:rgba(15,23,42,.06);color:var(--text);
}
.rr-kudos-overlay .rr-kudos-body{
  padding:14px 18px 16px;
  overflow-y:auto;
  display:flex;flex-direction:column;gap:14px;
}
.rr-kudos-overlay .rr-kudos-field{
  display:flex;flex-direction:column;gap:6px;
}
.rr-kudos-overlay .rr-kudos-label{
  font-size:10px;font-weight:700;color:var(--text-subtle);
  text-transform:uppercase;letter-spacing:.06em;
}
.rr-kudos-overlay .rr-kudos-label-hint{
  color:var(--text-subtle);font-weight:500;text-transform:none;letter-spacing:0;
  font-size:10px;margin-left:4px;
}
.rr-kudos-overlay .rr-kudos-driver-locked{
  font-size:13px;font-weight:600;color:var(--text);
  padding:7px 10px;
  background:var(--sch-surface-2, #F9FAFB);
  border:1px solid var(--sch-line);
  border-radius:6px;
}
/* Milestone preset summary · replaces the reason-chip grid when
   the modal is opened from a Send-note pill. Shows the locked
   message title + a small hint that the note below is editable. */
.rr-kudos-overlay .rr-kudos-preset-summary{
