          /* A · Identity — single-line dense row: avatar | name | email | pills */
          #view-pipeline .pa-zone-identity{display:flex;gap:8px;align-items:center}
          #view-pipeline .pa-zone-identity .pa-card-avatar{width:28px;height:28px;flex:0 0 auto;font-size:11px}
          #view-pipeline .pa-id-main{min-width:0;display:flex;flex-direction:column;gap:0}
          #view-pipeline .pa-zone-identity .pa-card-name{
            font-size:13px;font-weight:600;color:#111827;line-height:1.2;
            white-space:nowrap;overflow:hidden;text-overflow:ellipsis;
          }
          #view-pipeline .pa-id-meta,
          #view-pipeline .pa-id-email{
            font-size:11px;color:#6B7280;line-height:1.25;
            white-space:nowrap;overflow:hidden;text-overflow:ellipsis;
          }
          #view-pipeline .pa-id-meta{margin-top:0}
          /* Hide via-Indeed line; the source still appears in the
             expanded view. Keep only email under the name. */
          #view-pipeline .pa-id-meta{display:none}
          #view-pipeline .pa-id-email{margin-top:0}
          /* Pills inline at the end of the email row — tightest. */
          #view-pipeline .pa-id-pills{display:inline-flex;flex-wrap:nowrap;gap:4px;margin-top:2px}
          #view-pipeline .pa-id-pills .pa-stage-pill,
          #view-pipeline .pa-id-pills .pa-card-tag{font-size:10px;padding:1px 5px;line-height:1.25}
          /* B · Process timeline — horizontal dot strip. Done steps
             are color-only (no label); current step shows label
             inline to the right of its dot. Connectors are short
             1px lines between nodes. */
          #view-pipeline .pa-row-v3 .pa-steps{display:flex;align-items:center;width:100%;gap:0}
          /* ── Milestone stepper · Applied → Screening invite sent → Screening
                → Interview → Hired. Filled+coloured behind/at the current step,
                outline ahead; connector fills up to the current node. ── */
          #view-pipeline .pa-mstep{display:flex;align-items:flex-start;width:100%}
          #view-pipeline .pa-mstep-item{
            flex:1 1 0;min-width:0;position:relative;
            display:flex;flex-direction:column;align-items:center;text-align:center;
          }
          /* connector line into each node (not the first) */
          /* Shrunk + muted into a quiet progress track so the stage chip leads:
             smaller dots, no per-step dates, reached steps a calm slate (not
             green/blue) that recedes behind the chip. */
          #view-pipeline .pa-mstep-item:not(:first-child)::before{
            content:"";position:absolute;top:9px;left:-50%;width:100%;height:2px;
            background:var(--border-strong,#CBD5E1);z-index:0;
          }
          #view-pipeline .pa-mstep-item.is-reached:not(:first-child)::before{background:#94A3B8}
          #view-pipeline .pa-mstep-dot{
            position:relative;z-index:1;width:20px;height:20px;border-radius:50%;
            display:flex;align-items:center;justify-content:center;
            background:var(--surface,#fff);border:1.5px solid var(--border-strong,#CBD5E1);
            color:var(--text-subtle,#94A3B8);box-sizing:border-box;
          }
          #view-pipeline .pa-mstep-dot svg{width:11px;height:11px}
          #view-pipeline .pa-mstep-item.is-done .pa-mstep-dot{background:#64748B;border-color:#64748B;color:#fff}
          #view-pipeline .pa-mstep-item.is-current .pa-mstep-dot{
            background:#475569;border-color:#475569;color:#fff;
          }
          /* Labels + dates dropped — the stage chip names the stage, so the
             stepper is just a compact dot-only progress track. */
          #view-pipeline .pa-mstep-label{display:none}
          #view-pipeline .pa-mstep-date{display:none}
          /* Hold the dot-track to a compact width on the left of the zone so it
             reads as a small progress indicator, not a full-width bar. */
          #view-pipeline .pa-row-v3 .pa-steps{justify-content:center}
          #view-pipeline .pa-mstep{max-width:300px}
          /* Stage status second line — the recommended next step, muted under
             the stage chip (status + what-to-do, like the risk card). */
          #view-pipeline .pa-stage-next{font-size:12px;font-weight:500;color:var(--text-muted);margin-top:3px;line-height:1.25}
          /* Decline · a visible secondary action (no longer buried in ⋯). */
          #view-pipeline .pa-btn-decline{
            display:inline-flex;align-items:center;gap:6px;
            padding:7px 12px;border-radius:8px;border:1px solid var(--border);
            background:var(--surface,#fff);color:#B42318;font-size:13px;font-weight:600;
            cursor:pointer;white-space:nowrap;
          }
          #view-pipeline .pa-btn-decline:hover{background:#FEF2F2;border-color:#FECACA}
          #view-pipeline .pa-tl-step{
            display:flex;flex-direction:row;align-items:center;text-align:left;
            flex:0 0 auto;gap:4px;
          }
          #view-pipeline .pa-tl-node{
            width:14px;height:14px;border-radius:50%;flex:0 0 auto;
            display:flex;align-items:center;justify-content:center;
            background:#F3F4F6;color:#9CA3AF;
          }
          #view-pipeline .pa-tl-node svg{width:8px;height:8px}
          #view-pipeline .pa-tl-step.is-done .pa-tl-node{background:#DFF6DD;color:#16A34A}
          #view-pipeline .pa-tl-step.is-current .pa-tl-node{
            background:var(--sch-blue-soft,rgba(37,99,235,.08));color:var(--accent);
            box-shadow:0 0 0 2px rgba(37,99,235,.12);
          }
          #view-pipeline .pa-tl-pulse{width:5px;height:5px;border-radius:50%;background:currentColor}
          /* Labels: hide for done steps (state is self-evident from
             the green check), show inline for current step. */
          #view-pipeline .pa-tl-step.is-done .pa-tl-label,
          #view-pipeline .pa-tl-step.is-done .pa-tl-time{display:none}
          #view-pipeline .pa-tl-step.is-pending .pa-tl-label,
          #view-pipeline .pa-tl-step.is-pending .pa-tl-time{display:none}
          #view-pipeline .pa-tl-label{
            font-size:11px;font-weight:600;color:#111827;line-height:1.2;white-space:nowrap;
          }
          #view-pipeline .pa-tl-step.is-pending{opacity:.5}
          #view-pipeline .pa-tl-time{display:none}
          #view-pipeline .pa-tl-conn{
            flex:1 1 auto;min-width:12px;height:1px;background:var(--border);margin:0 4px;
          }
          #view-pipeline .pa-tl-empty{font-size:12px;color:#9CA3AF}
          /* C · Action zone — the screening workflow surface.
             Top row: the loud "Review video" CTA, the advance button,
             and a quiet decline. Bottom row: ghost contact icons. */
          #view-pipeline .pa-zone-action{
            display:flex;flex-direction:column;align-items:stretch;
            /* Top-anchored so the buttons hold a fixed position no
               matter how tall the identity/timeline zones grow. */
            justify-content:flex-start;gap:10px;
            /* Set apart as a quietly recessed neutral workflow surface,
               divided from the timeline by a hairline. The accent now
               lives only in the primary CTA, not a blue panel wash. */
            background:var(--canvas);
            border-left:1px solid var(--border);
          }
          /* V4 action zone · stacked workflow buttons (Fluent hierarchy:
             strong primary, tertiary utility). The CTA, Review video, and
             Decline each take the full column width so they read as one
             symmetric, same-width stack; the quiet ⋯ overflow tucks small
             at the bottom-right below them. Operator asked for the Decline
             to line up flush with the CTA above it. */
          #view-pipeline .pa-zone-action-v4{
            flex-direction:column;align-items:stretch;gap:8px;
          }
          #view-pipeline .pa-zone-action-v4 .pa-btn-advance,
          #view-pipeline .pa-zone-action-v4 .pa-btn-video,
          #view-pipeline .pa-zone-action-v4 .pa-btn-decline{
            flex:0 0 auto;width:100%;min-width:0;justify-content:center;margin-right:0;
          }
          #view-pipeline .pa-zone-action-v4 .pa-act-more{
            flex:0 0 auto;align-self:flex-end;
          }
          /* Review video · secondary action that sits next to the
             primary CTA on screened applicants. Subtle Fluent
             outline button — clear it's a button but visually
             quieter than the primary advance. */
          #view-pipeline .pa-btn-video{
            appearance:none;cursor:pointer;font:inherit;text-decoration:none;
            display:inline-flex;align-items:center;gap:5px;
            flex:0 0 auto;height:24px;padding:0 10px;
            background:#fff;border:1px solid var(--border-strong);border-radius:4px;
            color:var(--text);font-size:12px;font-weight:600;line-height:1;
            transition:background var(--t-fast),border-color var(--t-fast),color var(--t-fast);
          }
          #view-pipeline .pa-btn-video:hover{
            background:#F3F8FE;border-color:var(--accent);color:var(--accent);
          }
          #view-pipeline .pa-btn-video:focus-visible{
            outline:none;border-color:var(--accent);box-shadow:0 0 0 2px rgba(37,99,235,.30);
          }
          #view-pipeline .pa-btn-video svg{width:11px;height:11px;flex:0 0 auto}
          #view-pipeline .pa-act-more{
            appearance:none;cursor:pointer;font:inherit;
            display:inline-flex;align-items:center;justify-content:center;
            flex:0 0 28px;width:28px;height:28px;padding:0;
            background:transparent;border:0;border-radius:4px;
            color:var(--text-subtle);
            transition:background var(--t-fast),color var(--t-fast);
          }
          #view-pipeline .pa-act-more:hover{
            background:rgba(15,23,42,.06);color:var(--text);
          }
          #view-pipeline .pa-act-more:focus-visible{
            outline:none;background:rgba(15,23,42,.06);color:var(--text);
            box-shadow:0 0 0 2px rgba(37,99,235,.30);
          }
          #view-pipeline .pa-act-more svg{width:16px;height:16px;flex:0 0 auto}
          /* Overflow menu rows · Fluent menu-item layout (icon · label / sub). */
          .pa-pop.pa-pop-menu{
            padding:6px;min-width:240px;
          }
          .pa-pop-mi{
            appearance:none;cursor:pointer;font:inherit;width:100%;text-align:left;
            display:flex;align-items:center;gap:10px;
            padding:8px 10px;border-radius:6px;
            background:transparent;border:0;color:var(--text);
            transition:background var(--t-fast);
          }
          .pa-pop-mi:hover:not(:disabled){background:var(--canvas)}
          .pa-pop-mi:disabled,.pa-pop-mi.is-disabled{opacity:.55;cursor:not-allowed}
          .pa-pop-mi-icon{
            width:24px;height:24px;flex:0 0 auto;
            display:inline-flex;align-items:center;justify-content:center;
            color:var(--text-muted);
          }
          .pa-pop-mi-body{display:flex;flex-direction:column;min-width:0;gap:1px}
          .pa-pop-mi-label{font-size:var(--fs-sm);font-weight:600;color:var(--text);line-height:1.25}
          .pa-pop-mi-sub{font-size:var(--fs-xs);color:var(--text-subtle);line-height:1.25;
            white-space:nowrap;overflow:hidden;text-overflow:ellipsis;
          }
          #view-pipeline .pa-act-row{
            display:flex;align-items:center;gap:8px;
            flex-wrap:nowrap;justify-content:flex-end;width:100%;
          }
          /* Review video — Fluent primary; the screening centrepiece. */
          #view-pipeline .pa-btn-video{
            position:relative;
            display:inline-flex;align-items:center;justify-content:center;gap:7px;
            flex:1 1 0;min-width:0;
            height:32px;padding:0 14px;border-radius:4px;
            font-family:inherit;font-size:13.5px;font-weight:600;
            white-space:nowrap;cursor:pointer;
            /* Subtle AI cue · blue-led gradient drifting to a soft violet.
               Noticeable on a look (this is a special "review the video"
               action) without shouting. Calms to a plain outline once the
               video's been watched (.is-watched below). */
            background:linear-gradient(120deg,#1D4ED8 0%,#2563EB 55%,#3B82F6 100%);
            color:#fff;border:1px solid transparent;
            box-shadow:0 1px 2px rgba(11,60,120,.22);
            transition:background var(--t-fast),border-color var(--t-fast),box-shadow var(--t-fast),filter var(--t-fast);
          }
          #view-pipeline .pa-btn-video:hover{filter:brightness(1.06) saturate(1.05)}
          #view-pipeline .pa-btn-video:active{filter:brightness(.95)}
          #view-pipeline .pa-btn-video:focus-visible{outline:none;box-shadow:0 0 0 2px #fff,0 0 0 4px #2563EB}
          #view-pipeline .pa-btn-video svg{flex:0 0 auto}
          /* Unwatched marker — Fluent red dot, white-ringed. */
          #view-pipeline .pa-btn-video-dot{
            position:absolute;top:-5px;right:-5px;
            width:12px;height:12px;border-radius:50%;
            background:#DC2626;border:2px solid #fff;
            box-shadow:0 0 0 1px rgba(15,23,42,.06);
          }
          /* Reviewed — calm secondary, no dot. */
          #view-pipeline .pa-btn-video.is-watched{
            background:#fff;color:#2563EB;border-color:#D1D5DB;box-shadow:none;
          }
          #view-pipeline .pa-btn-video.is-watched:hover{background:#F5F9FD;border-color:#2563EB}
          /* Advance — secondary by default; goes primary once no
             unwatched video is competing for the operator's eye. */
          #view-pipeline .pa-btn-advance{
            display:inline-flex;align-items:center;justify-content:center;gap:5px;
            flex:1 1 0;min-width:0;
            height:24px;padding:0 10px;border-radius:4px;
            font-family:inherit;font-size:12px;font-weight:600;
            white-space:nowrap;cursor:pointer;
            background:#fff;color:#111827;border:1px solid #D1D5DB;
            transition:background var(--t-fast),border-color var(--t-fast),box-shadow var(--t-fast);
          }
          #view-pipeline .pa-btn-advance:hover{background:#F3F4F6;border-color:#C7C7C7}
          #view-pipeline .pa-btn-advance:focus-visible{outline:none;box-shadow:0 0 0 2px #fff,0 0 0 4px #2563EB}
          #view-pipeline .pa-btn-advance .pa-adv-ico{color:#2563EB;flex:0 0 auto}
          /* Subtle primary · operator dialed back the loud solid-fill
             treatment. Soft blue tint background + brand-blue text +
             matching border. Still reads as the dominant action on
             the card (clearly the brand color, only colored element
             in the action zone) but no longer shouts. Hover deepens
             the tint slightly without flipping to solid. */
          #view-pipeline .pa-btn-advance.is-primary{
            background:rgba(37,99,235,.08);
            color:#2563EB;
            border-color:rgba(37,99,235,.22);
            box-shadow:none;
          }
          #view-pipeline .pa-btn-advance.is-primary:hover{
            background:rgba(37,99,235,.14);
            border-color:rgba(37,99,235,.34);
          }
          #view-pipeline .pa-btn-advance.is-primary .pa-adv-ico{color:#2563EB}
          /* Action needed · the ball is in the DSP's court (send the first
             screening invite, send the booking link). A touch stronger than a
             plain primary so these read as "do this" when scanning the list. */
          #view-pipeline .pa-btn-advance.is-action{
            background:rgba(37,99,235,.12);
            border-color:rgba(37,99,235,.34);
            color:#2563EB;
          }
          #view-pipeline .pa-btn-advance.is-action:hover{
            background:rgba(37,99,235,.18);border-color:rgba(37,99,235,.46);
          }
          #view-pipeline .pa-btn-advance.is-action .pa-adv-ico{color:#2563EB}
          /* Follow-up · waiting on the applicant (resend / reschedule nudge).
             Quiet neutral so it recedes next to the action-needed CTAs — the
             contrast is the signal. */
          #view-pipeline .pa-btn-advance.is-followup{
            background:#fff;
            border-color:#E3E3E3;
            color:var(--text-muted);
            box-shadow:none;
          }
          #view-pipeline .pa-btn-advance.is-followup .pa-adv-ico{color:var(--text-subtle)}
          #view-pipeline .pa-btn-advance.is-followup:hover{
            background:var(--canvas);border-color:#D1D5DB;color:var(--text);
          }
          /* Decline — a defined Fluent danger button: red-tinted surface
             + red glyph so the disposition action is unmistakable and
             stands clear of the neutral contact icons. */
          #view-pipeline .pa-act-decline{
            display:inline-flex;align-items:center;justify-content:center;
            width:32px;height:32px;border-radius:4px;flex:0 0 auto;
            background:#FDF3F2;border:1px solid #EFC9C6;color:#DC2626;
            cursor:pointer;transition:background var(--t-fast),border-color var(--t-fast),color var(--t-fast);
          }
          #view-pipeline .pa-act-decline:hover{background:#F8D7D4;border-color:#DC2626;color:#B91C1C}
          #view-pipeline .pa-act-decline:active{background:#F1C2BE}
          #view-pipeline .pa-act-decline:focus-visible{outline:none;box-shadow:0 0 0 2px #fff,0 0 0 4px #DC2626}
          /* Contact icons — defined Fluent icon buttons, one row down. */
          #view-pipeline .pa-act-contact{display:flex;align-items:center;gap:6px;width:100%}
          #view-pipeline .pa-act-contact .pa-icon-btn{
            background:#fff;border:1px solid #D1D5DB;box-shadow:none;
            flex:1 1 0;min-width:0;
            width:32px;height:32px;border-radius:4px;color:#374151;
            transition:background var(--t-fast),border-color var(--t-fast),color var(--t-fast);
          }
          #view-pipeline .pa-act-contact .pa-icon-btn:hover{background:#F3F4F6;border-color:#C7C7C7;color:#111827}
          #view-pipeline .pa-act-contact .pa-icon-btn:focus-visible{outline:none;box-shadow:0 0 0 2px #fff,0 0 0 4px #2563EB}
          #view-pipeline .pa-act-contact .pa-icon-btn.is-disabled{opacity:.4;cursor:not-allowed;pointer-events:none}
          @media (max-width:980px){
            #view-pipeline .pa-row-v3{grid-template-columns:1fr}
            #view-pipeline .pa-row-v3 .pa-zone-timeline{
              border-left:0;border-right:0;
              border-top:1px solid var(--surface-hover);border-bottom:1px solid var(--surface-hover);
            }
            #view-pipeline .pa-zone-action{
              align-items:flex-start;
              border-left:0;border-top:1px solid rgba(37,99,235,.22);
            }
            #view-pipeline .pa-act-row{justify-content:flex-start}
            #view-pipeline .pa-act-contact{justify-content:flex-start}
          }

          /* Popover surface shared by phone / notes / more icons. */
          .pa-pop{
            position:fixed;z-index:9998;background:var(--surface);
            border:1px solid var(--border-strong);border-radius:var(--r-lg);
            box-shadow:var(--shadow-pop);min-width:240px;max-width:340px;
            font-size:var(--fs-sm);overflow:hidden;
          }
          .pa-pop-h{
            padding:10px 14px;border-bottom:1px solid var(--border);
            font-size:var(--fs-xs);font-weight:700;color:var(--text-subtle);
            letter-spacing:.06em;text-transform:uppercase;
          }
          .pa-pop-row{
            display:flex;align-items:center;gap:10px;
            padding:9px 14px;width:100%;text-align:left;
            background:transparent;border:0;color:var(--text);
            font:inherit;font-size:var(--fs-sm);cursor:pointer;text-decoration:none;
          }
          .pa-pop-row:hover{background:var(--canvas)}
          .pa-pop-row + .pa-pop-row{border-top:1px solid var(--border-subtle)}
          .pa-pop-row-strong{font-weight:600;color:var(--text)}
          .pa-pop-row.is-danger{color:var(--red)}
          .pa-pop-row.is-danger:hover{background:var(--red-soft)}
          .pa-pop-notes{padding:10px 14px}
          .pa-pop-notes textarea{
            width:100%;min-height:140px;resize:vertical;padding:8px 10px;
            border:1px solid var(--border);border-radius:var(--r-md);
            font:inherit;font-size:var(--fs-sm);background:var(--canvas);color:var(--text);
          }
          .pa-pop-notes textarea:focus{outline:none;border-color:var(--accent);box-shadow:var(--ring-focus)}
          .pa-pop-status{
            font-size:var(--fs-xs);color:var(--text-subtle);
            margin-top:6px;font-variant-numeric:tabular-nums;
          }

          /* Expanded detail panel */
          .pa-detail{display:none;border-top:1px solid var(--border-subtle);padding:var(--s-5) var(--s-6) var(--s-5);background:var(--canvas)}
          .pa-detail-section + .pa-detail-section{margin-top:var(--s-5)}
          .pa-detail-section-meta{font-size:var(--fs-xs);color:var(--text-subtle);margin-top:6px;font-variant-numeric:tabular-nums}
          .pa-card.expanded .pa-detail{display:block}
          .pa-detail-grid{display:grid;grid-template-columns:1fr 1fr;gap:var(--s-6)}
          @media (max-width:840px){.pa-detail-grid{grid-template-columns:1fr}}
          .pa-detail-section-title{font-size:var(--fs-xs);font-weight:700;color:var(--text-subtle);letter-spacing:.08em;text-transform:uppercase;margin-bottom:10px}

          /* Timeline */
          .pa-timeline{display:flex;flex-direction:column;gap:0;position:relative}
          .pa-timeline-step{display:grid;grid-template-columns:24px 1fr auto;gap:var(--s-2-5);align-items:flex-start;padding:var(--s-2) 0;position:relative}
          .pa-timeline-step::before{content:"";position:absolute;left:11px;top:18px;bottom:-8px;width:2px;background:var(--border)}
          .pa-timeline-step:last-child::before{display:none}
          .pa-timeline-dot{width:24px;height:24px;border-radius:50%;background:var(--surface);border:2px solid var(--border);display:flex;align-items:center;justify-content:center;color:var(--text-subtle);position:relative;z-index:1}
          .pa-timeline-dot svg{width:11px;height:11px;stroke-width:2.5}
          .pa-timeline-step.done .pa-timeline-dot{background:var(--green);border-color:var(--green);color:var(--text-inverse)}
          .pa-timeline-step.current .pa-timeline-dot{background:var(--accent);border-color:var(--accent);color:var(--text-inverse)}
          .pa-timeline-label{font-size:var(--fs-md);color:var(--text);font-weight:500}
          .pa-timeline-step.pending .pa-timeline-label{color:var(--text-subtle)}
          .pa-timeline-time{font-size:var(--fs-xs);color:var(--text-subtle);font-variant-numeric:tabular-nums;white-space:nowrap}

          /* Video player placeholder */
          .pa-video{
            position:relative;aspect-ratio:16/9;
            background:linear-gradient(135deg,#1F2937,#0F172A);border-radius:var(--r-md);
            display:flex;align-items:center;justify-content:center;
            color:#fff;cursor:pointer;overflow:hidden;
          }
          .pa-video::after{content:"";position:absolute;inset:0;background:radial-gradient(circle at 30% 20%, rgba(19,130,219,.2), transparent 50%)}
          .pa-video-play{
            position:relative;z-index:1;
            width:48px;height:48px;border-radius:50%;
            background:rgba(255,255,255,.95);color:var(--text);
            display:flex;align-items:center;justify-content:center;
            transition:transform var(--t-fast);
          }
          .pa-video:hover .pa-video-play{transform:scale(1.05)}
          .pa-video-play svg{width:18px;height:18px;margin-left:2px}
