            #rr-ivcal .oc-await-name{font-size:13px;font-weight:600;color:var(--oc-ink);overflow:hidden;white-space:nowrap;text-overflow:ellipsis}
            #rr-ivcal .oc-await-sub{font-size:11px;color:var(--oc-sub);overflow:hidden;white-space:nowrap;text-overflow:ellipsis}
            #rr-ivcal .oc-await-send{flex:0 0 auto;appearance:none;border:1px solid var(--oc-colsep);background:var(--oc-surface);color:var(--oc-blue);font:inherit;font-size:11px;font-weight:600;padding:3px 8px;border-radius:5px;cursor:pointer;transition:background var(--t-fast),border-color var(--t-fast)}
            #rr-ivcal .oc-await-send:hover{background:rgba(37,99,235,.10);border-color:var(--oc-blue)}
            #rr-ivcal .oc-await-send:disabled{color:var(--oc-sub);cursor:default;background:var(--oc-surface);border-color:var(--oc-colsep)}
            #rr-ivcal .oc-await-more{display:block;width:100%;text-align:left;appearance:none;border:0;background:none;cursor:pointer;color:var(--oc-blue);font:inherit;font-size:12px;font-weight:600;padding:4px 6px;border-radius:5px}
            #rr-ivcal .oc-await-more:hover{background:var(--oc-hover)}
            #rr-ivcal .oc-await-empty{font-size:12px;color:var(--oc-sub);line-height:1.4;padding:2px 6px}
            /* Empty-state nudge — shown above the grid when no availability is set. */
            #rr-ivcal .oc-nudge{display:flex;align-items:center;gap:11px;margin:0 0 10px;padding:10px 12px;border:1px solid var(--oc-colsep);border-radius:8px;background:var(--oc-hover);color:var(--oc-ink)}
            #rr-ivcal .oc-nudge-ic{width:20px;height:20px;flex:0 0 auto;color:var(--oc-blue)}
            #rr-ivcal .oc-nudge-txt{display:flex;flex-direction:column;gap:1px;min-width:0;flex:1 1 auto}
            #rr-ivcal .oc-nudge-txt strong{font-size:13px;font-weight:700}
            #rr-ivcal .oc-nudge-txt span{font-size:12px;color:var(--oc-sub);line-height:1.35}
            #rr-ivcal .oc-nudge-cta{flex:0 0 auto;appearance:none;border:0;border-radius:6px;background:var(--oc-blue);color:#fff;font:inherit;font-size:13px;font-weight:600;padding:7px 13px;cursor:pointer}
            #rr-ivcal .oc-nudge-cta:hover{filter:brightness(.94)}
            #rr-ivcal .oc-nudge-x{flex:0 0 auto;appearance:none;border:0;background:none;color:var(--oc-sub);font-size:18px;line-height:1;cursor:pointer;padding:0 3px;border-radius:5px}
            #rr-ivcal .oc-nudge-x:hover{background:var(--oc-colsep);color:var(--oc-ink)}
            #rr-ivcal .oc-gcal-ico{display:inline-flex;align-items:center;justify-content:center;flex:0 0 auto}
            #rr-ivcal .oc-gcal-row .oc-cal-lbl{gap:7px}
            #rr-ivcal .oc-gcal-connect{display:inline-flex;align-items:center;gap:7px;width:100%;text-align:left;appearance:none;border:1px solid var(--border);background:var(--surface);color:var(--oc-ink);cursor:pointer;font:inherit;font-size:13px;padding:6px 9px;border-radius:6px;transition:background var(--t-fast),border-color var(--t-fast)}
            #rr-ivcal .oc-gcal-connect:hover{background:var(--oc-hover);border-color:var(--oc-blue)}
            #rr-ivcal .oc-gcal-err{font-size:11px;color:var(--red,#B91C1C);line-height:1.35;padding:2px 4px 0}
            /* In-dashboard interview workspace · inset from the left nav rail
               (240px expanded / 64px collapsed) so the nav stays visible. */
            #rr-ivroom{position:fixed;top:44px;left:240px;right:0;bottom:0;z-index:10000;background:var(--surface,#fff);display:flex;flex-direction:column;color:var(--text,#111)}
            .app:has(.sidebar.collapsed) ~ #rr-ivroom{left:64px}
            #rr-ivroom .ivr-top{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 20px;border-bottom:1px solid var(--border,#e5e7eb);flex:0 0 auto;background:var(--surface,#fff)}
            #rr-ivroom .ivr-bc{font-size:15px;color:var(--text,#111)}
            #rr-ivroom .ivr-bc-mut{color:var(--text-subtle,#6b7280);font-weight:500}
            #rr-ivroom .ivr-top-acts{display:flex;align-items:center;gap:8px}
            #rr-ivroom .ivr-btn{appearance:none;border:1px solid var(--border,#e5e7eb);background:var(--surface,#fff);color:var(--text,#111);cursor:pointer;font:inherit;font-size:13px;font-weight:600;padding:7px 13px;border-radius:8px}
            #rr-ivroom .ivr-btn:hover{background:var(--surface-hover,#f3f4f6)}
            #rr-ivroom .ivr-end{background:#1D4ED8;border-color:#1D4ED8;color:#fff}
            #rr-ivroom .ivr-end:hover{background:#1E40AF}
            /* Notes + Actions live in a left side panel; the video fills the rest. */
            #rr-ivroom .ivr-main{flex:1;min-height:0;display:flex;gap:16px;padding:16px 20px}
            #rr-ivroom .ivr-side{flex:0 0 360px;display:flex;flex-direction:column;gap:14px;overflow-y:auto;padding:2px}
            /* Enterprise ATS cards · clean white surfaces, light borders, minimal shadow. */
            #rr-ivroom .ivr-card{border:1px solid var(--border,#e5e7eb);border-radius:var(--r-lg);background:var(--surface,#fff);padding:14px 16px;box-shadow:0 1px 2px rgba(15,23,42,.04)}
            #rr-ivroom .ivr-card-h{display:flex;align-items:center;justify-content:space-between;font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:.04em;color:var(--text-subtle,#6b7280);margin-bottom:10px}
            #rr-ivroom .ivr-snap-top{display:flex;gap:12px;align-items:center}
            #rr-ivroom .ivr-snap-av{flex:0 0 auto;width:52px;height:52px;border-radius:50%;background:var(--accent-soft,#e0ecfb);color:var(--accent-text,#2563EB);font-weight:700;font-size:18px;display:flex;align-items:center;justify-content:center}
            #rr-ivroom .ivr-snap-name{font-weight:700;font-size:16px;color:var(--text,#111)}
            #rr-ivroom .ivr-snap-pos{font-size:13px;color:var(--text-subtle,#6b7280);margin:1px 0 5px}
            #rr-ivroom .ivr-snap-stage{display:inline-block;font-size:11px;font-weight:700;color:var(--oc-blue,#2563EB);background:var(--accent-soft,#EFF6FF);border:1px solid #cfe0f6;padding:2px 8px;border-radius:999px}
            #rr-ivroom .ivr-snap-grid{margin-top:12px;border-top:1px solid var(--border,#F3F4F6);padding-top:10px;display:flex;flex-direction:column;gap:7px}
            #rr-ivroom .ivr-score-row{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:5px 0}
            #rr-ivroom .ivr-score-cat{font-size:13px;color:var(--text,#111);font-weight:500}
            #rr-ivroom .ivr-stars{display:inline-flex;gap:2px}
            #rr-ivroom .ivr-star{appearance:none;border:0;background:none;cursor:pointer;font-size:17px;line-height:1;color:#d4d8df;padding:0 1px}
            #rr-ivroom .ivr-star.on{color:#F5B301}
            #rr-ivroom .ivr-star:hover{color:#f0c34d}
            #rr-ivroom .ivr-rec-h{font-size:12px;font-weight:700;color:var(--text,#111);margin:12px 0 8px;padding-top:10px;border-top:1px solid var(--border,#F3F4F6)}
            #rr-ivroom .ivr-recs{display:grid;grid-template-columns:1fr 1fr;gap:8px}
            #rr-ivroom .ivr-rec{display:flex;align-items:center;gap:7px;font-size:13px;color:var(--text,#111);border:1px solid var(--border,#e5e7eb);border-radius:7px;padding:7px 9px;cursor:pointer}
            #rr-ivroom .ivr-rec input{margin:0;accent-color:var(--oc-blue,#2563EB)}
            #rr-ivroom .ivr-rec.on{border-color:var(--oc-blue,#2563EB);background:var(--accent-soft,#EFF6FF);font-weight:600}
            #rr-ivroom .ivr-rec.strong_hire.on{border-color:#16A34A;background:#ecfdf3;color:#15803D}
            #rr-ivroom .ivr-rec.no_hire.on{border-color:#B91C1C;background:#fef2f2;color:#9b1c1c}
            #rr-ivroom .ivr-journey{flex:0 0 230px;position:relative;border:1px solid var(--border,#e5e7eb);border-radius:var(--r-lg);background:var(--surface,#fff);box-shadow:0 1px 2px rgba(15,23,42,.04);overflow:hidden;transition:flex-basis .18s ease}
            #rr-ivroom .ivr-journey.collapsed{flex-basis:26px}
            #rr-ivroom .ivr-journey.collapsed .ivr-jinner{display:none}
            #rr-ivroom .ivr-jtoggle{position:absolute;top:8px;left:6px;z-index:2;appearance:none;border:0;background:none;cursor:pointer;color:var(--text-subtle,#6b7280);font-size:14px;line-height:1;padding:2px 4px;border-radius:5px}
            #rr-ivroom .ivr-jtoggle:hover{background:var(--surface-hover,#f3f4f6)}
            #rr-ivroom .ivr-jinner{padding:14px 16px 14px 26px;height:100%;overflow-y:auto}
            #rr-ivroom .ivr-jrow{display:flex;gap:10px;align-items:flex-start;padding:9px 0;position:relative}
            #rr-ivroom .ivr-jrow:not(:last-child):before{content:"";position:absolute;left:8px;top:24px;bottom:-9px;width:2px;background:var(--border,#e5e7eb)}
            #rr-ivroom .ivr-jdot{flex:0 0 18px;width:18px;height:18px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:10px;font-weight:700;background:#F3F4F6;color:#9ca3af;z-index:1}
            #rr-ivroom .ivr-jdot.done{background:#dff3e7;color:#16A34A}
            #rr-ivroom .ivr-jdot.cur{background:var(--oc-blue,#2563EB);color:#fff}
            #rr-ivroom .ivr-jrow.cur .ivr-jlabel{color:var(--oc-blue,#2563EB);font-weight:700}
            #rr-ivroom .ivr-jlabel{font-size:13px;font-weight:600;color:var(--text,#111)}
            #rr-ivroom .ivr-jsub{font-size:11px;color:var(--text-subtle,#6b7280);margin-top:1px}
            #rr-ivroom .ivr-profile{flex:0 0 280px;border:1px solid var(--border,#e5e7eb);border-radius:12px;padding:18px;overflow-y:auto;background:var(--surface,#fff)}
            #rr-ivroom .ivr-av{width:72px;height:72px;border-radius:50%;background:var(--accent-soft,#e0ecfb);color:var(--accent-text,#2563EB);font-weight:700;font-size:24px;display:flex;align-items:center;justify-content:center;margin:0 auto 10px}
            #rr-ivroom .ivr-name{text-align:center;font-weight:700;font-size:18px}
            #rr-ivroom .ivr-status{display:block;text-align:center;font-size:12px;font-weight:600;color:#16A34A;margin-top:6px}
            #rr-ivroom .ivr-sec{margin-top:16px;border-top:1px solid var(--border,#F3F4F6);padding-top:12px}
            #rr-ivroom .ivr-sec-h{font-size:13px;font-weight:700;color:var(--text,#111);margin-bottom:8px}
            #rr-ivroom .ivr-row{font-size:13px;color:var(--accent-text,#2563EB);margin-bottom:4px;word-break:break-word}
            #rr-ivroom .ivr-row.ivr-mut,#rr-ivroom .ivr-mut{color:var(--text-subtle,#6b7280)}
            #rr-ivroom .ivr-kv{display:flex;justify-content:space-between;gap:10px;font-size:13px;color:var(--text-subtle,#6b7280);margin-bottom:6px}
            #rr-ivroom .ivr-kv b{color:var(--text,#111);font-weight:600;text-align:right}
            #rr-ivroom .ivr-fullbtn{margin-top:18px;width:100%;appearance:none;border:0;background:var(--oc-blue,#2563EB);color:#fff;font-weight:600;cursor:pointer;padding:10px;border-radius:8px;font-size:13px}
            #rr-ivroom .ivr-fullbtn:hover{background:var(--oc-blue-strong,#1D4ED8)}
            #rr-ivroom .ivr-video{flex:1;min-width:0;background:#0b0f17;border-radius:12px;overflow:hidden;position:relative}
            #rr-ivroom .ivr-video iframe{width:100%;height:100%;border:0;display:block}
            /* Maximize (in-app): the video fills the window; side panel + top
               bar hide and an Exit button overlays the corner. Reliable click
               (normal stacking) unlike native fullscreen over a cross-origin
               iframe. Stays below the 44px topbar so the window controls + the
               way back stay reachable. */
            #rr-ivroom.ivr-max{left:0}
            #rr-ivroom.ivr-max .ivr-top,#rr-ivroom.ivr-max .ivr-side{display:none}
            #rr-ivroom.ivr-max .ivr-main{padding:0}
            #rr-ivroom.ivr-max .ivr-video{border-radius:0}
            #rr-ivroom .ivr-fsexit{display:none}
            #rr-ivroom.ivr-max .ivr-fsexit{display:inline-flex;align-items:center;position:absolute;top:14px;right:14px;z-index:6;appearance:none;border:0;background:rgba(15,23,42,.82);color:#fff;font:inherit;font-size:13px;font-weight:600;cursor:pointer;padding:8px 14px;border-radius:8px}
            #rr-ivroom.ivr-max .ivr-fsexit:hover{background:rgba(15,23,42,.95)}
            #rr-ivroom .ivr-tabs{display:flex;gap:18px;border-bottom:1px solid var(--border,#F3F4F6)}
            #rr-ivroom .ivr-tab{appearance:none;border:0;background:none;cursor:pointer;font:inherit;font-size:14px;font-weight:600;color:var(--oc-blue,#2563EB);padding:2px 2px 8px;border-bottom:2px solid var(--oc-blue,#2563EB)}
            #rr-ivroom .ivr-col-h{font-size:13px;font-weight:700;margin-bottom:8px}
            #rr-ivroom .ivr-ed{min-height:120px;max-height:300px;overflow-y:auto;border:1px solid var(--border,#e5e7eb);border-radius:8px;padding:10px 12px;font:inherit;font-size:14px;line-height:1.5;color:var(--text,#111);background:var(--surface,#fff)}
            #rr-ivroom .ivr-ed:empty:before{content:attr(data-ph);color:var(--text-subtle,#9ca3af)}
            #rr-ivroom .ivr-ed:focus{outline:none;border-color:var(--oc-blue,#2563EB)}
            #rr-ivroom .ivr-tb{display:flex;align-items:center;gap:5px;margin-top:8px}
            #rr-ivroom .ivr-tb button{appearance:none;border:1px solid var(--border,#e5e7eb);background:var(--surface,#fff);cursor:pointer;border-radius:6px;width:28px;height:26px;font-size:12px;color:var(--text,#111)}
            #rr-ivroom .ivr-tb button:hover{background:var(--surface-hover,#f3f4f6)}
            #rr-ivroom .ivr-saved{font-size:12px;color:var(--green,#16A34A);font-weight:600;margin-right:6px}
            #rr-ivroom .ivr-save{appearance:none;border:0;background:var(--oc-blue,#2563EB);color:#fff;font-weight:600;cursor:pointer;border-radius:7px;padding:6px 14px;font-size:13px}
            #rr-ivroom .ivr-save:hover{background:var(--oc-blue-strong,#1D4ED8)}
            #rr-ivroom .ivr-save:disabled{opacity:.6;cursor:default}
            #rr-ivroom .ivr-chips{display:flex;flex-wrap:wrap;gap:8px}
            #rr-ivroom .ivr-chip{appearance:none;border:1px solid var(--border,#e5e7eb);background:var(--surface,#fff);cursor:pointer;font:inherit;font-size:12px;padding:7px 11px;border-radius:8px;color:var(--text,#111)}
            #rr-ivroom .ivr-chip:hover{background:var(--accent-soft,#EFF6FF);border-color:var(--oc-blue,#2563EB)}
            #rr-ivroom .ivr-acts{display:flex;flex-direction:column;gap:10px}
            #rr-ivroom .ivr-act{appearance:none;cursor:pointer;font:inherit;font-size:13px;font-weight:600;padding:11px 14px;border-radius:8px;text-align:center;border:1px solid}
            #rr-ivroom .ivr-act.ok{background:#ecfdf3;border-color:#a6e6c0;color:#15803D}
            #rr-ivroom .ivr-act.ok:hover{background:#d6f7e3}
            #rr-ivroom .ivr-act.info{background:#EFF6FF;border-color:#bcd6f5;color:#1E40AF}
            #rr-ivroom .ivr-act.info:hover{background:#dcebfb}
            #rr-ivroom .ivr-act.danger{background:#fef2f2;border-color:#f4c2c2;color:#9b1c1c}
            #rr-ivroom .ivr-act.danger:hover{background:#fde1e1}
            @media (max-width:1100px){
              #rr-ivroom{left:0}
              #rr-ivroom .ivr-main{flex-direction:column}
              #rr-ivroom .ivr-side{flex:0 0 auto;order:2}
              #rr-ivroom .ivr-video{min-height:46vh;order:1}
              #rr-ivroom .ivr-journey{flex:0 0 auto;order:3}
              #rr-ivroom .ivr-journey.collapsed{flex-basis:auto}
            }
            /* Add/Edit calendar dialog */
            .oc-caldlg-back{position:fixed;inset:0;z-index:10000;background:rgba(15,23,42,.32);display:flex;align-items:center;justify-content:center}
            .oc-caldlg{background:var(--surface);border:1px solid var(--border);border-radius:12px;box-shadow:0 24px 70px rgba(15,23,42,.36);width:min(380px,94vw);padding:18px 20px;font-family:"Inter","Segoe UI Variable","Segoe UI",system-ui,sans-serif}
            .oc-caldlg-h{font-size:16px;font-weight:700;color:var(--text);margin-bottom:14px}
            .oc-caldlg-f{display:flex;align-items:flex-start;gap:12px;margin-bottom:14px}
            .oc-caldlg-f>span{min-width:54px;font-size:13px;font-weight:600;color:var(--text-subtle);padding-top:7px}
            .oc-caldlg-f input{flex:1;padding:8px 10px;border:1px solid var(--border);border-radius:6px;font:inherit;background:var(--surface);color:var(--text)}
            .oc-caldlg-sw{display:flex;flex-wrap:wrap;gap:8px;flex:1}
            .oc-caldlg-sw .oc-sw{width:24px;height:24px;border-radius:6px;border:2px solid transparent;cursor:pointer;padding:0;outline:none}
            .oc-caldlg-sw .oc-sw.on{border-color:var(--text);box-shadow:0 0 0 2px var(--surface) inset}
            .oc-caldlg-acts{display:flex;justify-content:flex-end;gap:8px;margin-top:6px}
            .oc-caldlg-acts .oc-btn{appearance:none;cursor:pointer;font:inherit;font-size:13px;color:var(--text);background:var(--surface);border:1px solid var(--border);border-radius:6px;padding:6px 14px}
            .oc-caldlg-acts .oc-btn.pri{background:var(--oc-blue,#2563EB);border-color:var(--oc-blue,#2563EB);color:#fff;font-weight:600}
            .oc-caldlg-acts .oc-btn:disabled{opacity:.6;cursor:default}
            /* command bar */
            #rr-ivcal .oc-bar{display:flex;align-items:center;gap:8px;padding:13px 10px;border-bottom:1px solid var(--oc-line);background:var(--oc-surface-2);flex-wrap:wrap}
            #rr-ivcal .oc-btn{appearance:none;cursor:pointer;font:inherit;font-size:13px;color:var(--oc-ink);background:var(--oc-surface);border:1px solid var(--border);border-radius:6px;padding:4px 10px;display:inline-flex;align-items:center;gap:6px;line-height:1}
            #rr-ivcal .oc-btn:hover{background:var(--oc-hover)}
            #rr-ivcal .oc-btn.pri{background:var(--oc-blue);border-color:var(--oc-blue);color:#fff;font-weight:600}
            #rr-ivcal .oc-btn.pri:hover{background:var(--oc-blue-strong)}
            #rr-ivcal .oc-ico{width:26px;height:26px;padding:0;justify-content:center;font-size:15px}
            #rr-ivcal .oc-seg{display:inline-flex;border:1px solid var(--border);border-radius:6px;overflow:hidden}
            #rr-ivcal .oc-seg button{appearance:none;cursor:pointer;font:inherit;font-size:13px;color:var(--oc-ink);background:var(--oc-surface);border:0;border-left:1px solid var(--border);padding:4px 12px;line-height:1}
            #rr-ivcal .oc-seg button:first-child{border-left:0}
            #rr-ivcal .oc-seg button.on{background:var(--oc-blue);color:#fff;font-weight:600}
            #rr-ivcal .oc-zoom button{padding:4px 9px;font-size:15px;line-height:1;min-width:28px;justify-content:center}
            #rr-ivcal .oc-period{font-size:15px;font-weight:600;color:var(--oc-ink);margin:0 4px}
            #rr-ivcal .oc-sp{flex:1}
            #rr-ivcal .oc-search{display:flex;align-items:center;gap:6px;border:1px solid var(--border);border-radius:6px;padding:3px 8px;background:var(--oc-surface);color:var(--oc-sub);font-size:12px}
            #rr-ivcal .oc-search input{border:0;outline:0;font:inherit;font-size:12px;width:120px;background:transparent;color:var(--oc-ink)}
            #rr-ivcal .oc-filters{display:flex;align-items:center;gap:12px}
            #rr-ivcal .oc-filters label{display:inline-flex;align-items:center;gap:5px;font-size:12px;color:var(--oc-sub);cursor:pointer}
            #rr-ivcal .oc-filters .dot{width:9px;height:9px;border-radius:2px;display:inline-block}
            /* day/week grid */
            #rr-ivcal .oc-head{display:grid;grid-template-columns:50px repeat(var(--days),1fr);border-bottom:1px solid var(--oc-colsep);background:#fff;position:sticky;top:0;z-index:6}
            #rr-ivcal .oc-corner{border-right:1px solid var(--oc-colsep);background:#fff}
            #rr-ivcal .oc-dh{text-align:left;padding:7px 0 8px 12px;border-left:1px solid var(--oc-colsep);background:#fff;cursor:pointer}
            #rr-ivcal .oc-dh .dow{font-size:11px;font-weight:700;color:var(--text-muted);letter-spacing:.05em;text-transform:uppercase}
            #rr-ivcal .oc-dh .dn{font-size:21px;font-weight:700;color:var(--oc-ink);line-height:1.05;margin-top:2px}
            #rr-ivcal .oc-dh.today .dn{color:#fff;background:var(--oc-blue);width:28px;height:28px;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;margin-top:1px;font-size:17px}
            #rr-ivcal .oc-dh.today .dow{color:var(--oc-blue);font-weight:800}
            #rr-ivcal .oc-scroll{overflow-y:auto;height:580px}
            #rr-ivcal .oc-grid{display:grid;grid-template-columns:50px repeat(var(--days),1fr);position:relative}
            #rr-ivcal .oc-gutter{position:relative}
            #rr-ivcal .oc-hr{position:relative;height:var(--rh)}
            #rr-ivcal .oc-hr span{position:absolute;top:-7px;right:6px;font-size:11px;font-weight:600;color:var(--oc-time);font-variant-numeric:tabular-nums;background:var(--oc-surface);padding:0 1px}
