          .sep-review .sep-finding-label{font-size:var(--fs-sm);font-weight:600}
          .sep-review .sep-finding-detail{font-size:var(--fs-xs);color:var(--text-subtle)}
          .sep-review .sep-certify{
            display:flex;align-items:flex-start;gap:9px;margin-top:var(--s-4);
            padding:var(--s-3);border:1px solid var(--border);border-radius:var(--r-md);
            background:var(--canvas);font-size:var(--fs-sm);cursor:pointer;
          }
          .sep-review .sep-certify input{margin-top:2px;flex-shrink:0;accent-color:var(--accent)}

          /* Separation Readiness Review — intelligence step shown between
             the review form and packet generation. Reuses sep-review +
             the system tokens; adds the score / timeline / risk visuals. */
          .sep-review .rdy-intro{font-size:var(--fs-sm);color:var(--text-muted);margin:0 0 var(--s-2)}
          .sep-review .rdy-loading{padding:var(--s-8) 0;text-align:center;color:var(--text-subtle);font-size:var(--fs-sm)}
          .sep-review .rdy-head{
            display:flex;gap:var(--s-4);align-items:center;
            background:var(--canvas);border:1px solid var(--border);border-radius:var(--r-lg);padding:var(--s-4);
          }
          .sep-review .rdy-score-big{display:flex;align-items:baseline;gap:2px;flex-shrink:0;min-width:92px;justify-content:center}
          .sep-review .rdy-score-num{font-size:40px;font-weight:800;line-height:1;letter-spacing:-.02em}
          .sep-review .rdy-score-den{font-size:var(--fs-md);font-weight:600;color:var(--text-subtle)}
          .sep-review .rdy-score-meta{flex:1;min-width:0}
          .sep-review .rdy-rec{font-size:var(--fs-sm);color:var(--text);margin:7px 0 0;line-height:1.45}
          .sep-review .rdy-pill{
            display:inline-flex;align-items:center;font-size:var(--fs-xs);font-weight:700;
            padding:3px 10px;border-radius:var(--r-pill);text-transform:uppercase;letter-spacing:.04em;
          }
          .sep-review .rdy-pill-strong{background:var(--green-soft);color:var(--green-dark)}
          .sep-review .rdy-pill-moderate{background:var(--amber-soft);color:var(--amber-dark)}
          .sep-review .rdy-pill-weak{background:var(--red-soft);color:var(--red-dark)}
          .sep-review .rdy-subgrid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--s-2-5);margin-top:var(--s-3)}
          .sep-review .rdy-sub{background:var(--surface);border:1px solid var(--border);border-radius:var(--r-md);padding:var(--s-2-5) var(--s-3)}
          .sep-review .rdy-sub-top{display:flex;justify-content:space-between;align-items:baseline;gap:8px;margin-bottom:7px}
          .sep-review .rdy-sub-label{font-size:var(--fs-sm);font-weight:600;color:var(--text)}
          .sep-review .rdy-sub-tag{font-size:var(--fs-xs);font-weight:700;flex-shrink:0}
          .sep-review .rdy-bar{height:6px;border-radius:var(--r-pill);background:var(--surface-secondary);overflow:hidden}
          .sep-review .rdy-bar>span{display:block;height:100%;border-radius:var(--r-pill)}
          .sep-review .rdy-warn{
            display:flex;gap:10px;align-items:flex-start;
            background:var(--amber-soft);border:1px solid var(--amber-border);border-radius:var(--r-md);
            padding:var(--s-3);margin-bottom:var(--s-2);
          }
          .sep-review .rdy-warn-ic{flex-shrink:0;color:var(--amber-dark);font-weight:800;font-size:var(--fs-base);line-height:1.3}
          .sep-review .rdy-warn-title{font-size:var(--fs-sm);font-weight:700;color:var(--text)}
          .sep-review .rdy-warn-body{font-size:var(--fs-xs);color:var(--text-muted);margin-top:2px;line-height:1.45}
          .sep-review .rdy-warn-note{font-size:var(--fs-xs);color:var(--amber-dark);margin-top:5px;font-style:italic}
          .sep-review .rdy-list{background:var(--canvas);border:1px solid var(--border);border-radius:var(--r-md);padding:var(--s-2) var(--s-3)}
          .sep-review .rdy-row{display:flex;gap:9px;align-items:baseline;padding:4px 0;font-size:var(--fs-sm);color:var(--text)}
          .sep-review .rdy-row-ic{width:14px;flex-shrink:0;text-align:center;font-weight:800}
          .sep-review .rdy-row.ok .rdy-row-ic{color:var(--green)}
          .sep-review .rdy-row.warn .rdy-row-ic{color:var(--amber-dark)}
          .sep-review .rdy-empty{font-size:var(--fs-xs);color:var(--text-subtle);padding:5px 0}
          .sep-review .rdy-timeline{position:relative;margin:2px 0 0;padding-left:18px}
          .sep-review .rdy-timeline::before{content:"";position:absolute;left:4px;top:5px;bottom:7px;width:2px;background:var(--border)}
          .sep-review .rdy-tl{position:relative;padding:0 0 var(--s-3) 2px}
          .sep-review .rdy-tl:last-child{padding-bottom:0}
          .sep-review .rdy-tl::before{content:"";position:absolute;left:-18px;top:3px;width:9px;height:9px;border-radius:50%;background:var(--surface);border:2px solid var(--text-subtle)}
          .sep-review .rdy-tl.hire::before{border-color:var(--accent)}
          .sep-review .rdy-tl.ack::before{border-color:var(--green)}
          .sep-review .rdy-tl.warn::before{border-color:var(--amber-dark)}
          .sep-review .rdy-tl.bad::before{border-color:var(--red)}
          .sep-review .rdy-tl-date{font-size:var(--fs-xs);font-weight:700;color:var(--text-subtle);text-transform:uppercase;letter-spacing:.03em}
          .sep-review .rdy-tl-label{font-size:var(--fs-sm);color:var(--text);margin-top:1px}
          .sep-review .rdy-tl-detail{font-size:var(--fs-xs);color:var(--text-subtle)}
          .sep-review .rdy-detail{border:1px solid var(--border);border-radius:var(--r-md);margin-bottom:var(--s-2);background:var(--surface)}
          .sep-review .rdy-detail>summary{
            display:flex;align-items:center;gap:10px;cursor:pointer;list-style:none;
            padding:9px var(--s-3);font-size:var(--fs-sm);font-weight:600;color:var(--text);
          }
          .sep-review .rdy-detail>summary::-webkit-details-marker{display:none}
          .sep-review .rdy-detail>summary::after{content:"▸";color:var(--text-subtle);font-size:11px;transition:transform .15s ease;flex-shrink:0}
          .sep-review .rdy-detail[open]>summary::after{transform:rotate(90deg)}
          .sep-review .rdy-detail-name{flex:1;min-width:0}
          .sep-review .rdy-detail-score{font-weight:800;font-size:var(--fs-sm);flex-shrink:0}
          .sep-review .rdy-detail-body{padding:0 var(--s-3) var(--s-1);border-top:1px solid var(--border-subtle)}
          .sep-review .rdy-factor{display:flex;justify-content:space-between;gap:12px;align-items:baseline;padding:5px 0;font-size:var(--fs-xs);border-bottom:1px solid var(--border-subtle)}
          .sep-review .rdy-factor:last-child{border-bottom:none}
          .sep-review .rdy-factor-label{color:var(--text-muted)}
          .sep-review .rdy-factor-val{font-weight:700;flex-shrink:0;color:var(--text);text-align:right}
          .sep-review .rdy-exec{
            display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1px;
            background:var(--border);border:1px solid var(--border);border-radius:var(--r-md);overflow:hidden;
          }
          .sep-review .rdy-exec-cell{background:var(--surface);padding:8px var(--s-3)}
          .sep-review .rdy-exec-k{font-size:var(--fs-xs);color:var(--text-subtle);text-transform:uppercase;letter-spacing:.03em}
          .sep-review .rdy-exec-v{font-size:var(--fs-sm);font-weight:600;color:var(--text);margin-top:1px}

          /* Schedule Assignment Wizard */
          .saw .saw-h{font-size:var(--fs-sm);font-weight:700;text-transform:uppercase;letter-spacing:.05em;color:var(--text-subtle);margin:0 0 8px;padding-bottom:4px;border-bottom:1px solid var(--border)}
          .saw .saw-status,.saw .saw-impact{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px 16px;margin-bottom:6px}
          .saw .saw-status>div,.saw .saw-impact>div{display:flex;justify-content:space-between;gap:10px;font-size:var(--fs-sm);padding:4px 0;border-bottom:1px dashed var(--border-subtle,rgba(15,23,42,.06))}
          .saw .saw-k{color:var(--text-subtle)}
          .saw .saw-v{font-weight:600;text-align:right}
          .saw .saw-tabs{display:flex;gap:6px;margin:16px 0 12px}
          .saw .saw-tab{appearance:none;border:1px solid var(--border);background:var(--surface);font:inherit;font-size:var(--fs-sm);font-weight:600;padding:6px 12px;border-radius:var(--r-md);cursor:pointer;color:var(--text-muted)}
          .saw .saw-tab.is-active{background:var(--accent-soft);color:var(--accent-text);border-color:var(--accent-border)}
          .saw .saw-group{margin-bottom:14px}
          .saw .saw-group-head{display:flex;align-items:baseline;justify-content:space-between;gap:10px;font-size:var(--fs-sm);font-weight:700;margin-bottom:6px}
          .saw .saw-group-sub{font-size:var(--fs-xs);font-weight:400;color:var(--text-subtle)}
          .saw .saw-row{display:flex;align-items:center;gap:10px;padding:8px 10px;border:1px solid var(--border);border-radius:var(--r-md);margin-bottom:6px;background:var(--surface)}
          .saw .saw-row.is-staged{border-color:var(--accent-border);background:var(--accent-soft)}
          .saw .saw-row-main{flex:1;min-width:0}
          .saw .saw-row-top{font-size:var(--fs-sm);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
          .saw .saw-row-sub{font-size:var(--fs-xs);color:var(--text-subtle);margin-top:1px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
          .saw .saw-score{flex-shrink:0;font-size:var(--fs-xs);font-weight:700;padding:2px 8px;border-radius:var(--r-pill);font-variant-numeric:tabular-nums}
          .saw .saw-empty{font-size:var(--fs-sm);color:var(--text-subtle);padding:8px 2px}
          .saw .saw-filters{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:10px}
          .saw .saw-filters .form-input{flex:1;min-width:120px}
          .saw .saw-list{max-height:38vh;overflow:auto}
          .saw .saw-violations{margin-top:6px;font-size:var(--fs-xs);color:#B91C1C;background:#F8D3CF;border-radius:var(--r-md);padding:8px 10px}
          .saw .saw-hint{font-size:var(--fs-xs);color:var(--text-subtle);line-height:1.45}
          .saw.saw-sched,.saw .saw-sched{min-width:0}

          /* Sort caret · idle (clickable but not the active sort)
             is a faded dual-arrow; active is a solid up/down. */
          #rr-roster-thead .rr-sort-caret{
            display:inline-block;margin-left:2px;
            font-size:9px;line-height:1;vertical-align:1px;
            font-variant-numeric:tabular-nums;
          }
          #rr-roster-thead .rr-sort-caret-idle{
            color:var(--text-subtle);opacity:.3;
            transition:opacity var(--t-fast);
          }
          #rr-roster-thead th[data-rr-roster-sort]:hover .rr-sort-caret-idle{
            opacity:.6;
          }
          /* Active sort arrow stays monochrome (no accent color) — it reads as
             "on" purely by being a solid single arrow against the faint idle
             carets, keeping the header quiet and enterprise-restrained. */
          #rr-roster-thead .rr-sort-caret-active{
            color:#374151;font-weight:700;
          }
          #rr-roster-thead th[data-rr-roster-sort]:hover,
          #rr-roster-thead [data-rr-roster-sort]:hover{
            color:var(--text) !important;
          }

          /* Status-pill picker · clicking the status pill in any
             driver row opens a small floating menu of status
             options. Trigger is a button styled identically to the
             original .status-pill so the at-rest visual is unchanged. */
          .rr-status-trigger{
            border:0;cursor:pointer;
            display:inline-flex;align-items:center;
            font:inherit;
            transition:filter var(--t-fast), box-shadow var(--t-fast);
          }
          .rr-status-trigger:hover{filter:brightness(0.96);box-shadow:0 1px 3px rgba(15,23,42,.08)}
          .rr-status-trigger:focus-visible{outline:none;box-shadow:0 0 0 3px var(--accent-soft)}
          .rr-status-picker{
            position:fixed;z-index:9999;
            background:var(--surface);
            border:1px solid var(--border);border-radius:var(--r-lg);
            box-shadow:var(--shadow-md);
            padding:4px;
            display:flex;flex-direction:column;gap:2px;
          }
          .rr-status-picker[hidden]{display:none}
          .rr-status-picker-item{
            display:flex;align-items:center;gap:10px;
            padding:8px 10px;
            border:0;background:transparent;cursor:pointer;
            font:inherit;font-size:var(--fs-sm);font-weight:500;
            color:var(--text);text-align:left;border-radius:6px;
            transition:background var(--t-fast);
          }
          .rr-status-picker-item:hover{background:var(--canvas)}
          .rr-status-picker-item:focus-visible{outline:none;background:var(--accent-soft);color:var(--accent-text)}
          .rr-status-picker-item.is-current{background:var(--accent-soft)}
          .rr-status-picker-dot{
            width:8px;height:8px;border-radius:50%;flex-shrink:0;
          }
          /* Roster row ⋯ menu — thin divider + muted icons, with a red
             destructive row for Terminate. Scoped so the other pickers
             that share .rr-status-picker chrome are untouched. */
          .rr-status-picker-sep{height:1px;background:var(--border-subtle);margin:4px 2px}
          #rr-row-more-pop .rr-status-picker-item svg{color:var(--text-subtle)}
          #rr-row-more-pop .rr-status-picker-item.is-danger,
          #rr-row-more-pop .rr-status-picker-item.is-danger svg{color:var(--red)}
          /* Match the KPI dashboard status palette (see .rr-dstatus-*). */
          .rr-status-dot-active{background:#16A34A}
          .rr-status-dot-onboarding{background:#1E293B}
          .rr-status-dot-seasonal{background:#0F766E}
          .rr-status-dot-leave{background:#C7860B}
          .rr-status-dot-inactive{background:var(--text-subtle)}
          .rr-status-dot-terminated{background:#DC2626}

          /* Attendance table header · same treatment as the Roster
             driver-table header (frosted-glass blue, sticky top,
             backdrop blur, pinned 79px) so Roster → Attendance reads
             as the same chrome family. Also zeros the table-wrap /
             dr-subview top margins inside the onboarding-roster
             mount so the KPI → table-header gap matches Schedule's
             25px. */
          #att-report-thead{
            position:sticky !important;top:0 !important;z-index:3 !important;
          }
          #att-report-thead th{
            background:#F3F4F6 !important;
            border-bottom:1px solid rgba(15,23,42,.26) !important;
            color:var(--text) !important;
            font-size:var(--fs-xs) !important;font-weight:600 !important;
            letter-spacing:.07em !important;text-transform:uppercase !important;
            padding:10px var(--s-4) 11px !important;
            height:79px !important;
            vertical-align:middle !important;
          }
          /* Match Roster's KPI → table-header gap parity rules so
             Attendance reads at the same vertical rhythm. */
          #ob-roster-mount #dr-sub-attendance,
          #ob-roster-mount #dr-sub-attendance .table-wrap,
          #ob-roster-mount #dr-sub-attendance .table-wrap > .table{
            margin-top:0 !important;padding-top:0 !important;
          }
          #ob-roster-mount #dr-sub-attendance .att-tabstrip,
          #ob-roster-mount #dr-sub-attendance #rr-att-filters{
            display:none !important;
          }

          /* In-header search · the search input was moved into the
             Driver column header cell so operators can scan + filter
             from the same row. JS in renderDriverTable relocates the
             .dr-search node (with its change/input handlers) into
             the .rr-roster-th-search-slot span here. */
          #rr-roster-thead th.rr-roster-th-driver{
            padding-top:0 !important;padding-bottom:0 !important;
          }
          /* The header search slot moved to the toolbar strip, so the Driver
             label is now a plain inline label that vertically centers with the
             other columns (no bottom margin reserving room for a search field). */
          #rr-roster-thead .rr-roster-th-driver-label{
            display:inline-flex;align-items:center;gap:4px;
            margin-right:0;margin-bottom:0;
          }
          #rr-roster-thead .rr-roster-th-search-slot{
            display:flex;align-items:center;
          }
          #rr-roster-thead .rr-roster-th-search-slot .dr-search{
            display:inline-block;position:relative;width:240px;max-width:32vw;
          }
          #rr-roster-thead .rr-roster-th-search-slot .dr-search svg{
            position:absolute;left:8px;top:50%;transform:translateY(-50%);
            width:13px;height:13px;color:var(--text-subtle);pointer-events:none;
          }
          #rr-roster-thead .rr-roster-th-search-slot .dr-search input{
            width:100%;height:26px;padding:0 8px 0 26px;
            border:1px solid rgba(15,23,42,.10);border-radius:6px;
            background:rgba(255,255,255,0.65);color:var(--text);
            font:inherit;font-size:var(--fs-xs);font-weight:500;
            text-transform:none;letter-spacing:0;
            transition:border-color var(--t-fast), box-shadow var(--t-fast), background var(--t-fast);
          }
          #rr-roster-thead .rr-roster-th-search-slot .dr-search input::placeholder{
            color:var(--text-subtle);font-weight:500;letter-spacing:0;text-transform:none;
          }
          #rr-roster-thead .rr-roster-th-search-slot .dr-search input:hover{
            border-color:rgba(15,23,42,.18);background:#fff;
          }
          #rr-roster-thead .rr-roster-th-search-slot .dr-search input:focus{
            outline:none;background:#fff;border-color:var(--accent);
            box-shadow:0 0 0 3px var(--accent-soft);
          }

          /* Driver-table header · matches the Schedule page's
             day-of-week strip — frosted-glass tinted blue, sticky
             top, backdrop blur so rows scroll softly underneath.
             Same #E8F1FA tint at 72% alpha that .cal-grid.head uses.
             Targets the thead by id (#rr-roster-thead) so the rule
             fires regardless of which view currently hosts the moved
             sub-tree (view-drivers vs view-onboarding-ops roster
             mode). The wrapping table-wrap is the scroll container;
             position:sticky on the thead pins it to the wrapper top. */
          /* Persistent vertical scrollbar · operator wanted the
             roster scrollbar to stay on screen even when idle (the
             OS auto-hide behaviour made the table feel like it was
             missing chrome). Force overflow-y:scroll so the track is
             always reserved, and style the webkit scrollbar so it
             reads as a quiet rail rather than the chunky OS default. */
          /* Roster column-header row · taller + ~25% larger labels
             (operator 2026-06-15/16). 11px -> 14px. */
          #rr-roster-table-wrap thead th{
            padding-top:var(--s-3-5);padding-bottom:var(--s-3-5);
            font-size:14px;
          }
          #rr-roster-table-wrap{
            overflow-x:auto;overflow-y:scroll !important;
            scrollbar-gutter:stable;
            position:relative;
            scrollbar-width:thin;                    /* Firefox */
            scrollbar-color:rgba(15,23,42,.22) transparent;
          }
          #rr-roster-table-wrap::-webkit-scrollbar{
            width:10px;height:10px;background:transparent;
          }
          #rr-roster-table-wrap::-webkit-scrollbar-track{
            background:rgba(15,23,42,.03);
            border-left:1px solid rgba(15,23,42,.06);
          }
          #rr-roster-table-wrap::-webkit-scrollbar-thumb{
            background:rgba(15,23,42,.22);
            border-radius:6px;
            border:2px solid transparent;
            background-clip:padding-box;
            transition:background var(--t-fast);
          }
          #rr-roster-table-wrap::-webkit-scrollbar-thumb:hover{
            background:rgba(15,23,42,.36);
            background-clip:padding-box;
          }
          #rr-roster-table-wrap::-webkit-scrollbar-corner{background:transparent}
          #rr-roster-thead{
            position:sticky !important;top:0 !important;z-index:3 !important;
          }
          #rr-roster-thead th{
            /* Matches the Schedule Targets table header exactly — dark charcoal
               (#374151) uppercase labels at 13px/700 with tight .02em tracking,
               white fill, and a single #ECEFF3 hairline. Controls live in the
               toolbar above, so the header only identifies columns. */
            background:var(--surface) !important;
            border-bottom:1px solid #ECEFF3 !important;
            color:#374151 !important;
            font-size:13px !important;font-weight:700 !important;
            letter-spacing:.02em !important;text-transform:uppercase !important;
            padding:0 var(--s-4) !important;
            height:36px !important;
            vertical-align:middle !important;
          }
          /* Slightly roomier rows + a softer hairline between them so the
             roster reads calmer and scans more easily (Schedule density). */
          #dr-sub-roster .table tbody td{
            padding-top:var(--s-4);padding-bottom:var(--s-4);
            border-bottom-color:var(--border-subtle);
          }
          /* ── Roster toolbar · search (left) + status filter & Add driver
             (right). Lightweight enterprise strip above the table. ── */
          .rr-roster-toolbar{
            display:flex;align-items:center;gap:var(--s-3);
            min-height:46px;padding:7px var(--s-4);
            background:var(--surface);
            border-bottom:1px solid var(--border);
          }
          .rr-roster-toolbar .rr-roster-toolbar-search{flex:1 1 auto;min-width:0}
          .rr-roster-toolbar .rr-roster-toolbar-actions{display:flex;align-items:center;gap:var(--s-2-5);flex:0 0 auto}
          /* Host for the relocated ⋯/bell/avatar chrome on the roster. */
          .rr-roster-chrome-host{display:inline-flex;align-items:center;gap:6px}
          .rr-roster-toolbar .dr-search{position:relative;width:min(360px,100%)}
          .rr-roster-toolbar .dr-search svg{position:absolute;left:10px;top:50%;transform:translateY(-50%);width:14px;height:14px;color:var(--text-subtle);pointer-events:none}
          .rr-roster-toolbar .dr-search input{
            width:100%;height:32px;padding:0 10px 0 30px;
            border:1px solid var(--border);border-radius:var(--r-md);
            background:var(--surface);color:var(--text);
            font:inherit;font-size:var(--fs-sm);
            transition:border-color var(--t-fast),box-shadow var(--t-fast);
          }
          .rr-roster-toolbar .dr-search input::placeholder{color:var(--text-subtle)}
          .rr-roster-toolbar .dr-search input:hover{border-color:var(--border-strong)}
          .rr-roster-toolbar .dr-search input:focus{outline:none;border-color:var(--accent);box-shadow:var(--ring-focus)}
          .rr-roster-toolbar .rr-roster-status-filter-btn{
            display:inline-flex;align-items:center;gap:2px;
            height:32px;padding:0 12px;
            border:1px solid var(--border);border-radius:var(--r-md);
            background:var(--surface);color:var(--text);
