          #view-fleet2 .fl-roster-bar select.fl-filter.is-set{color:var(--accent-text);border-color:rgba(37,99,235,.30);background-color:var(--accent-soft)}
          /* Vehicle photo / fallback icon in roster + drawer */
          #view-fleet2 .fl-veh-thumb{width:38px;height:38px;border-radius:var(--r-md);background:linear-gradient(135deg,#0F172A,#1E293B);color:#fff;display:flex;align-items:center;justify-content:center;flex-shrink:0;overflow:hidden}
          #view-fleet2 .fl-veh-thumb img{width:100%;height:100%;object-fit:cover}
          #view-fleet2 .fl-veh-thumb svg{width:18px;height:18px}
          /* Roster table tightening — matches the global table governance */
          #view-fleet2 .table tbody td{padding-top:var(--s-2-5);padding-bottom:var(--s-2-5)}
          #view-fleet2 .table tbody tr{cursor:pointer;transition:background var(--t-fast)}
          #view-fleet2 .table tbody tr:hover{background:var(--surface-hover)}
          #view-fleet2 .table thead th{letter-spacing:.04em}
          /* Empty state */
          #view-fleet2 .fl-empty{padding:var(--s-10) var(--s-6);text-align:center}
          #view-fleet2 .fl-empty .ic{width:44px;height:44px;border-radius:var(--r-lg);margin:0 auto var(--s-3-5);display:flex;align-items:center;justify-content:center;color:var(--accent);background:var(--accent-soft);border:1px solid var(--accent-border)}
          #view-fleet2 .fl-empty .ic svg{width:22px;height:22px}
          #view-fleet2 .fl-empty h3{margin:0 0 4px;font-size:var(--fs-base);font-weight:700;color:var(--text)}
          #view-fleet2 .fl-empty p{margin:0 auto var(--s-3-5);max-width:380px;font-size:var(--fs-md);color:var(--text-subtle);line-height:1.55}
          /* Skeleton */
          #view-fleet2 .fl-skel-cell{height:13px;border-radius:var(--r-sm);background:var(--canvas);position:relative;overflow:hidden}
          #view-fleet2 .fl-skel-cell::after{content:"";position:absolute;inset:0;background:linear-gradient(90deg, transparent, rgba(255,255,255,.65), transparent);transform:translateX(-100%);animation:flShimmer 1.4s ease-in-out infinite}
          #view-fleet2 .fl-skel-thumb{width:38px;height:38px;border-radius:var(--r-md);background:var(--canvas);position:relative;overflow:hidden}
          #view-fleet2 .fl-skel-thumb::after{content:"";position:absolute;inset:0;background:linear-gradient(90deg, transparent, rgba(255,255,255,.65), transparent);transform:translateX(-100%);animation:flShimmer 1.4s ease-in-out infinite}
          @keyframes flShimmer{to{transform:translateX(100%)}}
          /* Initial roster skeleton — rows of .rr-skel bars matching
             the 5-col table head rhythm so #fleet-tbody doesn't render
             empty before loadFleetRoster() lands. */
          #view-fleet2 .fl-skel-row td{padding-top:14px;padding-bottom:14px}
          #view-fleet2 .fl-skel-row{cursor:default}
          #view-fleet2 .fl-skel-veh{display:flex;align-items:center;gap:var(--s-3);min-width:0}
          /* Date-pill that warns when a compliance date is near/past */
          #view-fleet2 .fl-date{font-variant-numeric:tabular-nums;font-size:var(--fs-sm);white-space:nowrap}
          #view-fleet2 .fl-date.warn{color:var(--amber-dark);font-weight:600}
          #view-fleet2 .fl-date.urgent{color:var(--red);font-weight:700}
          #view-fleet2 .fl-date.dim{color:var(--text-subtle)}

          /* Subnav tab panels — only the active one renders */
          #view-fleet2 .fl-sub{display:none}
          #view-fleet2 .fl-sub.active{display:block}

          /* Operational status pill (Operational / Grounded) — for roster + drawer */
          #view-fleet2 .fl-opstat{display:inline-flex;align-items:center;gap:6px;font-size:var(--fs-xs);font-weight:600;line-height:1.5;white-space:nowrap}
          #view-fleet2 .fl-opstat .dot{width:8px;height:8px;border-radius:50%;flex:0 0 auto}
          #view-fleet2 .fl-opstat.operational{color:var(--green)}
          #view-fleet2 .fl-opstat.operational .dot{background:var(--green)}
          #view-fleet2 .fl-opstat.grounded{color:var(--red)}
          #view-fleet2 .fl-opstat.grounded .dot{background:var(--red)}

          /* Inline-edit button wrapping the status pill on the roster.
             Click → small popover menu (rendered into <body> at runtime)
             that flips status without opening the per-van drawer. */
          #view-fleet2 .fl-opstat-btn{
            display:inline-flex;align-items:center;gap:6px;
            padding:2px 6px 2px 4px;border-radius:var(--r-md);
            background:transparent;border:1px solid transparent;
            color:inherit;cursor:pointer;font:inherit;line-height:1.4;
            transition:background var(--t-fast), border-color var(--t-fast);
          }
          #view-fleet2 .fl-opstat-btn:hover{background:var(--canvas);border-color:var(--border)}
          #view-fleet2 .fl-opstat-btn:focus-visible{outline:none;border-color:var(--accent);box-shadow:var(--ring-focus)}
          #view-fleet2 .fl-opstat-row{display:inline-flex;align-items:center;gap:6px}
          #view-fleet2 .fl-opstat-chev{width:11px;height:11px;color:var(--text-subtle);flex:0 0 auto}

          /* Days-grounded box — sits right next to the Grounded pill.
             Square (logistics-instrument vibe, not a pill); severity
             ramps against Amazon's 7d / 14d repair-completion thresholds. */
          #view-fleet2 .fl-down-badge{
            display:inline-flex;align-items:center;justify-content:center;
            min-width:34px;padding:2px var(--s-2);
            border-radius:var(--r-sm);
            font-size:var(--fs-xs);font-weight:700;letter-spacing:.02em;line-height:1.4;
            background:var(--red-soft);color:var(--red);
            border:1px solid rgba(220,38,38,.18);
            font-variant-numeric:tabular-nums;
          }
          #view-fleet2 .fl-down-badge.warn{background:var(--amber-soft);color:var(--amber-dark);border-color:var(--amber-border)}
          #view-fleet2 .fl-down-badge.crit{background:var(--red-dark);color:#fff;border-color:var(--red-dark)}

          /* Repair-status cell · two labelled clocks + RO entry box.
             Stacked rows so each clock has its own label header. */
          #view-fleet2 .fl-repair-status{display:flex;flex-direction:column;gap:5px;min-width:200px}
          /* Non-warranty grounded vans · just the category + days. */
          #view-fleet2 .fl-rs-nonwarranty{gap:2px}
          #view-fleet2 .fl-rs-cat{font-size:var(--fs-sm);font-weight:600;color:var(--text)}
          #view-fleet2 .fl-rs-days{font-size:var(--fs-xs);color:var(--text-subtle);font-variant-numeric:tabular-nums}
          /* Grounding category picker (modal · mounted on <body>). */
          .rr-fl-ground-cats{display:flex;flex-direction:column;gap:6px}
          .rr-fl-ground-cat{
            appearance:none;cursor:pointer;font:inherit;text-align:left;
            display:flex;align-items:flex-start;gap:10px;
            padding:10px 12px;border-radius:var(--r-md);
            background:var(--surface);border:1px solid var(--border);
            transition:background var(--t-fast),border-color var(--t-fast);
          }
          .rr-fl-ground-cat:hover{background:var(--surface-hover)}
          .rr-fl-ground-cat.is-picked{
            background:var(--accent-soft);border-color:var(--accent);
          }
          .rr-fl-ground-radio{
            flex:0 0 auto;width:16px;height:16px;margin-top:1px;
            border-radius:50%;border:2px solid var(--border-strong,rgba(15,23,42,.22));
            transition:border-color var(--t-fast);
          }
          .rr-fl-ground-cat.is-picked .rr-fl-ground-radio{
            border-color:var(--accent);
            box-shadow:inset 0 0 0 3px var(--accent);
          }
          .rr-fl-ground-cat-text{display:flex;flex-direction:column;gap:1px;min-width:0}
          .rr-fl-ground-cat-label{font-size:var(--fs-sm);font-weight:600;color:var(--text)}
          .rr-fl-ground-cat-hint{font-size:var(--fs-xs);color:var(--text-subtle);line-height:1.4}
          #view-fleet2 .fl-rs-row{display:grid;grid-template-columns:120px 1fr;gap:var(--s-2);align-items:center}
          #view-fleet2 .fl-rs-label{
            font-size:var(--fs-xs);font-weight:700;letter-spacing:.05em;text-transform:uppercase;
            color:var(--text-subtle);
          }
          #view-fleet2 .fl-rs-ro-input{
            width:100%;height:24px;padding:2px 7px;
            border:1px solid var(--border);border-radius:var(--r-sm);
            background:var(--surface);color:var(--text);
            font-family:ui-monospace,SFMono-Regular,Menlo,monospace;
            font-size:var(--fs-sm);letter-spacing:.02em;
            transition:border-color var(--t-fast), box-shadow var(--t-fast);
          }
          #view-fleet2 .fl-rs-ro-input:focus{outline:none;border-color:var(--accent);box-shadow:var(--ring-focus)}
          #view-fleet2 .fl-clock{
            display:inline-flex;align-items:center;justify-content:flex-start;
            padding:1px 7px;border-radius:var(--r-sm);
            font-size:var(--fs-xs);font-weight:700;letter-spacing:.02em;line-height:1.5;
            font-variant-numeric:tabular-nums;white-space:nowrap;
            background:var(--canvas);color:var(--text-muted);border:1px solid var(--border);
          }
          #view-fleet2 .fl-clock.fl-clock-ok{background:var(--green-soft);color:var(--green);border-color:transparent}
          #view-fleet2 .fl-clock.fl-clock-warn{background:var(--amber-soft);color:var(--amber-dark);border-color:transparent}
          #view-fleet2 .fl-clock.fl-clock-crit{background:var(--red-dark);color:#fff;border-color:var(--red-dark)}
          #view-fleet2 .fl-clock.fl-clock-met{background:var(--green-soft);color:var(--green);border-color:transparent}
          #view-fleet2 .fl-clock.fl-clock-dim{background:transparent;color:var(--text-subtle);border-color:transparent}

          /* Floating inline status menu — appended to <body> so it
             escapes table-cell overflow.  Positioned in JS. */
          .fl-opstat-menu{
            position:absolute;z-index:9000;
            background:var(--surface);border:1px solid var(--border);
            border-radius:var(--r-lg);box-shadow:var(--shadow-lg);
            padding:var(--s-2);min-width:200px;
          }
          .fl-opstat-menu .row{
            display:flex;align-items:center;gap:var(--s-2-5);width:100%;
            padding:var(--s-2) var(--s-2-5);border-radius:var(--r-md);
            background:transparent;border:none;cursor:pointer;text-align:left;
            font-size:var(--fs-md);color:var(--text);font-weight:500;
            transition:background var(--t-fast);
          }
          .fl-opstat-menu .row:hover{background:var(--canvas)}
          .fl-opstat-menu .row[disabled]{opacity:.55;cursor:default}
          .fl-opstat-menu .row[disabled]:hover{background:transparent}
          .fl-opstat-menu .pip{width:8px;height:8px;border-radius:50%;flex:0 0 auto}
          .fl-opstat-menu .pip.green{background:var(--green)}
          .fl-opstat-menu .pip.red{background:var(--red)}
          .fl-opstat-menu .row .sub{
            margin-left:auto;font-size:var(--fs-xs);font-weight:700;letter-spacing:.05em;
            text-transform:uppercase;color:var(--text-subtle);
          }
          .fl-opstat-menu .row.is-active .sub{color:var(--green)}

          /* Issue severity chip */
          #view-fleet2 .fl-sev{display:inline-flex;align-items:center;font-size:var(--fs-xs);font-weight:700;letter-spacing:.04em;text-transform:uppercase;padding:2px var(--s-2);border-radius:var(--r-sm);white-space:nowrap}
          #view-fleet2 .fl-sev.low{background:var(--canvas);color:var(--text-muted);border:1px solid var(--border)}
          #view-fleet2 .fl-sev.medium{background:var(--accent-soft);color:var(--accent-text)}
          #view-fleet2 .fl-sev.high{background:var(--amber-soft);color:var(--amber-dark)}
          #view-fleet2 .fl-sev.critical{background:var(--red-soft);color:var(--red)}

          /* ── Fluent 2 restyle · Fleet roster ───────────────────────────
             Microsoft 365 / Windows 11 surface language: Segoe UI,
             crisp 4px corners, Fluent neutral + brand-blue palette,
             quiet 1px strokes, and the signature animated accent
             underline on text fields. Scoped to #view-fleet2 so the
             rest of the app's design system is untouched. */
          #view-fleet2{
            /* Match the Schedule page ground exactly (#view-schedule.rrx-schedule
               uses background:#F9FAFB — the unified neutral canvas). Fleet
               previously inherited the global body --canvas (#FEFEFF); pin it to
               the Schedule value so the two pages read identically.
               (Re-scoped from #view-fleet2 → #view-fleet2 when the Fleet
               content moved; defines the --flu-* tokens the moved roster/
               table/drawer markup depends on.) */
            background:#F9FAFB;
            --flu-brand:#2563EB;
            --flu-brand-hover:#1D4ED8;
            --flu-stroke:var(--border);
            --flu-stroke-strong:#D1D5DB;
            --flu-bg-hover:#F3F4F6;
            --flu-bg-selected:#EFF6FF;
            --flu-fg:#111827;
            --flu-fg-2:#6B7280;
            --flu-radius:10px;
            --flu-success-fg:#15803D;  --flu-success-bg:#DCFCE7;  --flu-success-bd:#BBF7D0;
            --flu-danger-fg:#B91C1C;   --flu-danger-bg:#FEE2E2;   --flu-danger-bd:#FECACA;
            --flu-warning-fg:#92400E;  --flu-warning-bg:#FEF3C7;  --flu-warning-bd:#FDE68A;
            --flu-font:"Segoe UI Variable Text","Segoe UI Variable","Segoe UI",system-ui,-apple-system,sans-serif;
          }
          #view-fleet2 .table,
          #view-fleet2 .fl-roster-bar,
          #view-fleet2 .fl-ribbon{font-family:var(--flu-font)}

          /* Header — Fluent DataGrid: sentence case, quiet, thin rule */
          #view-fleet2 .table thead th{
            background:var(--surface);
            color:var(--flu-fg-2);
            font-weight:600;
            text-transform:none;
            letter-spacing:.01em;
            border-bottom:1px solid var(--flu-stroke);
          }
          #view-fleet2 .table thead th[data-rr-sort]:hover,
          #view-fleet2 .table thead th[data-att-sort]:hover{color:var(--flu-brand)}

          /* Rows — thin Fluent dividers + neutral hover */
          #view-fleet2 .table tbody td{border-bottom:1px solid var(--flu-stroke);color:var(--flu-fg)}
          #view-fleet2 .table tbody tr:hover{background:var(--flu-bg-hover)}

          /* Square Fluent corners across the roster's chips & controls */
          #view-fleet2 .fl-down-badge,
          #view-fleet2 .fl-clock,
          #view-fleet2 .fl-sev,
          #view-fleet2 .fl-rs-ro-input,
          #view-fleet2 .fl-opstat-btn,
          #view-fleet2 .fl-veh-thumb,
          #view-fleet2 .fl-roster-bar .fl-search input,
          #view-fleet2 .fl-roster-bar select.fl-filter{border-radius:4px}

          /* Status dropdown trigger — Fluent subtle button */
          #view-fleet2 .fl-opstat-btn:hover{background:var(--flu-bg-hover);border-color:var(--flu-stroke)}
          #view-fleet2 .fl-opstat-btn:focus-visible{
            border-color:var(--flu-brand);box-shadow:none;
            outline:2px solid var(--flu-brand);outline-offset:-1px;
          }

          /* Text fields — Fluent field: neutral border, darker bottom
             edge, 2px brand underline on focus (no glow, no reflow) */
          #view-fleet2 .fl-rs-ro-input,
          #view-fleet2 .fl-roster-bar .fl-search input,
          #view-fleet2 .fl-roster-bar select.fl-filter{
            border-color:var(--flu-stroke-strong);
            border-bottom-color:var(--flu-fg-2);
          }
          #view-fleet2 .fl-rs-ro-input:focus,
          #view-fleet2 .fl-roster-bar .fl-search input:focus,
          #view-fleet2 .fl-roster-bar select.fl-filter:focus{
            outline:none;
            border-color:var(--flu-stroke-strong);
            border-bottom-color:var(--flu-brand);
            box-shadow:inset 0 -2px 0 0 var(--flu-brand);
          }
          #view-fleet2 .fl-roster-bar select.fl-filter.is-set{
            color:var(--flu-brand);border-color:var(--flu-stroke-strong);
            background-color:var(--flu-bg-selected);
          }

          /* Status text — Fluent semantic foregrounds */
          #view-fleet2 .fl-opstat.operational{color:var(--flu-success-fg)}
          #view-fleet2 .fl-opstat.operational .dot{background:var(--flu-success-fg)}
          #view-fleet2 .fl-opstat.grounded{color:var(--flu-danger-fg)}
          #view-fleet2 .fl-opstat.grounded .dot{background:var(--flu-danger-fg)}

          /* Badges — Fluent tint badges (filled for critical) */
          #view-fleet2 .fl-down-badge{
            background:var(--flu-danger-bg);color:var(--flu-danger-fg);
            border-color:var(--flu-danger-bd);
          }
          #view-fleet2 .fl-down-badge.warn{
            background:var(--flu-warning-bg);color:var(--flu-warning-fg);
            border-color:var(--flu-warning-bd);
          }
          #view-fleet2 .fl-down-badge.crit{
            background:var(--flu-danger-fg);color:#fff;border-color:var(--flu-danger-fg);
          }
          #view-fleet2 .fl-clock.fl-clock-ok,
          #view-fleet2 .fl-clock.fl-clock-met{
            background:var(--flu-success-bg);color:var(--flu-success-fg);border-color:var(--flu-success-bd);
          }
          #view-fleet2 .fl-clock.fl-clock-warn{
            background:var(--flu-warning-bg);color:var(--flu-warning-fg);border-color:var(--flu-warning-bd);
          }
          #view-fleet2 .fl-clock.fl-clock-crit{
            background:var(--flu-danger-fg);color:#fff;border-color:var(--flu-danger-fg);
          }
          #view-fleet2 .fl-sev.medium{background:var(--flu-bg-selected);color:var(--flu-brand)}
          #view-fleet2 .fl-sev.high{background:var(--flu-warning-bg);color:var(--flu-warning-fg)}
          #view-fleet2 .fl-sev.critical{background:var(--flu-danger-bg);color:var(--flu-danger-fg)}

          /* ── Fleet execution KPI strip ─────────────────────────────
             Reuses the dashboard's stock .kpi-card system so the FEM
             and VORR cards read as part of the same KPI family as
             every other surface in the app — same padding, same brand
             ribbon, same label/value/sub rhythm.  We only override the
             grid to 2-up and make the cards behave as buttons; state
             is conveyed by a single pip in .kpi-sub, never by red
             chrome on the card itself. */
          /* ── Page ribbon · set 1:1 with the schedule page's icon
             strip (.sched-nav-heading) — same card chrome, padding,
             radius, shadow, and title-left / actions-right layout. ── */
          /* Page padding · match Schedule's effective offset before
             the strip card. Schedule uses 20px page padding-top +
             a hidden ~20px legacy .sched-cmd-shell = 40px before
             the visible strip. Fleet has no hidden shell, so its
             .page padding-top is bumped to 40px directly. The other
             three sides stay at 20px (--rr-space-200) like Schedule.
             Also locks the page to a viewport-tall flex column so the
             chrome (strip card, KPI strip, roster bar) stays put and
             only the table body scrolls — same pattern Schedule uses. */
          /* Page layout (.active / > .page) is now owned by the
             #view-fleet2 self-contained style block above — the new page
             uses 20px padding + its own .f2 chrome, not the old 40px-top
             fleet ribbon. These legacy rules are retired with #view-fleet. */
          #view-fleet-legacy.active{
            display:flex;flex:1 1 auto;min-height:0;
          }
          #view-fleet-legacy > .page{
            padding:40px var(--rr-space-200) var(--rr-space-200) var(--rr-space-200) !important;
            display:flex;flex-direction:column;
            flex:1 1 auto;min-height:0;
            overflow:hidden;
          }
          /* TCP chrome rows · locked at the top, never scroll. */
          #view-fleet2 .fl-ribbon,
          #view-fleet2 .fl-kpi-pills,
          #view-fleet2 #rr-fleet-exec-detail{
            flex:0 0 auto;
          }
          /* Active sub-tab fills the remaining space and itself is a
             flex column so the roster bar can sit above the scrolling
             table area. */
          #view-fleet2 .fl-sub.active{
            flex:1 1 auto;min-height:0;
            display:flex;flex-direction:column;
          }
          /* Table-wrap is the visual card (border, radius); inside it,
             the roster bar pins to the top and .fl-table-scroll owns
             the vertical scroll for the table body. */
          #view-fleet2 .table-wrap{
            flex:1 1 auto;min-height:0;
            display:flex;flex-direction:column;
            overflow:hidden;
          }
          #view-fleet2 .fl-roster-bar{
            flex:0 0 auto;
          }
          #view-fleet2 .fl-table-scroll{
            flex:1 1 auto;min-height:0;
            overflow-y:scroll;overflow-x:auto;
            scrollbar-gutter:stable;
            scrollbar-width:thin;
            scrollbar-color:var(--border-strong) transparent;
          }
          /* Cohesion pass · thin, quiet scrollbar matching the driver
             pool and the rest of the app (the old 14px dark-thumb bar
             read as legacy-Windows chrome). */
          #view-fleet2 .fl-table-scroll::-webkit-scrollbar{
            width:8px;height:8px;background:transparent;
          }
          #view-fleet2 .fl-table-scroll::-webkit-scrollbar-track{
            background:transparent;
          }
          #view-fleet2 .fl-table-scroll::-webkit-scrollbar-thumb{
            background:var(--border-strong);border-radius:4px;min-height:48px;
          }
          #view-fleet2 .fl-table-scroll::-webkit-scrollbar-thumb:hover{
            background:var(--text-subtle);
          }

          /* Fleet strip card · locked to the TCP spec so it reads
             identical to Schedule + Onboarding (and now Fleet Bridge).
             Tokens come from dashboard/tcp.css. */
          #view-fleet2 .fl-ribbon{
            display:flex;align-items:center;
            justify-content:flex-start;
            gap:var(--s-3);flex-wrap:nowrap;
            padding:11px 18px;
            /* Density pass · strip→KPI gap tracks the shared
               --tcp-strip-gap (16→12) so Fleet tightens with the rest. */
            margin-bottom:var(--tcp-strip-gap, 12px);
            background:var(--rr-bg-surface-1);
            border:1px solid var(--rr-border-primary);
            border-radius:var(--rr-radius-medium);
            box-shadow:none;
            min-height:var(--tcp-strip-h);
            height:var(--tcp-strip-h);
            max-height:var(--tcp-strip-h);
            box-sizing:border-box;
            overflow:visible;
          }
          /* Cmd-shell · the "Fleet / Print/Download" tabs sit above
             the ribbon card. Plain-text labels matching Schedule's
             .sched-v2-cmd-tabs — active is brand-blue text, no card
             chrome, hover stays transparent. */
          #view-fleet2 .fl-ribbon.fl-cmd-shell{position:relative}
          #view-fleet2 .fl-cmd-tabs{
            position:absolute;left:0;bottom:100%;margin-bottom:-1px;
            display:inline-flex;gap:2px;
            height:var(--tcp-cmd-tabs-h);
            align-items:center;
          }
          #view-fleet2 .fl-cmd-tab{
            appearance:none;background:transparent;cursor:pointer;
            /* Match Schedule's .sched-v2-cmd-tabs .sched-cmd-tab: same
               font-shorthand (--rr-font-caption = 400 12px/16px) then
               override weight to 600. Earlier I used `font:inherit` +
               `font-size:11px`, which rendered 1px smaller than
               Schedule. */
            font:var(--rr-font-caption);
            font-weight:600;letter-spacing:.04em;text-transform:uppercase;
            color:var(--rr-fg-secondary);
            padding:var(--rr-space-60) var(--rr-space-120);
            border:1px solid transparent;border-bottom:0;
            border-radius:var(--rr-radius-medium) var(--rr-radius-medium) 0 0;
            transition:color var(--rr-motion-fast);
          }
          #view-fleet2 .fl-cmd-tab:hover:not(.active){background:transparent}
          #view-fleet2 .fl-cmd-tab.active{
            color:var(--rr-brand-primary);background:transparent;border-color:transparent;
          }
          #view-fleet2 .fl-cmd-tab:focus-visible{outline:none;color:var(--rr-brand-primary)}
          /* Match Schedule's darkened cmd-tab strip (var(--text)). */
          #view-fleet2 .fl-cmd-tab{color:var(--text) !important}
          /* Print/Download mode · everything except the print-actions
             goes invisible; the print/download/proof buttons sit at the
             ribbon's left edge. */
          #view-fleet2 .fl-ribbon.fl-cmd-shell:not(.is-print) .fl-print-actions{display:none}
          #view-fleet2 .fl-ribbon.fl-cmd-shell.is-print .fl-ribbon-actions{position:relative}
          #view-fleet2 .fl-ribbon.fl-cmd-shell.is-print .fl-ribbon-actions > :not(.fl-print-actions){
            visibility:hidden;
          }
          #view-fleet2 .fl-ribbon.fl-cmd-shell.is-print .fl-print-actions{
            display:inline-flex;gap:8px;visibility:visible;
            position:absolute;left:0;top:50%;transform:translateY(-50%);
          }
          /* Print isolation · only the fleet print-area renders on paper. */
          #rr-fleet-print-area{display:none}
          @media print{
            html.rr-printing #view-fleet2 > .page > *:not(#rr-fleet-print-area){display:none !important}
            html.rr-printing #rr-fleet-print-area{display:block !important;padding:0}
            html.rr-printing #rr-fleet-print-area .rr-print-head{
              font-size:18px;font-weight:700;margin:0 0 12px;color:#000;
            }
            html.rr-printing #rr-fleet-print-area table{
              width:100%;border-collapse:collapse;font-size:12px;
            }
            html.rr-printing #rr-fleet-print-area table th,
            html.rr-printing #rr-fleet-print-area table td{
              border:1px solid #D1D5DB;padding:6px 8px;text-align:left;
              vertical-align:top;
            }
          }
          /* Proof-of-Use report modal (Outlook-style centered dialog). */
          .rr-proof-modal{
            position:fixed;inset:0;background:var(--overlay,rgba(15,23,42,.4));
            z-index:9999;display:flex;align-items:center;justify-content:center;
            padding:var(--s-6);
          }
          .rr-proof-card{
            background:#fff;border:1px solid var(--border);border-radius:8px;
            box-shadow:var(--shadow-pop);
            width:780px;max-width:100%;max-height:90vh;
            display:flex;flex-direction:column;overflow:hidden;
          }
          .rr-proof-head{
            display:flex;align-items:center;justify-content:space-between;
            padding:14px 18px;border-bottom:1px solid var(--border);background:var(--canvas);
          }
          .rr-proof-head h3{margin:0;font-size:15px;font-weight:600;color:#111827}
          .rr-proof-head-sub{font-size:12px;color:#6B7280;margin-top:2px}
          .rr-proof-close{
            background:transparent;border:0;cursor:pointer;color:#6B7280;
            width:28px;height:28px;border-radius:4px;font-size:18px;
          }
          .rr-proof-close:hover{background:var(--surface-hover);color:#111827}
          .rr-proof-body{padding:14px 18px;overflow-y:auto;flex:1 1 auto}
          .rr-proof-bar{
            display:flex;align-items:end;gap:10px;flex-wrap:wrap;
            padding-bottom:12px;border-bottom:1px solid var(--border);margin-bottom:12px;
          }
          .rr-proof-bar label{
            display:flex;flex-direction:column;gap:4px;
            font-size:12px;font-weight:600;color:#6B7280;
          }
          .rr-proof-bar input,
          .rr-proof-bar select{
            height:30px;padding:0 8px;font:inherit;font-size:13px;color:#111827;
            border:1px solid var(--border);border-radius:4px;background:#fff;
          }
          .rr-proof-bar input:focus,
          .rr-proof-bar select:focus{
            outline:none;border-color:#2563EB;box-shadow:0 0 0 1px #2563EB;
          }
          .rr-proof-bar .btn-primary{
            height:30px;padding:0 14px;font-size:13px;font-weight:600;
            background:#2563EB;color:#fff;border:1px solid #2563EB;border-radius:4px;
          }
          .rr-proof-bar .btn-primary:hover{background:#1D4ED8;border-color:#1D4ED8}
          .rr-proof-result{font-size:13px;color:#111827}
          .rr-proof-summary{
            background:var(--canvas);border:1px solid var(--border);border-radius:4px;
            padding:10px 12px;margin-bottom:10px;
            display:flex;align-items:baseline;justify-content:space-between;gap:10px;
            font-size:13px;
          }
          .rr-proof-table{width:100%;border-collapse:collapse;font-size:13px}
          .rr-proof-table th,.rr-proof-table td{
            border-bottom:1px solid #F0EFEE;padding:8px 10px;text-align:left;
            vertical-align:top;
          }
          .rr-proof-table thead th{
            background:var(--canvas);font-size:12px;font-weight:600;color:#6B7280;
            border-bottom:1px solid var(--border);
          }
          .rr-proof-empty{padding:18px;text-align:center;color:#6B7280;font-size:13px}
          .rr-proof-foot{
            display:flex;align-items:center;justify-content:flex-end;gap:8px;
            padding:12px 18px;border-top:1px solid var(--border);background:var(--canvas);
          }
          .rr-proof-foot .btn{
            height:30px;padding:0 12px;font-size:13px;font-weight:600;
            background:#fff;color:#111827;border:1px solid #D1D5DB;border-radius:4px;
            cursor:pointer;
          }
          .rr-proof-foot .btn:hover{background:#F3F4F6}
          .rr-proof-foot .btn-primary{
            background:#2563EB;color:#fff;border-color:#2563EB;
          }
          .rr-proof-foot .btn-primary:hover{background:#1D4ED8;border-color:#1D4ED8}

          /* Title block · matches Schedule's .sched-v2-title exactly.
             flex 0 0 240px (TCP --tcp-title-w), flex-column with
             explicit align-items:flex-start to override the global
             .page-header-l { align-items:center } that would otherwise
             center the title horizontally. Page-icon (the fleet
             diagram glyph) hidden — Schedule + Onboarding + Fleet
             Bridge all drop the icon next to the title. */
          #view-fleet2 .fl-ribbon-titlewrap{
            flex:0 0 var(--tcp-title-w);
            align-self:center;
            display:flex;flex-direction:column;justify-content:center;
            align-items:flex-start;
            min-width:0;
            margin-right:var(--rr-space-160);
            padding-right:var(--rr-space-120);
          }
          #view-fleet2 .fl-ribbon-titlewrap .page-icon{display:none !important}
          #view-fleet2 .fl-ribbon .page-title{
            font:var(--rr-font-subtitle);
            color:var(--rr-fg-primary);
            letter-spacing:-.01em;
            margin:0;
            white-space:nowrap;
          }
          #view-fleet2 .fl-ribbon .page-sub{
            font:var(--rr-font-caption);
            color:var(--rr-fg-secondary);
            margin:2px 0 0;
            white-space:nowrap;
          }
          /* Action ribbon · first hairline divider sits at the same X
             as Schedule's (16px margin + 16px padding + 1px line in
             rgba(15,23,42,.16) after a 240px title block + 16px margin-right
             on the title). */
          #view-fleet2 .fl-ribbon-actions{
            display:flex;align-items:center;
            justify-content:flex-start;
            gap:6px;flex-wrap:nowrap;min-width:0;
            margin-left:var(--rr-space-160);
            padding-left:var(--rr-space-160);
            border-left:1px solid rgba(15,23,42,.16);
          }
          #view-fleet2 .fl-ribbon-tail{
            display:flex;align-items:center;gap:8px;
            margin-left:10px;align-self:center;
          }
          #view-fleet2 .fl-ribbon-group{
            display:flex;align-items:center;gap:6px;flex-wrap:nowrap;
            margin-bottom:0;
            padding:0;
          }
          /* Tile metrics match Schedule's .sched-v2-tile exactly:
             same padding, min-width, gap, icon size, and rounded
             corners (--rr-radius-medium, not 90° square — Schedule's
             rounded tiles are the standard now). */
          #view-fleet2 .fl-ribbon-btn{
            position:relative;
            appearance:none;cursor:pointer;font:inherit;
            display:inline-flex;flex-direction:column;
            align-items:center;justify-content:center;gap:4px;
            min-width:62px;
            padding:6px 10px 7px;
            background:transparent;
            border:0;
            border-radius:var(--rr-radius-medium);
            color:var(--rr-fg-secondary);
            transition:background var(--t-fast),color var(--t-fast),
                       transform .12s cubic-bezier(.2,.7,.2,1);
          }
          #view-fleet2 .fl-ribbon-btn:hover{
            background:var(--rr-bg-hover);color:var(--rr-fg-primary);
          }
          /* Icon styling matched 1:1 to the Schedule / onboarding
             command-strip tiles (#view-schedule.rrx-schedule .subnav-item svg):
             28×28, 1.6 stroke, square caps + miter joins for the
             boxy line-icon feel, colored with --rr-fg-secondary. */
          #view-fleet2 .fl-ribbon-btn svg{
            width:28px !important;height:28px !important;stroke-width:1.6 !important;
            stroke-linecap:square !important;stroke-linejoin:miter !important;
            /* --rr-fg-secondary is never defined (only ever used with this
               fallback), so pin the concrete value or the icons inherit the
               button's darker text color and stop matching the Schedule strip. */
            color:var(--rr-fg-secondary, #6B7280) !important;
          }
          #view-fleet2 .fl-ribbon-btn span{font-size:13px;font-weight:500}
          /* Active view switcher — colored, not boxed (mirrors the
             schedule ribbon's active tab). */
          #view-fleet2 .fl-ribbon-view.active,
          #view-fleet2 .fl-ribbon-view.active:hover{
            background:var(--rr-bg-selected);
            color:var(--rr-brand-pressed);
          }
          #view-fleet2 .fl-ribbon-view.active svg{color:var(--rr-brand-primary)}
          #view-fleet2 .fl-ribbon-view.active span{font-weight:600}
          /* Count badge pinned to the button's top-right corner. */
          #view-fleet2 .fl-ribbon-count{
            position:absolute;top:4px;right:6px;
            min-width:16px;height:16px;padding:0 4px;
            display:inline-flex;align-items:center;justify-content:center;
            font-size:10px;font-weight:700;line-height:1;
            border-radius:8px;
            background:rgba(15,23,42,.08);color:var(--text-muted);
          }
          #view-fleet2 .fl-ribbon-view.active .fl-ribbon-count{
            background:var(--accent);color:#fff;
          }
          /* Hairline divider between ribbon groups — matches Schedule's
             .sched-ribbon-group + .sched-ribbon-group::before (1px ×
             20px line in --rr-border-secondary, 4px margin on the
             right). */
          #view-fleet2 .fl-ribbon-group + .fl-ribbon-group{
            margin-left:var(--rr-space-40);
            padding-left:0;
            position:static;
          }
          #view-fleet2 .fl-ribbon-group + .fl-ribbon-group::before{
            content:"";
            display:inline-block;
            width:1px;height:20px;
            background:var(--rr-border-secondary);
            margin-right:var(--rr-space-40);
          }

          /* ── Fleet assignment · "Rules" footer + van-rules popover ──
             A twin of the schedule page's Assign-rules box; both share
             one localStorage key so editing either updates the other. */
          #view-fleet2 .fl-tab-wrap{
            position:relative;display:inline-flex;
            flex-direction:column;align-items:center;
          }
          #view-fleet2 .fl-rules-foot{
            display:inline-flex;align-items:center;justify-content:center;gap:4px;
            margin:-2px auto 0;padding:3px 9px;border-radius:4px;
            background:transparent;border:0;cursor:pointer;font-family:inherit;
            font-size:11px;font-weight:500;letter-spacing:.01em;color:var(--text-subtle);
            transition:background var(--t-fast),color var(--t-fast);
          }
          #view-fleet2 .fl-rules-foot svg{width:9px;height:9px;display:block;stroke-width:2}
          #view-fleet2 .fl-rules-foot:hover,
          #view-fleet2 .fl-rules-foot:focus-visible{
            color:var(--sch-blue);background:rgba(37,99,235,.06);outline:none;
          }
          #view-fleet2 .fl-rules-foot[aria-expanded="true"]{
            color:var(--sch-blue);background:rgba(37,99,235,.08);
          }
          #view-fleet2 .sched-vans-rules-popover{
            position:absolute;top:calc(100% + 4px);left:0;right:auto;z-index:60;
            width:460px;max-width:calc(100vw - 48px);
            max-height:calc(100vh - 200px);overflow-y:auto;
            font-family:"Inter","Segoe UI","Segoe UI Web (West European)",-apple-system,BlinkMacSystemFont,Roboto,"Helvetica Neue",sans-serif;
            background:rgba(255,255,255,.82);
            -webkit-backdrop-filter:blur(40px) saturate(170%);
            backdrop-filter:blur(40px) saturate(170%);
            border:1px solid rgba(255,255,255,.55);border-radius:8px;
            box-shadow:0 14px 32px rgba(0,0,0,.20),0 0 10px rgba(0,0,0,.12);
          }
          #view-fleet2 .sched-vans-rules-popover[hidden]{display:none}
          /* Brand-blue Fluent header. */
          #view-fleet2 .sched-vans-rules-popover > .sched-vans-rules-head{
            display:flex;align-items:center;gap:9px;
            background:linear-gradient(135deg,var(--accent),#1E40AF);color:#fff;
            font-size:14px;font-weight:600;letter-spacing:.005em;
            padding:13px 18px;border:0;border-radius:8px 8px 0 0;margin:0;
          }
          #view-fleet2 .sched-vans-rules-popover > .sched-vans-rules-head *{color:#fff}
          #view-fleet2 .sched-vans-rules-popover > .sched-vans-rules-head > svg{
            width:16px;height:16px;flex:0 0 auto;
          }
          #view-fleet2 .sched-vans-rules-popover .sched-vans-rules-head-title{
            font-size:14px;font-weight:600;
          }
          #view-fleet2 .sched-vans-rules-info{
            margin-left:auto;display:inline-flex;align-items:center;justify-content:center;
            width:22px;height:22px;border-radius:50%;
            background:transparent;border:0;cursor:pointer;padding:0;
          }
          /* Light Fluent body + the rule rows. */
          #view-fleet2 .sched-vans-rules-popover .sched-smartfill-rules-body{
            display:block;column-count:2;column-gap:20px;
            column-rule:1px solid rgba(15,23,42,.07);
            padding:8px 16px 10px;background:rgba(248,249,250,.55);
            border-radius:0 0 8px 8px;
          }
          #view-fleet2 .sched-smartfill-rule{
            display:flex;align-items:center;gap:10px;padding:8px 12px;
            font-size:13px;color:#111827;line-height:1.35;cursor:pointer;
            border-radius:4px;transition:background 80ms linear;
          }
          #view-fleet2 .sched-smartfill-rule:hover{background:rgba(15,23,42,.05)}
          #view-fleet2 .sched-smartfill-rule input[type="checkbox"]{
            width:15px;height:15px;cursor:pointer;accent-color:var(--accent);
            margin:0;flex:0 0 auto;
          }
          #view-fleet2 .sched-smartfill-rule .sf-rule-name{flex:1;line-height:1.3}

          /* KPI strip · brought to the TCP --tcp-kpi-h (46px) spec
             so Fleet's KPI bar reads identical to Schedule's joined-
             pill row. Tokens match #rr-sched-kpis.sched-kpi-pills. */
          /* KPI CONTRACT · standardized onto the --kpi-* tokens
             (app/rr-system.css) so Fleet is pixel-identical to the
             Schedule master: same shadow, border, radius, height,
             padding, gap, dot size, and value/sub typography. */
          #view-fleet2 .fl-kpi-pills{
            display:flex;flex-wrap:wrap;align-items:stretch;
            gap:0;padding:0;
            margin:0 0 var(--kpi-margin-bottom);
            background:var(--kpi-bg);
            border:1px solid var(--kpi-border);
            border-radius:var(--kpi-radius);
            box-shadow:var(--kpi-shadow);
            font:var(--rr-font-body);
            min-height:var(--kpi-height);
            overflow:hidden;
          }
          #view-fleet2 .fl-kpi-pills[hidden]{display:none}
          #view-fleet2 .fl-kpi-pill{
            display:inline-flex;align-items:center;
            gap:var(--kpi-gap);
            padding:var(--kpi-pad-y) var(--kpi-pad-x);
            border-right:1px solid var(--kpi-divider);
            font:var(--rr-font-body);font-weight:600;
            color:var(--kpi-text-primary);
            font-variant-numeric:tabular-nums;
            line-height:1.2;
            min-height:var(--kpi-height);
            cursor:pointer;
            transition:background var(--t-fast);
          }
          #view-fleet2 .fl-kpi-pill:last-child{border-right:0}
          #view-fleet2 .fl-kpi-pill:hover{background:rgba(15,23,42,.04)}
          #view-fleet2 .fl-kpi-pill:focus-visible{
            outline:none;box-shadow:inset 0 0 0 2px var(--accent);
          }
          #view-fleet2 .fl-kpi-dot{
            width:var(--kpi-dot-size);height:var(--kpi-dot-size);
            border-radius:50%;flex:0 0 auto;background:var(--kpi-dot-neutral);
          }
          #view-fleet2 .fl-kpi-dot.green{background:var(--kpi-success)}
          #view-fleet2 .fl-kpi-dot.amber{background:#B45309}
          #view-fleet2 .fl-kpi-dot.red{background:var(--kpi-danger)}
          #view-fleet2 .fl-kpi-text{
            display:inline-flex;flex-direction:column;gap:1px;
            line-height:1.2;min-width:0;
          }
          #view-fleet2 .fl-kpi-line{
            font:var(--kpi-value-font);color:var(--kpi-text-primary);
            font-variant-numeric:tabular-nums;
          }
          #view-fleet2 .fl-kpi-value{font-weight:600}
          #view-fleet2 .fl-kpi-frac{color:var(--kpi-text-secondary);font-weight:500}
          #view-fleet2 .fl-kpi-name{color:var(--rr-fg-secondary);font-weight:600;margin-left:4px}
          #view-fleet2 .fl-kpi-sub{
            font:var(--kpi-label-font);color:var(--kpi-text-secondary);
          }

          /* Drill-down slide-over — reuses the Fleet drawer cosmetics
             (sticky head, body scroller) but stays self-contained so we
             don't fight existing van-drawer state. */
          /* Inline FEM / VORR drill-down — expands beneath the KPI
             cards (matches the dashboard's other KPI drill-downs).
             The slide-over treatment was replaced with an in-page
             panel so the drill-down stays in the operator's flow. */
          .fl-exec-drawer{
            display:block;background:transparent;
            margin:var(--s-2) 0 var(--s-3);
          }
          .fl-exec-panel{
            width:100%;max-width:100%;
            background:var(--surface);
            border:1px solid var(--sch-line,var(--border));
            border-radius:8px;
            box-shadow:0 1px 4px rgba(15,23,42,.04);
            overflow:visible;
            animation:flExecExpand .18s ease-out;
          }
          @keyframes flExecExpand{from{opacity:0;transform:translateY(-4px)}to{opacity:1;transform:none}}
          .fl-exec-panel .head{
            padding:var(--s-4) var(--s-5);
            border-bottom:1px solid var(--border-subtle);
            display:flex;align-items:flex-start;justify-content:space-between;
            gap:var(--s-3);background:var(--surface);
          }
          .fl-exec-panel .head h2{
            margin:0;font-size:var(--fs-lg);font-weight:700;letter-spacing:-.01em;color:var(--text);
          }
          .fl-exec-panel .head p{
            margin:4px 0 0;font-size:var(--fs-sm);color:var(--text-subtle);
          }
          .fl-exec-panel .close{
            background:transparent;border:1px solid transparent;border-radius:var(--r-md);
            width:32px;height:32px;display:inline-flex;align-items:center;justify-content:center;
            color:var(--text-subtle);cursor:pointer;
            transition:background var(--t-fast), color var(--t-fast);
          }
          .fl-exec-panel .close:hover{background:var(--canvas);color:var(--text)}
          .fl-exec-panel .close svg{width:16px;height:16px}
          .fl-exec-panel .body{padding:var(--s-4) var(--s-6) var(--s-6);flex:1}

          .fl-exec-row{
            display:grid;grid-template-columns:1.5fr 1fr 1fr 1fr;
            gap:var(--s-3);align-items:center;
            padding:var(--s-3) 0;
            border-bottom:1px solid var(--border-subtle);
          }
          .fl-exec-row:last-child{border-bottom:none}
          .fl-exec-row .who{display:flex;flex-direction:column;gap:2px;min-width:0}
          .fl-exec-row .who .name{font-size:var(--fs-base);font-weight:600;color:var(--text)}
          .fl-exec-row .who .sub{font-size:var(--fs-xs);color:var(--text-subtle)}
          .fl-exec-row .days{
            font-size:18px;font-weight:700;color:var(--text);
            font-variant-numeric:tabular-nums;
          }
          .fl-exec-row .days .u{font-size:var(--fs-xs);color:var(--text-subtle);font-weight:500;margin-left:3px}
          .fl-exec-row .badge{
            display:inline-flex;align-items:center;gap:6px;
            font-size:var(--fs-xs);font-weight:700;letter-spacing:.04em;text-transform:uppercase;
            padding:2px var(--s-2);border-radius:var(--r-pill);white-space:nowrap;
          }
          .fl-exec-row .badge.healthy{background:var(--green-soft);color:var(--green)}
          .fl-exec-row .badge.warning{background:var(--amber-soft);color:var(--amber-dark)}
          .fl-exec-row .badge.at_risk{background:var(--amber-soft-strong);color:var(--amber-dark)}
          .fl-exec-row .badge.violation{background:var(--red-soft);color:var(--red)}
          .fl-exec-row .badge.grounded{background:var(--red-soft);color:var(--red)}
          .fl-exec-row .action{
            font-size:var(--fs-sm);color:var(--text-muted);text-align:right;line-height:1.4;
          }
          .fl-exec-row .action.crit{color:var(--red);font-weight:600}
          .fl-exec-row .action.warn{color:var(--amber-dark);font-weight:600}

          .fl-exec-empty{
            padding:var(--s-8) var(--s-4);text-align:center;color:var(--text-subtle);
          }
          .fl-exec-empty .ic{
            width:48px;height:48px;border-radius:var(--r-lg);
            margin:0 auto var(--s-3);
            display:flex;align-items:center;justify-content:center;
            color:var(--green);background:var(--green-soft);
          }
          .fl-exec-empty .ic svg{width:22px;height:22px}
          .fl-exec-empty h3{margin:0 0 4px;font-size:var(--fs-base);font-weight:700;color:var(--text)}
          .fl-exec-empty p{margin:0;font-size:var(--fs-md);max-width:380px;margin-inline:auto}

