          #view-email .em-cmd-tab{
            appearance:none;background:transparent;cursor:pointer;font:inherit;
            font-size:11px;font-weight:600;letter-spacing:.04em;text-transform:uppercase;
            color:var(--rr-fg-secondary);
            padding:var(--rr-space-60) var(--rr-space-120);
            border:1px solid transparent;border-bottom:0;
            border-radius:var(--rr-radius-medium) var(--rr-radius-medium) 0 0;
            transition:color var(--rr-motion-fast);
          }
          #view-email .em-cmd-tab:hover:not(.active){background:transparent}
          #view-email .em-cmd-tab.active{
