#rr-sched-smartfill-rules-popover.rr-sf-compact{min-width:250px !important}
#rr-sched-smartfill-rules-popover.rr-sf-compact .sf2-presets{padding:12px 14px 14px}
#rr-sched-smartfill-rules-popover.rr-sf-compact .sf2-presets-row{
  display:flex !important;
  flex-direction:column !important;
  align-items:stretch !important;
  gap:8px !important;
}
/* Plain text rows (operator 2026-06-12): no per-option border, left-
   justified, regular weight — hover tint alone marks the row. */
#rr-sched-smartfill-rules-popover.rr-sf-compact .sf2-preset{
  display:flex !important;
  align-items:center !important;
  justify-content:flex-start !important;
  text-align:left !important;
  height:34px !important;
  padding:0 10px !important;
  border:0 !important;
  border-radius:7px !important;
  background:transparent !important;
  color:var(--sidebar-bg,#0F172A) !important;
  font-size:12.5px !important;
  font-weight:400 !important;
