}
#rr-sched-smartfill-rules-popover.rr-sf-compact .sf2-preset{
  height:30px !important;
  gap:7px !important;
  font-size:12px !important;
}
/* Selected = checkmark, never a border/box. */
#rr-sched-smartfill-rules-popover.rr-sf-compact .sf2-preset.active{
  background:transparent !important;
  border:0 !important;
  box-shadow:none !important;
