#rr-sched-smartfill-rules-popover.rr-sf-compact .sf2-preset.active .sf2-preset-check{display:inline-flex}
/* Click-to-reveal explanation line under a row (compact only). */
.sf2-preset-desc{display:none}
#rr-sched-smartfill-rules-popover.rr-sf-compact .sf2-preset-desc.is-open{
