}
#rr-sched-colors-popover .rr-sched-routecolor-opt > input{
  grid-column:2;grid-row:1;justify-self:start;width:14px;height:14px;margin:0 !important;
}
#rr-sched-colors-popover .rr-sched-routecolor-opt > span{
