}
#rr-sched-colors-popover #rr-sched-routecolor-legend{
  display:flex;flex-direction:column;gap:2px !important;margin-top:4px !important;
}
#rr-sched-colors-popover #rr-sched-routecolor-legend > div{
  border:0 !important;background:transparent !important;padding:0 !important;border-radius:0 !important;
}
#rr-sched-colors-popover .rr-rcp-row{
  display:grid !important;
  grid-template-columns:minmax(0,1fr) 165px !important;
  column-gap:10px !important;align-items:center !important;
