/* ═══ Action-bar busy signal (operator 2026-06-12) ══════════════════
   Understated working state for Smart Fill / Assign Fleet: inline
   spinner, button locked, slim shimmer bar under the action bar. */
.rr-ab-busy{
  pointer-events:none !important;
  opacity:.78;
}
.rr-ab-busy-spin{display:inline-flex;align-items:center;margin-right:6px}
.rr-ab-busy-spin svg{width:13px;height:13px}
.rr-sf-spin{animation:rrSfSpin 1s linear infinite;transform-origin:50% 50%}
@keyframes rrSfSpin{to{transform:rotate(360deg)}}
#rr-ab-progress{
  position:absolute;left:0;right:0;bottom:-6px;height:2px;
  border-radius:2px;overflow:hidden;pointer-events:none;
  background:rgba(37,99,235,.15);
}
#rr-ab-progress::after{
  content:"";position:absolute;top:0;bottom:0;width:36%;
  border-radius:2px;
  background:var(--sidebar-bg, #0F172A);
  animation:rrAbProgress 1.2s ease-in-out infinite;
}
#rr-ab-progress[hidden]{display:none}
@keyframes rrAbProgress{
  0%{left:-36%}
  100%{left:100%}
}

/* ═══ Smart Fill · full-page settings view (operator 2026-06-13) ═══════
   The "Smart Fill" sidebar item opens this roomy page over the schedule
   grid. The Rules + Schedule Colors popovers are re-homed into it and
   styled inline via .rr-as-page (see live.js _rrOpenSmartFillPage). Only
   #view-schedule is covered, so the sidebar stays reachable to navigate
   back out. */
#view-schedule { position: relative; }
/* Overlay-pin context for the Onboarding view-switcher strip (#rr-ob-viewseg),
   mirroring #view-schedule above. */
#view-onboarding-ops { position: relative; }
.rr-smartfill-page{
  position:absolute; inset:0; z-index:60;
  background:var(--canvas, #F4F6FA);
  overflow:auto; display:flex; flex-direction:column;
}
.rr-smartfill-page[hidden]{ display:none; }
.rr-sf-page-head{
  position:sticky; top:0; z-index:2;
  display:flex; align-items:center; justify-content:space-between; gap:12px;
  padding:13px 20px; background:var(--sidebar-bg, #0F172A); color:#fff;
}
.rr-sf-page-headings{ display:flex; flex-direction:column; gap:3px; min-width:0; }
.rr-sf-page-title{ font-size:16px; font-weight:600; letter-spacing:.01em; }
.rr-sf-page-sub{ font-size:12.5px; font-weight:400; color:rgba(255,255,255,.72); }
.rr-sf-page-done{
  background:rgba(255,255,255,.16); color:#fff; border:0; border-radius:8px;
  padding:7px 18px; font-size:13px; font-weight:600; cursor:pointer;
  flex:0 0 auto;
}
.rr-sf-page-done:hover{ background:rgba(255,255,255,.28); }

/* ── Shared card chrome ─────────────────────────────────────────────── */
.rr-sf-card{
