  box-shadow:0 1px 3px rgba(15,23,42,.06); padding:18px 20px;
}
.rr-sf-card[hidden]{ display:none; }

/* ── Preset cards row ────────────────────────────────────────────────── */
.rr-sf-cards3{ display:grid; grid-template-columns:repeat(3,1fr); gap:18px; }
@media (max-width:880px){ .rr-sf-cards3{ grid-template-columns:1fr; } }
.rr-sf-mini{ display:flex; flex-direction:column; gap:14px; }
.rr-sf-mini-head{ display:flex; align-items:flex-start; gap:11px; }
.rr-sf-mini-ic{
  flex:0 0 auto; width:34px; height:34px; border-radius:9px;
  display:flex; align-items:center; justify-content:center;
}
.rr-sf-mini-ic svg{ width:19px; height:19px; }
.rr-sf-ic-limits{ background:rgba(37,99,235,.10); color:#2563EB; }
.rr-sf-ic-prefs{ background:rgba(124,58,237,.11); color:#7C3AED; }
.rr-sf-ic-safety{ background:rgba(22,163,74,.11); color:#16A34A; }
.rr-sf-ic-adv{ background:rgba(100,116,139,.13); color:#475569; }
.rr-sf-mini-titles{ min-width:0; }
.rr-sf-mini-title{ font-size:14px; font-weight:600; color:#0F172A; }
.rr-sf-mini-sub{ font-size:12px; color:#64748B; margin-top:2px; line-height:1.35; }
.rr-sf-field{ display:flex; flex-direction:column; gap:5px; }
.rr-sf-field > label{ font-size:12px; font-weight:500; color:#475569; }
.rr-sf-input{
  width:100%; box-sizing:border-box; appearance:auto;
  padding:8px 11px; font-size:13px; color:#0F172A; background:#fff;
  border:1px solid #D7DCE3; border-radius:8px; cursor:pointer;
}
.rr-sf-input:hover{ border-color:#B9C2CE; }
.rr-sf-input:focus{ outline:0; border-color:#2563EB; box-shadow:0 0 0 3px rgba(37,99,235,.12); }
.rr-sf-edit{
  margin-top:auto; align-self:flex-start; background:transparent; border:0; padding:2px 0;
  font-size:13px; font-weight:600; color:#2563EB; cursor:pointer;
  display:inline-flex; align-items:center; gap:4px;
}
.rr-sf-edit:hover{ color:#1D4ED8; }
.rr-sf-edit span{ font-size:15px; line-height:1; }

/* ── Advanced Rules section — header + three preset-style cards ───────── */
.rr-sf-adv-head{ display:flex; align-items:flex-start; gap:11px; }
.rr-sf-adv-headings{ flex:1 1 auto; min-width:0; }
.rr-sf-badge-count{
  flex:0 0 auto; align-self:center; font-size:12px; font-weight:600; color:#2563EB;
  background:rgba(37,99,235,.10); border-radius:999px; padding:3px 11px;
}
.rr-sf-adv-toggle{
  flex:0 0 auto; align-self:center; width:28px; height:28px; border:0; border-radius:7px;
  background:transparent; color:#64748B; cursor:pointer;
  display:flex; align-items:center; justify-content:center;
}
.rr-sf-adv-toggle:hover{ background:rgba(15,23,42,.05); }
.rr-sf-adv-toggle svg{ width:12px; height:12px; transition:transform .15s; }
.rr-sf-advanced.rr-collapsed .rr-sf-adv-toggle svg{ transform:rotate(180deg); }
.rr-sf-advanced.rr-collapsed .rr-sf-adv-body{ display:none; }
.rr-sf-adv-body{ margin-top:16px; }
/* "N active" pill that sits under each advanced card's heading. */
.rr-sf-active-pill{
  align-self:flex-start; font-size:12px; font-weight:600; color:#16A34A;
  background:rgba(22,163,74,.10); border-radius:999px; padding:3px 11px;
}
/* Per-group icon tints (echo the preset-card icon badges). */
.rr-sf-ic-quality{ background:rgba(217,119,6,.12); color:#D97706; }
.rr-sf-ic-route{ background:rgba(13,148,136,.12); color:#0D9488; }
.rr-sf-ic-optimization{ background:rgba(37,99,235,.10); color:#2563EB; }
.rr-sf-viewall{
  margin-top:14px; background:transparent; border:0; padding:2px 0;
  font-size:13px; font-weight:600; color:#2563EB; cursor:pointer;
  display:inline-flex; align-items:center; gap:4px;
}
.rr-sf-viewall:hover{ color:#1D4ED8; }
.rr-sf-viewall span{ font-size:15px; line-height:1; }

/* Detailed editor host — re-homed Rules + Colors boxes stack here. */
.rr-sf-detail{ display:flex; flex-direction:column; gap:22px; }
.rr-sf-detail[hidden]{ display:none; }

/* ── Sticky footer ───────────────────────────────────────────────────── */
.rr-sf-page-foot{
  position:sticky; bottom:0; z-index:3;
  display:flex; align-items:center; justify-content:space-between; gap:12px;
  padding:12px 20px; background:#fff; border-top:1px solid #E5E8ED;
}
.rr-sf-foot-saved{ display:flex; align-items:center; gap:8px; font-size:13px; color:#475569; }
.rr-sf-foot-saved svg{ width:17px; height:17px; color:#16A34A; flex:0 0 auto; }
.rr-sf-foot-actions{ display:flex; align-items:center; gap:10px; }
.rr-sf-foot-reset{
  background:#fff; color:#334155; border:1px solid #D7DCE3; border-radius:8px;
  padding:8px 16px; font-size:13px; font-weight:600; cursor:pointer;
}
.rr-sf-foot-reset:hover{ background:#F8FAFC; border-color:#C7D0DC; }
.rr-sf-foot-save{
  background:#2563EB; color:#fff; border:0; border-radius:8px;
  padding:8px 18px; font-size:13px; font-weight:600; cursor:pointer;
}
.rr-sf-foot-save:hover{ background:#1D4ED8; }
.rr-sf-foot-save:disabled{ opacity:.6; cursor:default; }
.rr-sf-page-body{
  flex:1 1 auto; width:100%; max-width:1080px; margin:0 auto;
  padding:22px 20px 48px; display:flex; flex-direction:column; gap:22px;
}
/* Re-homed Rules + Colors boxes render as inline page cards, not drawers. */
.rr-smartfill-page .rr-as-page{
  position:static !important; inset:auto !important; transform:none !important;
  display:flex !important; flex-direction:column !important;
  width:100% !important; max-width:none !important; min-width:0 !important;
  height:auto !important; max-height:none !important; margin:0 !important;
  border:1px solid #E5E8ED !important; border-radius:14px !important;
  box-shadow:0 1px 3px rgba(15,23,42,.06) !important; overflow:visible !important;
}
.rr-smartfill-page .rr-as-page[hidden]{ display:flex !important; }
/* The boxes keep their own header; drop the popover close X — the page's
   Done button + the Rules box's Save/Cancel handle exit. */
.rr-smartfill-page .rr-as-page .rr-pol-close,
.rr-smartfill-page .rr-as-page #rr-colors-close{ display:none !important; }
/* Inner bodies grow with the page rather than scrolling internally. */
.rr-smartfill-page .rr-as-page #rr-sched-smartfill-rules-body,
.rr-smartfill-page .rr-as-page .sched-smartfill-rules-body,
.rr-smartfill-page .rr-as-page .rr-colors-body{
  max-height:none !important; height:auto !important; overflow:visible !important;
}

/* The Rules box is a .rr-policy-drawer positioned by high-specificity
   #id#id !important rules, so the .rr-as-page override above (a class
   selector) loses to them and the box renders position:absolute → out of
   flow → invisible in the page (only Colors showed). Re-assert the inline
   layout with a matching #id#id specificity so it flows as a page card. */
.rr-smartfill-page #rr-sched-smartfill-rules-popover#rr-sched-smartfill-rules-popover.rr-as-page{
  position:static !important; inset:auto !important;
  top:auto !important; right:auto !important; bottom:auto !important; left:auto !important;
  transform:none !important;
  display:flex !important; flex-direction:column !important;
  width:100% !important; max-width:none !important; min-width:0 !important;
  height:auto !important; max-height:none !important; margin:0 !important;
}

/* ── Modern-panel re-theme · Stage 1 ───────────────────────────────────
   In the page the revealed editor should read as light panels, not the
   dark / brand-blue floating popovers. Page-scoped (#rr-smartfill-page) so
   the caret-menu popovers elsewhere keep their original chrome. The card
   border/radius/shadow already come from .rr-as-page; here we light the
   header bars + container surface and darken their text. */
#view-schedule #rr-smartfill-page #rr-sched-smartfill-rules-popover,
#view-schedule #rr-smartfill-page #rr-sched-colors-popover{
  background:#fff !important;
  -webkit-backdrop-filter:none !important; backdrop-filter:none !important;
}
#view-schedule #rr-smartfill-page #rr-sched-smartfill-rules-popover > :first-child,
#view-schedule #rr-smartfill-page #rr-sched-colors-popover .rr-pol-head{
  background:#fff !important; background-image:none !important;
  border-bottom:1px solid #EEF1F5 !important;
  border-radius:14px 14px 0 0 !important;
  padding:15px 18px !important;
}
#view-schedule #rr-smartfill-page #rr-sched-smartfill-rules-popover > :first-child *,
#view-schedule #rr-smartfill-page #rr-sched-colors-popover .rr-pol-head,
#view-schedule #rr-smartfill-page #rr-sched-colors-popover .rr-pol-title{
  color:#0F172A !important;
}
#view-schedule #rr-smartfill-page #rr-sched-smartfill-rules-popover > :first-child{
  font-size:14px !important; font-weight:600 !important; letter-spacing:0 !important;
}
/* Body surface → solid white so the inner section cards sit on a clean panel. */
#view-schedule #rr-smartfill-page #rr-sched-smartfill-rules-popover > :last-child,
#view-schedule #rr-smartfill-page #rr-sched-colors-popover .rr-colors-body{
  background:#fff !important;
}

/* ── Modern-panel rebuild · Stage 2 · consistent advanced formatting ────
