  transform:rotate(180deg) !important;
}
/* Dropdown panel · white card, navy outline, drops under the trigger. */
#view-onboarding-ops[data-obsub="calendar"] .rr-cal-viewdd-menu{
  position:absolute !important; top:calc(100% + 6px) !important; left:0 !important; z-index:80 !important;
  display:flex !important; flex-direction:column !important; gap:2px !important;
