  background:#FFFFFF !important; border:1.5px solid var(--sidebar-bg, #0F172A) !important; border-radius:8px !important;
  box-shadow:0 10px 28px rgba(15,23,42,.16), 0 2px 6px rgba(15,23,42,.08) !important;
}
#view-onboarding-ops[data-obsub="calendar"] .rr-cal-viewdd-menu[hidden]{ display:none !important; }
/* Menu rows · the original view buttons, restyled from pills to full-width
