  display:flex !important; flex-direction:row !important; align-items:center !important; justify-content:flex-start !important;
  gap:0 !important; width:100% !important; min-width:0 !important; height:34px !important; padding:0 12px !important; margin:0 !important;
  background:transparent !important; color:var(--sidebar-bg, #0F172A) !important;
  border:0 !important; border-radius:6px !important; box-shadow:none !important;
  font-size:13px !important; font-weight:500 !important; line-height:1 !important; white-space:nowrap !important;
  text-align:left !important; cursor:pointer !important;
}
#view-onboarding-ops[data-obsub="calendar"] .rr-cal-viewgroup .rr-cal-viewdd-menu .rr-cal-vtab > svg{ display:none !important; }
#view-onboarding-ops[data-obsub="calendar"] .rr-cal-viewgroup .rr-cal-viewdd-menu .rr-cal-vtab:hover{
  background:rgba(15,23,42,.05) !important; color:var(--sidebar-bg, #0F172A) !important;
}
/* Active view row · light-blue highlight + navy-blue bold (the selected option). */
#view-onboarding-ops[data-obsub="calendar"] .rr-cal-viewgroup .rr-cal-viewdd-menu .rr-cal-vtab.active{
  background:#EFF6FF !important; color:#1E40AF !important; font-weight:600 !important;
