#view-onboarding-ops[data-obsub="calendar"] .rr-cal-sync{
  /* order:-1 floats the sync pill to the front of the right-hand action group,
     so it sits in line just before Schedule Interview / Add calendar. */
  display:inline-flex; align-items:center; gap:8px; flex:0 0 auto; order:-1;
  height:34px; padding:0 13px; border-radius:999px;
  background:rgba(22,163,74,.08); border:1px solid rgba(22,163,74,.22);
  font-size:12.5px; font-weight:600; color:#15803D; white-space:nowrap;
}
#view-onboarding-ops[data-obsub="calendar"] .rr-cal-sync-dot{
  width:8px; height:8px; border-radius:50%; background:#16A34A; box-shadow:0 0 0 3px rgba(22,163,74,.16);
}

/* ── KPI strip ───────────────────────────────────────────────────────── */
#view-onboarding-ops[data-obsub="calendar"] .rr-cal-kpis{
  display:grid; grid-template-columns:repeat(4, minmax(0,1fr)); gap:12px; width:100%;
}
#view-onboarding-ops[data-obsub="calendar"] .rr-kpi{
  display:flex; align-items:center; gap:13px; padding:13px 16px;
  border-radius:14px; background:var(--surface,#FFFFFF);
  border:1px solid rgba(15,23,42,.07); box-shadow:0 1px 2px rgba(15,23,42,.04);
}
#view-onboarding-ops[data-obsub="calendar"] .rr-kpi-ic{
  display:inline-flex; align-items:center; justify-content:center; flex:0 0 auto;
  width:40px; height:40px; border-radius:11px;
}
#view-onboarding-ops[data-obsub="calendar"] .rr-kpi-ic svg{ width:20px; height:20px; }
#view-onboarding-ops[data-obsub="calendar"] .rr-kpi-ic--blue{ background:rgba(37,99,235,.10); color:#2563EB; }
#view-onboarding-ops[data-obsub="calendar"] .rr-kpi-ic--indigo{ background:rgba(99,102,241,.12); color:#6366F1; }
#view-onboarding-ops[data-obsub="calendar"] .rr-kpi-ic--red{ background:rgba(220,38,38,.10); color:#DC2626; }
#view-onboarding-ops[data-obsub="calendar"] .rr-kpi-ic--amber{ background:rgba(245,158,11,.14); color:#D97706; }
#view-onboarding-ops[data-obsub="calendar"] .rr-kpi-body{ display:flex; flex-direction:column; min-width:0; }
#view-onboarding-ops[data-obsub="calendar"] .rr-kpi-label{
