#view-onboarding-ops[data-obsub="calendar"] #rr-ivcal .oc-corner{ background:#FFFFFF; }
#view-onboarding-ops[data-obsub="calendar"] #rr-ivcal .oc-dh{ padding:13px 0 13px 14px; }
#view-onboarding-ops[data-obsub="calendar"] #rr-ivcal .oc-dh .dow{
