}
#view-onboarding-ops[data-obsub="calendar"] #rr-ivcal .oc-dh .dn{
  font-size:25px; font-weight:700; color:#0F172A; margin-top:3px;
}
#view-onboarding-ops[data-obsub="calendar"] #rr-ivcal .oc-dh.today .dn{ width:36px; height:36px; }
#view-onboarding-ops[data-obsub="calendar"] #rr-ivcal .oc-dh.today .dow{ color:#2563EB; }
/* Columns — soft neutral working-hours wash; only today carries faint blue */
#view-onboarding-ops[data-obsub="calendar"] #rr-ivcal .oc-col{ background:#F8FAFC; }
#view-onboarding-ops[data-obsub="calendar"] #rr-ivcal .oc-col.today{ background:rgba(37,99,235,.05); }
#view-onboarding-ops[data-obsub="calendar"] #rr-ivcal .oc-hr span{ color:#94A3B8; font-weight:550; }
