#view-onboarding-ops[data-obsub="calendar"] #rr-ivcal .oc-ev{
  border-radius:9px; border-left-width:3px; padding:4px 8px 4px 10px;
  box-shadow:0 1px 2px rgba(15,23,42,.07), 0 2px 5px rgba(15,23,42,.05);
}
#view-onboarding-ops[data-obsub="calendar"] #rr-ivcal .oc-ev:hover{
  filter:none; box-shadow:0 3px 8px rgba(15,23,42,.14), 0 6px 16px rgba(15,23,42,.10);
}
#view-onboarding-ops[data-obsub="calendar"] #rr-ivcal .oc-ev .et{ font-weight:700; }
/* Month view */
#view-onboarding-ops[data-obsub="calendar"] #rr-ivcal .oc-mhead{ background:#FFFFFF; }
#view-onboarding-ops[data-obsub="calendar"] #rr-ivcal .oc-mdow{ color:#94A3B8; letter-spacing:.06em; }
#view-onboarding-ops[data-obsub="calendar"] #rr-ivcal .oc-mcell{ padding:4px 5px 5px; }
#view-onboarding-ops[data-obsub="calendar"] #rr-ivcal .oc-mcell.out{ background:#FAFBFC; }
#view-onboarding-ops[data-obsub="calendar"] #rr-ivcal .oc-pill{ border-radius:6px; padding:1px 6px; line-height:1.6; }

/* Responsive · KPI strip wraps to 2×2 on tighter widths */
@media (max-width: 1180px){
  #view-onboarding-ops[data-obsub="calendar"] .rr-cal-kpis{ grid-template-columns:repeat(2, minmax(0,1fr)); }
}

/* ════════════════════════════════════════════════════════════════════════
   Light pop-out headers (operator: every pop-out, every page, loses the dark
   header). The base .rr-pol-head is already white; this re-points the few
   pop-out headers still painted navy (var(--sidebar) / --sidebar-bg) to a
   white header with a dark title + muted close — matching the Staffing-Policy
   / Attendance-modal treatment. Selectors mirror the originals' specificity
   (the Smart Fill rule doubles its id) + sit last in the file, so they win.
   ════════════════════════════════════════════════════════════════════════ */
#rr-sched-smartfill-rules-popover#rr-sched-smartfill-rules-popover .sched-smartfill-rules-head.rr-pol-head,
#rr-sched-smartfill-rules-popover#rr-sched-smartfill-rules-popover .rr-pol-head,
#rr-sched-colors-popover .rr-pol-head,
.rr-reqd-head,
.rr-reqset-head{
  background:#FFFFFF !important;
  color:#0F172A !important;
  border-bottom:1px solid #EEF0F4 !important;
}
#rr-sched-smartfill-rules-popover#rr-sched-smartfill-rules-popover .rr-pol-title,
#rr-sched-colors-popover .rr-pol-title,
.rr-reqd-title,
.rr-reqset-title{ color:#0F172A !important; }
.rr-reqd-sub,
.rr-reqset-help{ color:#64748B !important; }
#rr-sched-smartfill-rules-popover#rr-sched-smartfill-rules-popover .rr-pol-close,
#rr-sched-smartfill-rules-popover#rr-sched-smartfill-rules-popover .rr-pol-head .rr-pol-close svg,
#rr-sched-colors-popover .rr-pol-close,
.rr-reqd-close{ color:#64748B !important; }
#rr-sched-colors-popover .rr-pol-close:hover,
.rr-reqd-close:hover{ background:rgba(15,23,42,.06) !important; color:#0F172A !important; }

/* ════════════════════════════════════════════════════════════════════════
   App launcher · Google-style grid menu in the schedule action bar, next to
   the coverage card. Grid button → 3-column pop-out (Operations / People /
   Business). ════════════════════════════════════════════════════════════ */
.rr-applauncher{ position:relative; display:inline-flex; align-items:center; }
.rr-al-btn{
  width:32px; height:32px; flex:0 0 auto; padding:0;
  display:inline-flex; align-items:center; justify-content:center;
  /* Premium refinement pass (operator): soft warm yellow with a near-
     imperceptible vertical gradient + a faint top highlight for restrained
     depth; very-light neutral hairline; soft drop shadow; squircle corners.
     Charcoal dots live on the SVG. Footprint unchanged (32×32). */
  border:1px solid rgba(0,0,0,.06); border-radius:14px;
  background:
    linear-gradient(180deg, rgba(255,255,255,.45), rgba(255,255,255,0) 45%),
    linear-gradient(180deg, #FCEAA8, #F7E199);
  box-shadow:0 2px 6px rgba(0,0,0,.08);
  color:var(--text-muted, #64748B); cursor:pointer;
  /* GPU-accelerated, ease-out, no bounce / no spring. */
  transition:transform .2s ease-out, box-shadow .2s ease-out, border-color .2s ease-out;
  will-change:transform;
}
.rr-al-btn svg{ width:16px; height:16px; }
/* Hover · lifts toward the user: brighter fill, larger soft shadow, a small
   rise + 1.02 scale. */
.rr-al-btn:hover{
  background:
    linear-gradient(180deg, rgba(255,255,255,.5), rgba(255,255,255,0) 45%),
    linear-gradient(180deg, #FDEEB4, #F9E6A4);
  border-color:rgba(0,0,0,.10);
  box-shadow:0 6px 16px rgba(0,0,0,.12);
  transform:translateY(-1.5px) scale(1.02);
}
/* Pressed · physical button: drops down, shadow collapses to an inset, fill
   darkens, quick. */
.rr-al-btn:active{
  background:
    linear-gradient(180deg, rgba(255,255,255,.2), rgba(255,255,255,0) 45%),
    linear-gradient(180deg, #F3DA8C, #EDCE78);
  transform:translateY(1px) scale(1);
  box-shadow:0 1px 2px rgba(0,0,0,.10), inset 0 2px 3px rgba(0,0,0,.12), inset 0 1px 0 rgba(255,255,255,.25);
  transition-duration:.1s;
}
/* Open (menu showing) · a settled, slightly-darker "pressed-in" rest state. */
.rr-al-btn[aria-expanded="true"]{
  background:linear-gradient(180deg, #F4DC92, #EFD180);
  border-color:rgba(0,0,0,.10);
  box-shadow:0 1px 3px rgba(0,0,0,.08), inset 0 1px 2px rgba(0,0,0,.08);
  transform:none;
}
.rr-al-panel{
  position:fixed; z-index:130; /* left/top set by JS (place()) so the rail can't clip it */
  display:flex; flex-direction:column; gap:2px;
  width:280px; padding:16px; background:#FFFFFF;
  border:1px solid rgba(15,23,42,.08); border-radius:16px;
  box-shadow:0 20px 50px -12px rgba(15,23,42,.28), 0 6px 16px -8px rgba(15,23,42,.14);
}
.rr-al-panel[hidden]{ display:none; }
/* Sidebar-blue "icon card" inside the white pop-out — the apps + utility items
   ride this card; the account actions (Settings / Sign out) stay on the white
   panel below it. Icon tiles go white so the colored glyphs pop on the blue. */
.rr-al-card{
  display:flex; flex-direction:column; gap:2px;
  background:#EFF6FF; border-radius:12px; padding:8px;
}
.rr-al-card .rr-al-item:hover{ background:#FFFFFF; }
/* App-switcher section at the top of the drawer (mirrors sidebar nav). */
.rr-al-apps{ display:flex; flex-direction:column; gap:2px; }
.rr-al-apps:not(:empty){ margin-bottom:6px; padding-bottom:6px; border-bottom:1px solid rgba(15,23,42,.08); }
/* "Soon" tag on not-yet-built apps (Vault, Reports). */
.rr-al-soon{
  margin-left:auto; align-self:center;
  font-size:10px; font-weight:700; letter-spacing:.04em; text-transform:uppercase;
  color:#64748B; background:#F1F5F9; border-radius:999px; padding:2px 8px;
}
.rr-al-col{ display:flex; flex-direction:column; gap:2px; }
.rr-al-colhd{ font-size:12px; font-weight:700; color:#0F172A; padding:0 8px 8px; }
.rr-al-item{
  display:flex; align-items:center; gap:12px; width:100%;
  padding:8px; border:0; background:transparent; border-radius:10px;
  text-align:left; cursor:pointer; font:inherit; font-size:14px; font-weight:500; color:#1F2937;
  transition:background-color .12s ease;
}
.rr-al-item:hover{ background:#F3F4F6; }
.rr-al-ico{
  width:38px; height:38px; flex:0 0 auto;
  display:inline-flex; align-items:center; justify-content:center;
  border-radius:11px; background:#FFFFFF; border:1px solid transparent; color:#334155;
  transition:background-color .12s ease, border-color .12s ease, color .12s ease;
}
.rr-al-ico svg{ width:20px; height:20px; }
/* Multi-tone app icons · match the Google Workspace launcher feel (operator
   request): each app's glyph + tile carries its own brand hue, floating on
   the panel's soft shadow. Defined after the base rule so the color holds on
   hover too — the row's own :hover background is the hover feedback. */
.rr-al-item[data-al-go="schedule"] .rr-al-ico       { color:#2563EB; }
.rr-al-item[data-al-go="onboarding-ops"] .rr-al-ico { color:#15A34A; }
.rr-al-item[data-al-go="fleet2"] .rr-al-ico         { color:#0E7490; }
.rr-al-item[data-al-go="messages"] .rr-al-ico       { color:#7C3AED; }
.rr-al-item[data-al-go="email"] .rr-al-ico          { color:#E11D48; }
.rr-al-item[data-al-go="admin"] .rr-al-ico          { color:#4F46E5; }
.rr-al-item[data-al-act="drive"] .rr-al-ico         { color:#D97706; }
.rr-al-item[data-al-act="reports"] .rr-al-ico       { color:#64748B; }
.rr-al-item[data-al-act="indeed"] .rr-al-ico        { color:#2557A7; }
.rr-al-item[data-al-act="adpsync"] .rr-al-ico       { color:#D0271D; }

/* ════════════════════════════════════════════════════════════════════════
   Unified pop-out framing · "make every pop-out look like the app launcher"
   ─────────────────────────────────────────────────────────────────────────
   Every dropdown / rules / settings pop-out now wears the launcher's frame:
   an opaque-white surface (no acrylic / glass), a faint hairline edge that
   reads as borderless, the launcher's soft two-layer shadow and 14px rounded
   corners. inline-styles.css loads last, so these win same-specificity ties;
   the schedule-rrx / onboarding-rrx frames use !important, so the rules
   pop-outs are matched at id-level specificity (two ids out-rank a
   one-id-two-class view rule) and re-declared !important. The JS-built
   pop-outs set their frame with plain inline styles, which !important here
   beats. Centred modals, side drawers, the windowed interview-event editor
   and the intentionally-tinted forecast / recurrence pops are left alone.
   Header colours were handled in the earlier white-header pass; the one
   exception is the onboarding rules pop-out, whose leftover navy band that
   pass missed is whitened at the bottom of this block.
   ════════════════════════════════════════════════════════════════════════ */
/* ── Container frame ─────────────────────────────────────────────────────*/
.popover,
.rr-qat-menu,
.hdr-undo-menu,
.rr-tf-popover,
.oc-menu, .oc-quick, .oc-hover,
.rr-ob-rules-chooser,
.cl-rn-meta-pop, .cl-launch-pop,
.rr-reqset-pop,
.sched-kpi-config-popover,
#rr-pol-info-pop,
#rr-sched-colors-popover,
#view-schedule .rr-ab-menu,
#view-schedule #rr-sched-targets-kpis .rr-tgt-kpi-menu,
#view-onboarding-ops[data-obsub="calendar"] .rr-cal-viewdd-menu,
#view-schedule #rr-sched-smartfill-rules-popover,
#view-schedule #rr-sched-vans-rules-popover,
#view-schedule #rr-sched-quick-settings-popover,
#view-schedule #rr-sched-milestone-rules-popover,
#view-onboarding-ops.rrx-onboarding .ob-rules-popover,
#rr-recruiting-chooser,
#rr-att-ev-pop,
#rr-tp-vp-pop,
#rr-di-menu{
  background:#FFFFFF !important;
  -webkit-backdrop-filter:none !important; backdrop-filter:none !important;
  border:1px solid rgba(15,23,42,.08) !important;
  border-radius:14px !important;
  box-shadow:0 18px 48px rgba(15,23,42,.18), 0 2px 8px rgba(15,23,42,.08) !important;
}
/* ── Full-bleed header / body corners follow the new 14px radius so no
      square corner peeks past the rounded shell (radius only — the header
      and body colours stay exactly as they are). ───────────────────────*/
#view-schedule #rr-sched-smartfill-rules-popover > :first-child,
#view-schedule #rr-sched-vans-rules-popover > :first-child,
#view-schedule #rr-sched-quick-settings-popover > :first-child,
#view-schedule #rr-sched-milestone-rules-popover > :first-child,
#view-onboarding-ops.rrx-onboarding .ob-rules-popover > :first-child{
  border-top-left-radius:14px !important;
  border-top-right-radius:14px !important;
}
#view-schedule #rr-sched-smartfill-rules-popover > :last-child,
#view-schedule #rr-sched-vans-rules-popover > :last-child,
#view-schedule #rr-sched-quick-settings-popover > :last-child,
#view-schedule #rr-sched-milestone-rules-popover > :last-child,
#view-onboarding-ops.rrx-onboarding .ob-rules-popover > :last-child{
  border-bottom-left-radius:14px !important;
  border-bottom-right-radius:14px !important;
}
/* ── Onboarding rules pop-outs (Onboarding / Funnel / Interview) still wore
      the sidebar-navy header band (--sidebar-bg resolves to #0F172A off the
      rail) — the one dark header the app-wide white-header pass missed. Bring
      it in line with the launcher and every other pop-out: white band, dark
      title + icon, hairline divider. Matched at equal specificity to the
      onboarding-rrx !important rules and re-declared !important so it wins on
      load order (inline-styles.css is the last stylesheet). ──────────────*/
#view-onboarding-ops.rrx-onboarding .ob-rules-popover > :first-child{
  background:#FFFFFF !important;
  background-image:none !important;
  color:#0F172A !important;
  border-bottom:1px solid #EEF1F5 !important;
}
#view-onboarding-ops.rrx-onboarding .ob-rules-popover > :first-child *{
  color:#0F172A !important;
}
#view-onboarding-ops.rrx-onboarding .ob-rules-popover > :first-child > svg{
  color:#334155 !important;
}

/* ════════════════════════════════════════════════════════════════════════
   App launcher · pinned to the TOP-RIGHT of every screen. placeLauncher()
   (wiring script) inserts it in-flow just left of the notifications bell on
   the views that show one (Schedule, Onboarding Funnel); on views without a
   bell (Fleet / Messages / Email / Admin) it floats in the corner via
   .rr-al-fixed, clear of the window-controls overlay. ════════════════════ */
.rr-applauncher.rr-al-fixed{
  position:fixed; top:8px; right:158px; z-index:120;
  -webkit-app-region:no-drag; app-region:no-drag;
}

/* ════════════════════════════════════════════════════════════════════════
   App-launcher account footer · Settings + Sign out, moved out of the
   retired top-right account menu. The footer spans the full panel width
   under the 3 nav columns, divided by a hairline. (Refresh app / What's
   new still live in the ⌘K command palette.) ════════════════════════════ */
.rr-al-foot{
  grid-column:1 / -1;
  display:flex; gap:6px;
  margin-top:12px; padding-top:12px;
  border-top:1px solid rgba(15,23,42,.08);
}
.rr-al-footitem{ flex:1; }
.rr-al-footitem svg{ width:18px; height:18px; flex:0 0 auto; color:#475569; }
.rr-al-footitem:hover svg{ color:#2563EB; }
.rr-al-signout{ color:#DC2626; }
.rr-al-signout svg{ color:#DC2626; }
.rr-al-signout:hover{ background:#FEF2F2; }
.rr-al-signout:hover svg{ color:#DC2626; }
/* Retire the top-right account icon app-wide — Settings + Sign out now ride
   the launcher; the bell stays put. */
#rr-hdr-avatar-btn{ display:none !important; }

/* ═══════════════════════════════════════════════════════════════════════
   ROUTEREADY DRIVE — document management workspace (#view-drive).
   Enterprise / Outlook idiom: white surfaces, hairline borders, monochrome
   icons, no gradients. Three-column shell: section rail · content · details.
   ═══════════════════════════════════════════════════════════════════════ */
.rr-drive-page{display:flex;flex-direction:column;min-height:0}
.rr-drive-shell{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:16px;align-items:stretch;height:calc(100vh - 210px);min-height:440px}
@media (max-width:980px){.rr-drive-shell{grid-template-columns:1fr;height:auto}.rr-drive-details{display:none}}

/* In-page dock for the app launcher (Drive has no bell to anchor it). The
   launcher keeps its normal docked styling, same as the Schedule action bar. */
.rr-launcher-dock{display:inline-flex;align-items:center}
.rr-launcher-dock:not(:empty){margin-left:6px;padding-left:12px;border-left:1px solid var(--border)}


/* ── Center content ──────────────────────────────────────────────────── */
.rr-drive-center{position:relative;display:flex;flex-direction:column;min-width:0;min-height:0;background:var(--surface);border:1px solid var(--border);border-radius:var(--r-lg);overflow:hidden}
.rr-drive-toolbar{display:flex;align-items:center;gap:12px;padding:12px 16px;border-bottom:1px solid var(--border);flex:0 0 auto}
.rr-drive-crumbs{display:flex;align-items:center;gap:5px;flex:0 1 auto;min-width:0;font-size:var(--fs-sm);overflow:hidden}
.rr-drive-tb-spacer{flex:1}
/* Cross-cutting view chips (Recent / Shared) — replaced the section rail. */
.rr-drive-chips{display:flex;align-items:center;gap:4px;flex:0 0 auto}
.rr-drive-chip-btn{display:inline-flex;align-items:center;gap:6px;background:none;border:1px solid transparent;border-radius:var(--r-md);padding:5px 11px;font:inherit;font-size:var(--fs-sm);font-weight:500;color:var(--text-muted);cursor:pointer;white-space:nowrap;transition:background var(--t-fast),color var(--t-fast),border-color var(--t-fast)}
.rr-drive-chip-btn:hover{background:var(--canvas);color:var(--text)}
.rr-drive-chip-btn.is-active{background:var(--accent-soft);color:var(--accent-text);font-weight:600}
.rr-drive-chip-cnt{font-size:var(--fs-xs);font-weight:600;color:var(--text-subtle);font-variant-numeric:tabular-nums}
.rr-drive-chip-btn.is-active .rr-drive-chip-cnt{color:var(--accent-text)}
.rr-drive-crumb{background:none;border:0;padding:2px 4px;font:inherit;font-size:var(--fs-sm);font-weight:600;color:var(--text-muted);cursor:pointer;white-space:nowrap;border-radius:var(--r-sm)}
.rr-drive-crumb:hover{color:var(--text);background:var(--canvas)}
.rr-drive-crumb.is-current{color:var(--text);cursor:default}
.rr-drive-crumb.is-current:hover{background:none}
.rr-drive-crumb-sep{color:var(--text-disabled);flex:0 0 auto}
.rr-drive-search{display:flex;align-items:center;gap:7px;flex:0 0 auto;width:260px;max-width:38vw;background:var(--canvas);border:1px solid var(--border);border-radius:var(--r-md);padding:6px 10px}
.rr-drive-search svg{width:15px;height:15px;flex:0 0 auto;color:var(--text-subtle)}
.rr-drive-search input{flex:1;min-width:0;background:none;border:0;outline:none;font:inherit;font-size:var(--fs-sm);color:var(--text)}
.rr-drive-vtoggle{display:inline-flex;flex:0 0 auto;background:var(--canvas);border:1px solid var(--border);border-radius:var(--r-md);padding:2px}
.rr-drive-vbtn{display:inline-flex;align-items:center;justify-content:center;width:30px;height:26px;background:none;border:0;border-radius:var(--r-sm);color:var(--text-subtle);cursor:pointer}
.rr-drive-vbtn svg{width:15px;height:15px}
.rr-drive-vbtn:hover{color:var(--text)}
.rr-drive-vbtn.is-active{background:var(--surface);color:var(--accent-text);box-shadow:var(--shadow-xs,0 1px 2px rgba(15,23,42,.08))}
.rr-drive-main{flex:1;min-height:0;overflow-y:auto;padding:18px}

/* ── Category / folder cards ─────────────────────────────────────────── */
.rr-drive-sectionhead{font-size:var(--fs-xs);font-weight:700;letter-spacing:.05em;text-transform:uppercase;color:var(--text-subtle);margin:4px 2px 12px}
.rr-drive-cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(214px,1fr));gap:12px;margin-bottom:8px}
.rr-drive-card{display:flex;align-items:flex-start;gap:12px;padding:15px;background:var(--surface);border:1px solid var(--border);border-radius:var(--r-lg);cursor:pointer;text-align:left;transition:border-color var(--t-fast),box-shadow var(--t-fast)}
.rr-drive-card:hover{border-color:var(--accent);box-shadow:var(--shadow-sm)}
.rr-drive-card-ico{flex:0 0 auto;width:50px;height:50px;border-radius:12px;background:var(--canvas);display:flex;align-items:center;justify-content:center;color:var(--text-muted)}
.rr-drive-card-ico svg{width:25px;height:25px}
.rr-drive-card-body{min-width:0;flex:1}
.rr-drive-card-name{font-size:var(--fs-md);font-weight:600;color:var(--text);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.rr-drive-card-meta{font-size:var(--fs-xs);color:var(--text-subtle);margin-top:3px}

/* ── File / folder list (list view) ──────────────────────────────────── */
.rr-drive-list{display:flex;flex-direction:column}
.rr-drive-lhead,.rr-drive-row{display:grid;grid-template-columns:1fr 130px 120px 84px 34px;gap:12px;align-items:center;padding:9px 10px}
.rr-drive-lhead{font-size:10px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;color:var(--text-subtle);border-bottom:1px solid var(--border);position:sticky;top:-18px;background:var(--surface);z-index:1}
.rr-drive-row{border-bottom:1px solid var(--border-subtle);cursor:pointer;border-radius:var(--r-sm)}
.rr-drive-row:hover{background:var(--canvas)}
.rr-drive-row.is-selected{background:var(--accent-soft)}
.rr-drive-name{display:flex;align-items:center;gap:11px;min-width:0}
.rr-drive-fico{flex:0 0 auto;width:38px;height:38px;border-radius:9px;background:var(--canvas);display:flex;align-items:center;justify-content:center;color:var(--text-subtle)}
.rr-drive-fico svg{width:20px;height:20px}
.rr-drive-fico.is-folder{color:var(--text-muted)}
.rr-drive-fico.t-pdf{color:#b42318}.rr-drive-fico.t-img{color:#0e7490}.rr-drive-fico.t-doc{color:#1d4ed8}.rr-drive-fico.t-xls{color:#15803d}
.rr-drive-name-txt{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:var(--fs-sm);font-weight:600;color:var(--text)}
.rr-drive-cell{font-size:var(--fs-xs);color:var(--text-subtle);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.rr-drive-row .rr-drive-rowact{display:flex;justify-content:flex-end;color:var(--text-disabled)}
.rr-drive-row:hover .rr-drive-rowact{color:var(--text-subtle)}
/* Clickable sort headers */
.rr-drive-sortbtn{display:inline-flex;align-items:center;gap:4px;background:none;border:0;padding:0;margin:0;font:inherit;letter-spacing:inherit;text-transform:inherit;color:inherit;cursor:pointer;text-align:left;min-width:0}
.rr-drive-sortbtn:hover,.rr-drive-sortbtn.is-active{color:var(--text-muted)}
.rr-drive-caret{font-size:8px;line-height:1}

/* Folder action bar (shown inside an open custom folder) */
.rr-drive-folderbar{display:flex;flex-direction:column;align-items:stretch;gap:8px;margin:0 2px 16px;padding-bottom:16px;border-bottom:1px solid var(--border-subtle)}
.rr-drive-folderbar-head{display:flex;align-items:center;justify-content:space-between;gap:16px}
.rr-drive-folderbar-name{display:flex;align-items:center;gap:11px;font-size:22px;line-height:1.2;font-weight:700;letter-spacing:-.01em;color:var(--text);min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.rr-drive-folderbar-name .rr-drive-fico{width:34px;height:34px}
/* Quiet metadata line under the folder anchor — real counts + last activity. */
.rr-drive-folderbar-meta{font-size:var(--fs-sm);color:var(--text-subtle);padding-left:45px;letter-spacing:.01em}
/* Folder title is editable in place — looks like the heading; click to type.
   No box/ring while editing (operator request) — just the text caret. */
.rr-drive-folderbar-rename{font:inherit;color:inherit;cursor:text;outline:none;white-space:nowrap}
.rr-drive-folderbar-rename:focus{outline:none;background:none;box-shadow:none}
.rr-drive-folderbar-acts{display:flex;gap:8px;flex:0 0 auto}

/* Multi-select checkboxes — swap with the file icon on hover / when checked */
.rr-drive-figbox{position:relative;flex:0 0 auto;width:38px;height:38px}
.rr-drive-figbox .rr-drive-fico{position:absolute;inset:0}
/* Selection check sits as a small badge on the icon's corner — the file-type
   icon stays visible underneath (it does NOT turn into a checkmark). */
.rr-drive-check{position:absolute;inset:auto;right:-3px;bottom:-3px;display:none;align-items:center;justify-content:center;width:16px;height:16px;border-radius:50%;background:var(--surface);border:1.5px solid var(--border-strong,var(--border));color:transparent;cursor:pointer;box-shadow:0 0 0 2px var(--surface);transition:background var(--t-fast),border-color var(--t-fast)}
.rr-drive-check svg{width:10px;height:10px}
.rr-drive-row:hover .rr-drive-check,.rr-drive-row.is-checked .rr-drive-check{display:flex}
.rr-drive-row.is-checked .rr-drive-check{background:var(--accent);border-color:var(--accent);color:#fff}
.rr-drive-row.is-checked{background:var(--accent-soft)}
.rr-drive-tile .rr-drive-tile-ico{position:relative}
.rr-drive-tile .rr-drive-check{inset:auto;top:-6px;left:-6px;width:22px;height:22px;border-radius:6px}
.rr-drive-tile .rr-drive-check svg{width:13px;height:13px}
.rr-drive-tile:hover .rr-drive-check,.rr-drive-tile.is-checked .rr-drive-check{display:flex}
.rr-drive-tile.is-checked .rr-drive-check{background:var(--accent);border-color:var(--accent);color:#fff}
.rr-drive-tile.is-checked{border-color:var(--accent);box-shadow:var(--shadow-sm)}

/* Contextual selection bar (replaces the toolbar while items are checked) */
.rr-drive-bulkbar{display:flex;align-items:center;gap:12px;padding:7px 4px;margin-bottom:8px;min-height:42px}
.rr-drive-bulkbar[hidden]{display:none}
.rr-drive-toolbar[hidden]{display:none}
.rr-drive-bulk-x{display:inline-flex;align-items:center;justify-content:center;width:30px;height:30px;border:0;background:none;border-radius:var(--r-sm);color:var(--text-muted);cursor:pointer}
.rr-drive-bulk-x:hover{background:var(--canvas)}
.rr-drive-bulk-x svg{width:18px;height:18px}
.rr-drive-bulk-count{font-size:var(--fs-sm);font-weight:600;color:var(--text)}
.rr-drive-bulk-acts{display:flex;gap:8px;margin-left:6px;flex-wrap:wrap}

/* Multi-select details summary */
.rr-drive-det-multi{padding:14px 16px;display:flex;flex-direction:column;gap:8px;overflow-y:auto}
.rr-drive-det-multi-item{display:flex;align-items:center;gap:10px;min-width:0}
.rr-drive-det-multi-more{font-size:var(--fs-xs);color:var(--text-subtle);padding-left:2px}

/* Drag-and-drop — dragging source, folder drop target, upload overlay */
.rr-drive-row.rr-drive-dragging,.rr-drive-tile.rr-drive-dragging{opacity:.45}
.rr-drive-card.rr-drive-dropover{border-color:var(--accent);background:var(--accent-soft);box-shadow:0 0 0 2px var(--accent) inset}
.rr-drive-dropzone{position:absolute;inset:0;z-index:6;display:flex;align-items:center;justify-content:center;background:var(--accent-soft);border:2px dashed var(--accent);border-radius:var(--r-lg);pointer-events:none}
.rr-drive-dropzone[hidden]{display:none}
.rr-drive-dropzone.is-invalid{background:var(--canvas);border-color:var(--border-strong,var(--border))}
.rr-drive-dropzone-inner{display:flex;flex-direction:column;align-items:center;gap:8px;text-align:center;color:var(--accent)}
.rr-drive-dropzone.is-invalid .rr-drive-dropzone-inner{color:var(--text-subtle)}
.rr-drive-dropzone svg{width:40px;height:40px}
.rr-drive-dropzone-title{font-size:var(--fs-md);font-weight:700;color:var(--text)}
.rr-drive-dropzone-sub{font-size:var(--fs-sm);color:var(--text-subtle)}

/* Folder customization picker (color swatches + icon choices) */
.rr-drive-style-label{font-size:10px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;color:var(--text-subtle);margin-bottom:9px}
.rr-drive-sw-row{display:flex;flex-wrap:wrap;gap:9px}
.rr-drive-sw{width:26px;height:26px;border-radius:50%;border:2px solid transparent;cursor:pointer;padding:0;outline-offset:2px;box-shadow:inset 0 0 0 1px rgba(0,0,0,.08)}
.rr-drive-sw.is-active{border-color:var(--text);box-shadow:none}
.rr-drive-sw-none{background:var(--surface);position:relative;box-shadow:inset 0 0 0 1px var(--border-strong,var(--border))}
.rr-drive-sw-none::after{content:"";position:absolute;left:3px;right:3px;top:11px;height:2px;background:var(--text-disabled);transform:rotate(-45deg)}
.rr-drive-icq-row{display:flex;flex-wrap:wrap;gap:8px}
.rr-drive-icq{width:38px;height:38px;display:flex;align-items:center;justify-content:center;border:1px solid var(--border);border-radius:var(--r-md,10px);background:var(--surface);cursor:pointer}
.rr-drive-icq svg{width:20px;height:20px}
.rr-drive-icq:hover{border-color:var(--accent)}
.rr-drive-icq.is-active{border-color:var(--accent);box-shadow:0 0 0 1px var(--accent) inset}

/* Favorite (star) on folder cards + folderbar */
.rr-drive-foldercard{position:relative}
.rr-drive-fav{position:absolute;top:8px;right:8px;width:24px;height:24px;display:none;align-items:center;justify-content:center;border-radius:6px;color:var(--text-disabled);cursor:pointer}
.rr-drive-fav svg{width:15px;height:15px}
.rr-drive-foldercard:hover .rr-drive-fav,.rr-drive-fav.is-on{display:flex}
.rr-drive-fav:hover{background:var(--canvas);color:var(--text-muted)}
.rr-drive-fav.is-on,.rr-drive-fav.is-on:hover{color:#f59e0b}
.rr-drive-folderbar-acts .btn.is-active{border-color:#f59e0b;color:#b45309}

/* Compliance view — wider status column + expiry badges */
.rr-drive-complist .rr-drive-lhead,.rr-drive-complist .rr-drive-row{grid-template-columns:minmax(0,1fr) 130px 110px 96px 132px}
.rr-drive-expbadge{display:inline-block;font-size:11px;font-weight:600;padding:2px 9px;border-radius:999px;white-space:nowrap}
.rr-drive-expbadge.is-expired{background:#fee2e2;color:#b42318}
.rr-drive-expbadge.is-soon{background:#fef3c7;color:#b45309}
.rr-drive-expbadge.is-ok{background:var(--canvas);color:var(--text-subtle)}
.rr-drive-chip-btn.rr-drive-chip-alert .rr-drive-chip-cnt{background:#fee2e2;color:#b42318}

/* Google Workspace file colors (icon tint by type) */
.rr-drive-fico.t-gdoc,.rr-drive-tile-ico.t-gdoc,.rr-drive-newico.t-gdoc,.rr-al-ico.t-gdoc{color:#1a73e8}
.rr-drive-fico.t-gsheet,.rr-drive-tile-ico.t-gsheet,.rr-drive-newico.t-gsheet,.rr-al-ico.t-gsheet{color:#188038}
.rr-drive-fico.t-gslide,.rr-drive-tile-ico.t-gslide,.rr-drive-newico.t-gslide,.rr-al-ico.t-gslide{color:#e37400}

/* Google Workspace status strip */
.rr-drive-gbanner{display:flex;align-items:center;gap:13px;padding:12px 14px;margin-bottom:14px;border:1px solid var(--accent);border-radius:var(--r-lg);background:var(--accent-soft)}
.rr-drive-gbanner[hidden]{display:none}
.rr-drive-gbanner-ico{flex:0 0 auto;width:30px;height:30px;display:flex;align-items:center;justify-content:center;color:var(--accent)}
.rr-drive-gbanner-ico svg{width:22px;height:22px}
.rr-drive-gbanner-txt{flex:1;min-width:0}
.rr-drive-gbanner-title{font-size:var(--fs-sm);font-weight:700;color:var(--text)}
.rr-drive-gbanner-body{font-size:var(--fs-xs);color:var(--text-muted);margin-top:2px;line-height:1.5}
.rr-drive-gbanner-body code{font-family:var(--font-mono,ui-monospace,monospace);font-size:11px;background:var(--surface);border:1px solid var(--border);border-radius:4px;padding:0 4px}
.rr-drive-gbanner-acts{display:flex;align-items:center;gap:6px;flex:0 0 auto}
.rr-drive-gbanner-x{display:inline-flex;align-items:center;justify-content:center;width:28px;height:28px;border:0;background:none;border-radius:var(--r-sm);color:var(--text-subtle);cursor:pointer}
.rr-drive-gbanner-x:hover{background:var(--surface)}
.rr-drive-gbanner-x svg{width:16px;height:16px}

/* New ▾ menu */
.rr-drive-newwrap{position:relative}
#rr-drive-new{display:inline-flex;align-items:center;gap:7px}
.rr-drive-new-caret{width:13px;height:13px;margin-left:-2px}
.rr-drive-newmenu{position:absolute;top:calc(100% + 6px);right:0;z-index:60;min-width:212px;background:var(--surface);border:1px solid var(--border);border-radius:var(--r-lg);box-shadow:var(--shadow-md,0 8px 24px rgba(15,23,42,.12));padding:6px;display:flex;flex-direction:column;gap:1px}
.rr-drive-newmenu[hidden]{display:none}
.rr-drive-newitem{display:flex;align-items:center;gap:11px;padding:8px 10px;border:0;background:none;cursor:pointer;border-radius:var(--r-sm);font-size:var(--fs-sm);font-weight:500;color:var(--text);text-align:left;width:100%}
.rr-drive-newitem:hover{background:var(--canvas)}
.rr-drive-newico{flex:0 0 auto;display:inline-flex;align-items:center;justify-content:center;width:20px;height:20px;color:var(--text-muted)}
.rr-drive-newico svg{width:18px;height:18px}
.rr-drive-newmenu-sep{height:1px;background:var(--border);margin:5px 6px}
.rr-drive-popmenu .rr-drive-newitem{font-weight:500}
.rr-drive-newcheck{display:inline-flex;width:14px;justify-content:center;color:var(--accent);font-weight:700}
.rr-drive-popmenu .rr-drive-newitem.is-active{color:var(--text)}

/* ════════════════════════════════════════════════════════════════════════
   Vault v2 — enterprise 3-column DMS (left nav · content · preview panel).
   Reduced borders, generous whitespace, RouteReady blue only for primary
   actions + active nav. Scoped to .rr-drive-v2 so it overrides the base.
   ════════════════════════════════════════════════════════════════════════ */
.rr-drive-v2{padding:0 14px 14px;height:100%;min-height:0}
.rr-drive-v2 .rr-drive-shell{display:grid;grid-template-columns:220px minmax(0,1fr) 340px;gap:0;height:calc(100vh - 96px);min-height:520px;background:var(--surface);border:1px solid var(--border);border-radius:var(--r-xl,14px);overflow:hidden}
@media (max-width:1180px){.rr-drive-v2 .rr-drive-shell{grid-template-columns:210px minmax(0,1fr)}.rr-drive-v2 .rr-drive-details{display:none}}
@media (max-width:820px){.rr-drive-v2 .rr-drive-shell{grid-template-columns:1fr;height:auto}.rr-drive-v2 .rr-drive-nav{display:none}}

/* Left navigation */
.rr-drive-nav{display:flex;flex-direction:column;min-height:0;padding:14px 12px;background:var(--canvas);border-right:1px solid var(--border-subtle)}
.rr-drive-nav-top{display:flex;align-items:center;gap:8px;margin-bottom:16px}
.rr-drive-newbtn{flex:0 0 auto;gap:7px;padding:8px 12px;font-size:var(--fs-sm)}
.rr-drive-navlist{display:flex;flex-direction:column;gap:1px;overflow-y:auto;min-height:0;flex:1}
.rr-drive-navitem{display:flex;align-items:center;gap:11px;width:100%;padding:8px 10px;border:0;background:none;border-radius:8px;cursor:pointer;font-size:var(--fs-sm);font-weight:500;color:var(--text-muted);text-align:left;line-height:1.2}
.rr-drive-navitem:hover{background:var(--surface)}
.rr-drive-navitem.is-active{background:var(--accent-soft);color:var(--accent);font-weight:600}
.rr-drive-navico{flex:0 0 auto;width:18px;height:18px;display:inline-flex;align-items:center;justify-content:center;color:currentColor}
.rr-drive-navico svg{width:18px;height:18px}
.rr-drive-navlbl{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.rr-drive-navcnt{font-size:var(--fs-xs);color:var(--text-subtle);font-weight:500}
.rr-drive-navitem.is-active .rr-drive-navcnt{color:var(--accent)}
.rr-drive-navitem.is-alert .rr-drive-navcnt{background:#fee2e2;color:#b42318;border-radius:999px;padding:1px 7px}
.rr-drive-navsep{height:1px;background:var(--border-subtle);margin:9px 8px}
/* "Folders" group label + folder rows in the left rail. */
.rr-drive-navhead{font-size:var(--fs-xs);font-weight:700;letter-spacing:.04em;text-transform:uppercase;color:var(--text-subtle);padding:2px 10px 4px}
/* Folder tree row · [subtle chevron | folder button]. The chevron toggles the
   sub-folders (collapsed by default); the spacer keeps icons aligned. */
.rr-drive-navrow{display:flex;align-items:center;gap:1px}
.rr-drive-navrow .rr-drive-navfolderbtn{flex:1;min-width:0;padding-left:4px}
.rr-drive-navrow .rr-drive-navico{color:var(--text-muted)}
.rr-drive-navrow.is-active .rr-drive-navico{color:var(--accent)}
.rr-drive-navchev{flex:0 0 auto;width:16px;height:28px;display:inline-flex;align-items:center;justify-content:center;border:0;background:none;padding:0;cursor:pointer;color:var(--text-subtle);opacity:.45;border-radius:4px}
.rr-drive-navchev svg{width:13px;height:13px;transition:transform .15s ease}
.rr-drive-navchev.is-open svg{transform:rotate(90deg)}
.rr-drive-navchev:hover{opacity:.9;background:var(--surface)}
.rr-drive-navchev.is-empty{cursor:default;pointer-events:none}
/* Folder rearrange / nest drag (rail). Grab cursor on draggable folder rows;
   drop indicators — a tinted outlined box = nest inside, a top/bottom rule =
   reorder before/after that folder. */
.rr-drive-navfolderbtn[draggable="true"]{cursor:grab}
.rr-drive-navfolderbtn[draggable="true"]:active{cursor:grabbing}
.rr-drive-navrow .rr-drive-navfolderbtn.rr-drive-dragging{opacity:.45}
.rr-drive-navrow.is-drop-into{background:var(--accent-soft);border-radius:8px;box-shadow:inset 0 0 0 1.5px var(--accent)}
.rr-drive-navrow.is-drop-before{box-shadow:inset 0 2px 0 var(--accent)}
.rr-drive-navrow.is-drop-after{box-shadow:inset 0 -2px 0 var(--accent)}
.rr-drive-nav-foot{margin-top:auto;padding-top:8px;border-top:1px solid var(--border-subtle)}
.rr-drive-storage-t{font-size:10px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;color:var(--text-subtle);padding:8px 10px 0}
.rr-drive-storage-v{font-size:var(--fs-xs);color:var(--text-muted);padding:3px 10px 8px}
.rr-drive-navfootbtn{color:var(--text-subtle)}

/* Center column */
.rr-drive-v2 .rr-drive-center{border:0;border-radius:0;background:var(--surface)}
.rr-drive-v2 .rr-drive-toolbar{border-bottom:1px solid var(--border-subtle);padding:14px 24px;gap:14px}
.rr-drive-v2 .rr-drive-search{flex:1;max-width:560px;background:var(--canvas);border:1px solid var(--border-subtle);border-radius:10px;height:42px;padding:0 14px}
.rr-drive-v2 .rr-drive-search:focus-within{border-color:var(--accent);background:var(--surface)}
.rr-drive-v2 .rr-drive-search input{font-size:var(--fs-sm)}
.rr-drive-tb-actions{display:flex;align-items:center;gap:8px;flex:0 0 auto;margin-left:auto}
.rr-drive-tbtn{display:inline-flex;align-items:center;gap:7px;padding:8px 13px;border:1px solid var(--border-subtle);background:var(--surface);border-radius:9px;cursor:pointer;font-size:var(--fs-sm);font-weight:500;color:var(--text-muted)}
.rr-drive-tbtn:hover{background:var(--canvas);color:var(--text)}
.rr-drive-tbtn.is-active{border-color:var(--accent);color:var(--accent)}
.rr-drive-tbtn svg{width:16px;height:16px}
.rr-drive-v2 .rr-drive-crumbs{padding:12px 24px 0}
.rr-drive-v2 .rr-drive-main{padding:6px 24px 26px}
.rr-drive-v2 .rr-drive-sectionhead{font-size:var(--fs-xs);font-weight:700;letter-spacing:.04em;text-transform:uppercase;color:var(--text-subtle);margin:16px 2px 10px}
.rr-drive-v2 .rr-drive-sectionhead-gap{margin-top:28px}

/* Quick access — small, low-chrome folder cards */
.rr-drive-quick{display:grid;grid-template-columns:repeat(auto-fill,minmax(188px,1fr));gap:10px}
.rr-drive-v2 .rr-drive-quick .rr-drive-card{padding:12px;border-color:var(--border-subtle);border-radius:10px}
.rr-drive-v2 .rr-drive-quick .rr-drive-card:hover{border-color:var(--accent);background:var(--canvas);box-shadow:none}
.rr-drive-v2 .rr-drive-quick .rr-drive-card-ico{width:42px;height:42px}

/* Folders table */
.rr-drive-ftable{display:flex;flex-direction:column}
.rr-drive-fhead,.rr-drive-frow{display:grid;grid-template-columns:minmax(0,1fr) 96px 132px 44px;align-items:center;gap:14px;padding:0 10px}
.rr-drive-fhead-acts{text-align:right}
.rr-drive-fhead{height:34px;font-size:10px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;color:var(--text-subtle);border-bottom:1px solid var(--border-subtle)}
.rr-drive-frow{height:52px;border-radius:8px;cursor:pointer}
.rr-drive-frow:hover{background:var(--canvas)}
.rr-drive-frow.rr-drive-dropover{background:var(--accent-soft);box-shadow:inset 0 0 0 1.5px var(--accent)}
/* Per-row folder actions — a single 3-dot menu button (Google-Drive style). */
.rr-drive-frow-acts{display:flex;align-items:center;justify-content:flex-end;min-width:0}
.rr-drive-kebab{display:inline-flex;align-items:center;justify-content:center;width:30px;height:30px;padding:0;border:0;background:transparent;border-radius:7px;color:var(--text-muted);cursor:pointer;opacity:.55;transition:opacity .12s ease,background .12s ease,color .12s ease}
.rr-drive-kebab svg{width:18px;height:18px}
.rr-drive-frow:hover .rr-drive-kebab{opacity:1}
.rr-drive-kebab:hover{background:var(--surface-hover);color:var(--text)}
/* Destructive menu item (Delete / Hide). */
.rr-drive-newitem-danger,.rr-drive-newitem-danger .rr-drive-newico{color:#dc2626}
.rr-drive-newitem-danger:hover{background:var(--red-soft,#fef2f2)}
/* "Show hidden folders" restore control under the folders table. */
.rr-drive-showhidden{display:inline-flex;align-items:center;gap:6px;margin:8px 2px 0;padding:6px 9px;border:0;background:none;color:var(--text-muted);font-size:12px;font-weight:600;cursor:pointer;border-radius:6px}
.rr-drive-showhidden:hover{background:var(--surface-hover);color:var(--text)}
.rr-drive-fname{display:flex;align-items:center;gap:12px;min-width:0;font-size:var(--fs-sm);font-weight:600;color:var(--text)}
.rr-drive-fname .rr-drive-fico{flex:0 0 auto}
.rr-drive-fname .rr-drive-name-txt{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.rr-drive-fcell{font-size:var(--fs-sm)}
.rr-drive-cell-soft{color:var(--text-subtle)}

/* Documents table — 56px rows, 5 columns, hairline separators only */
.rr-drive-v2 .rr-drive-list{border:0}
.rr-drive-v2 .rr-drive-lhead,.rr-drive-v2 .rr-drive-row{grid-template-columns:minmax(0,1fr) 140px 160px 130px 140px;gap:18px;padding:0 14px;border:0}
.rr-drive-v2 .rr-drive-lhead{height:42px;border-bottom:1px solid var(--border-subtle);position:sticky;top:0;background:var(--surface);z-index:1;color:var(--text-muted)}
.rr-drive-v2 .rr-drive-row{position:relative;height:64px;border-radius:10px;border-bottom:1px solid transparent}
.rr-drive-v2 .rr-drive-row:hover{background:var(--canvas)}
.rr-drive-v2 .rr-drive-row.is-selected,.rr-drive-v2 .rr-drive-row.is-checked{background:var(--accent-soft)}
.rr-drive-v2 .rr-drive-name-txt{font-weight:500}
.rr-drive-v2 .rr-drive-fico{width:40px;height:40px}

/* Right preview / details panel */
.rr-drive-v2 .rr-drive-details{border:0;border-left:1px solid var(--border-subtle);border-radius:0;background:var(--surface)}

/* ── Grid view ───────────────────────────────────────────────────────── */
.rr-drive-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:12px}
.rr-drive-tile{display:flex;flex-direction:column;gap:10px;padding:14px;border:1px solid var(--border);border-radius:var(--r-lg);background:var(--surface);cursor:pointer;transition:border-color var(--t-fast),box-shadow var(--t-fast)}
.rr-drive-tile:hover{border-color:var(--accent);box-shadow:var(--shadow-sm)}
.rr-drive-tile.is-selected{border-color:var(--accent);box-shadow:var(--shadow-sm)}
.rr-drive-tile-ico{width:47px;height:47px;border-radius:11px;background:var(--canvas);display:flex;align-items:center;justify-content:center;color:var(--text-subtle)}
.rr-drive-tile-ico svg{width:24px;height:24px}
.rr-drive-tile-name{font-size:var(--fs-sm);font-weight:600;color:var(--text);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.rr-drive-tile-meta{font-size:var(--fs-xs);color:var(--text-subtle)}

/* ── Empty state ─────────────────────────────────────────────────────── */
.rr-drive-empty{display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;gap:10px;padding:64px 24px;color:var(--text-subtle)}
.rr-drive-empty svg{width:42px;height:42px;opacity:.4}
.rr-drive-empty-title{font-size:var(--fs-md);font-weight:600;color:var(--text-muted)}
.rr-drive-empty-sub{font-size:var(--fs-sm);max-width:320px;line-height:1.5}

/* ── Details / preview pane ──────────────────────────────────────────── */
.rr-drive-details{background:var(--surface);border:1px solid var(--border);border-radius:var(--r-lg);overflow-y:auto;min-height:0;display:flex;flex-direction:column}
.rr-drive-det-empty{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:9px;text-align:center;padding:28px 22px;color:var(--text-subtle)}
.rr-drive-det-empty svg{width:30px;height:30px;opacity:.4}
.rr-drive-det-empty span{font-size:var(--fs-xs);max-width:200px;line-height:1.5}
.rr-drive-det-head{padding:16px 16px 12px;border-bottom:1px solid var(--border)}
.rr-drive-det-name{font-size:var(--fs-md);font-weight:700;color:var(--text);line-height:1.35;word-break:break-word}
.rr-drive-det-type{font-size:var(--fs-xs);color:var(--text-subtle);margin-top:3px}
.rr-drive-det-preview{margin:14px 16px;border:1px solid var(--border);border-radius:var(--r-md);overflow:hidden;background:var(--canvas);min-height:150px;display:flex;align-items:center;justify-content:center}
.rr-drive-det-preview iframe{width:100%;height:280px;border:0;background:#fff}
/* Client-side Word / Excel render (mammoth / SheetJS → HTML). */
.rr-drive-doc-html{width:100%;max-height:320px;overflow:auto;background:#fff;padding:14px 16px;font-size:var(--fs-sm);line-height:1.55;color:var(--text);text-align:left}
.rr-drive-doc-html.rr-drive-xls{padding:0}
.rr-drive-doc-html img{max-width:100%}
.rr-drive-doc-html h1,.rr-drive-doc-html h2,.rr-drive-doc-html h3{font-size:var(--fs-md);margin:.6em 0 .3em}
.rr-drive-doc-html p{margin:0 0 .5em}
.rr-drive-doc-html table{border-collapse:collapse;font-size:var(--fs-xs);width:100%}
.rr-drive-doc-html td,.rr-drive-doc-html th{border:1px solid var(--border-subtle);padding:4px 8px;white-space:nowrap}
.rr-drive-det-preview img{max-width:100%;max-height:280px;display:block}
.rr-drive-det-noprev{padding:34px 16px;text-align:center;color:var(--text-subtle);font-size:var(--fs-xs);line-height:1.5}
.rr-drive-det-noprev svg{width:30px;height:30px;opacity:.4;margin-bottom:8px}
.rr-drive-det-meta{padding:6px 16px 14px}
.rr-drive-det-row{display:grid;grid-template-columns:96px 1fr;gap:8px;padding:7px 0;border-top:1px solid var(--border-subtle);font-size:var(--fs-sm)}
.rr-drive-det-row:first-child{border-top:0}
.rr-drive-det-row .k{font-size:var(--fs-xs);font-weight:600;letter-spacing:.02em;text-transform:uppercase;color:var(--text-subtle);padding-top:1px}
.rr-drive-det-row .v{color:var(--text);word-break:break-word}
.rr-drive-det-tags{display:flex;flex-wrap:wrap;gap:5px}
.rr-drive-det-tag{font-size:10px;font-weight:600;color:var(--text-muted);background:var(--canvas);border:1px solid var(--border);border-radius:var(--r-pill);padding:1px 8px}
.rr-drive-det-foot{margin-top:auto;padding:13px 16px;border-top:1px solid var(--border);display:flex;gap:8px;flex-wrap:wrap}

/* Tag chip on a row (suggested driver match etc.). */
.rr-drive-chip{display:inline-flex;align-items:center;gap:4px;font-size:10px;font-weight:600;color:var(--text-muted);background:var(--canvas);border:1px solid var(--border);border-radius:var(--r-pill);padding:1px 7px}

/* ════════════════════════════════════════════════════════════════════════
   Vault v2 · enterprise refinement pass — premium cards, calmer typography,
   a useful empty preview, a real storage card, subtler folder selection, and
   an 8px rhythm. Pure polish: no layout or proportion changes. All motion is
   gentle (≈160ms) and collapses under prefers-reduced-motion (block above).
   ════════════════════════════════════════════════════════════════════════ */

/* Typography hierarchy — the filename anchors each row; metadata stays quiet
   (but never too light). Background fades smoothly on hover / selection. */
.rr-drive-v2 .rr-drive-name-txt{font-weight:600;color:var(--text)}
.rr-drive-v2 .rr-drive-cell{color:var(--text-muted)}
.rr-drive-v2 .rr-drive-cell.rr-drive-cell-soft{color:var(--text-subtle)}
.rr-drive-v2 .rr-drive-row{transition:background-color .16s ease}

/* Document tiles (grid) — comfortable padding, a slightly larger icon, two
   quiet metadata lines + an owner chip, and a 2px hover lift. */
.rr-drive-v2 .rr-drive-grid{gap:14px}
.rr-drive-v2 .rr-drive-tile{gap:12px;padding:18px 16px;border-color:var(--border-subtle);border-radius:12px;transition:border-color .16s ease,box-shadow .16s ease,transform .16s ease}
.rr-drive-v2 .rr-drive-tile:hover{border-color:var(--border);box-shadow:var(--shadow-sm-hover);transform:translateY(-2px)}
.rr-drive-v2 .rr-drive-tile.is-selected,.rr-drive-v2 .rr-drive-tile.is-checked{border-color:var(--accent);box-shadow:var(--shadow-sm);transform:none}
.rr-drive-v2 .rr-drive-tile-ico{width:52px;height:52px;border-radius:13px}
.rr-drive-v2 .rr-drive-tile-ico svg{width:26px;height:26px}
.rr-drive-v2 .rr-drive-tile-name{font-weight:600}
.rr-drive-v2 .rr-drive-tile-meta{color:var(--text-muted)}
.rr-drive-tile-sub{display:flex;align-items:center;justify-content:center;gap:7px;margin-top:-4px;font-size:var(--fs-xs);color:var(--text-subtle)}
.rr-drive-tile-edited{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.rr-drive-ava{flex:0 0 auto;width:20px;height:20px;border-radius:50%;background:var(--canvas);border:1px solid var(--border-subtle);color:var(--text-muted);font-size:9px;font-weight:700;letter-spacing:.02em;display:inline-flex;align-items:center;justify-content:center}

/* Folder / section nav — calmer hover, an obvious-but-soft selected state with
   a subtle left indicator. Hover and chevron transitions settle at ~160ms. */
.rr-drive-v2 .rr-drive-navitem{position:relative;transition:background-color .16s ease,color .16s ease}
.rr-drive-v2 .rr-drive-navitem.is-active::before{content:"";position:absolute;left:1px;top:50%;transform:translateY(-50%);width:3px;height:16px;border-radius:3px;background:var(--accent)}
.rr-drive-v2 .rr-drive-navchev{transition:opacity .16s ease,background-color .16s ease}

/* Toolbar controls — unhurried 160ms transitions for a settled, premium feel. */
.rr-drive-v2 .rr-drive-tbtn{transition:background-color .16s ease,border-color .16s ease,color .16s ease}
.rr-drive-v2 .rr-drive-vbtn{transition:background-color .16s ease,color .16s ease,box-shadow .16s ease}

/* Storage card — thin progress bar + quiet caption. Shared by the rail foot and
   the empty preview so they read identically. Track reads on white and canvas. */
.rr-drive-storecard{padding:0}
.rr-drive-store-bar{height:6px;border-radius:999px;background:var(--border);overflow:hidden}
.rr-drive-store-bar span{display:block;height:100%;border-radius:999px;background:var(--accent);transition:width .3s ease}
.rr-drive-store-line{display:flex;align-items:baseline;justify-content:space-between;gap:8px;margin-top:8px;font-size:var(--fs-xs);color:var(--text-subtle)}
.rr-drive-store-count{flex:0 0 auto;font-variant-numeric:tabular-nums}
.rr-drive-v2 .rr-drive-nav-foot .rr-drive-storage{padding:4px 10px 6px}
.rr-drive-v2 .rr-drive-nav-foot .rr-drive-storage-t{padding:0 0 8px}

/* Empty preview workspace — Preview · Recent activity · Storage · Details. */
.rr-drive-det-empty2{display:flex;flex-direction:column;gap:24px;padding:20px 16px}
.rr-drive-det-sec{display:flex;flex-direction:column;gap:10px}
.rr-drive-det-sechead{font-size:10px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;color:var(--text-subtle)}
.rr-drive-det-noselect{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;padding:30px 16px;border:1px solid var(--border-subtle);border-radius:12px;background:var(--canvas);color:var(--text-subtle)}
.rr-drive-det-noselect svg{width:30px;height:30px;opacity:.4}
.rr-drive-det-noselect span{font-size:var(--fs-sm);font-weight:500;color:var(--text-muted)}
.rr-drive-det-quiet{font-size:var(--fs-sm);color:var(--text-subtle);line-height:1.5}
.rr-drive-recents{display:flex;flex-direction:column;gap:2px}
.rr-drive-recent{display:flex;align-items:center;gap:10px;width:100%;padding:8px;border:0;background:none;border-radius:8px;cursor:pointer;text-align:left;transition:background-color .16s ease}
.rr-drive-recent:hover{background:var(--canvas)}
.rr-drive-recent .rr-drive-fico{flex:0 0 auto;width:34px;height:34px}
.rr-drive-recent .rr-drive-fico svg{width:18px;height:18px}
.rr-drive-recent-body{min-width:0;display:flex;flex-direction:column;gap:1px}
.rr-drive-recent-name{font-size:var(--fs-sm);font-weight:600;color:var(--text);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.rr-drive-recent-meta{font-size:var(--fs-xs);color:var(--text-subtle);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}

/* Details content fades in on selection — a calm transition between documents. */
.rr-drive-v2 .rr-drive-details > *{animation:rr-drive-detfade .16s ease}
@keyframes rr-drive-detfade{from{opacity:0}to{opacity:1}}

/* ════════════════════════════════════════════════════════════════════════
   Vault sidebar · match the app's Schedule rail — the soft-blue (#EFF6FF) light
   theme. The global rail redefines the --sidebar-* vars ON the .sidebar element
   (see "Soft-blue sidebar" above), so the Vault's own nav redefines the SAME
   vars here to read identically. Selected item = white pill + blue ink, exactly
   like .sidebar .nav-item.active. Scoped to the nav — content + preview stay light.
   ════════════════════════════════════════════════════════════════════════ */
.rr-drive-v2 .rr-drive-nav{
  --sidebar-bg:#EFF6FF;
  --sidebar-ink:#1E293B;
  --sidebar-ink-idle:#475569;
  --sidebar-icon-idle:#64748B;
  --sidebar-icon-active:#2563EB;
  --sidebar-hover:#E0EAFE;
  --sidebar-divider:rgba(15,23,42,.10);
  background:var(--sidebar-bg);
  border-right:1px solid var(--sidebar-divider);
}
.rr-drive-v2 .rr-drive-nav .rr-drive-navitem{color:var(--sidebar-ink-idle)}
.rr-drive-v2 .rr-drive-nav .rr-drive-navitem:hover{background:var(--sidebar-hover);color:var(--sidebar-ink)}
/* Selected = white pill + blue ink (matches .sidebar .nav-item.active). */
.rr-drive-v2 .rr-drive-nav .rr-drive-navitem.is-active{
  background:#FFFFFF;color:#1E40AF;font-weight:600;
  box-shadow:0 1px 2px rgba(15,23,42,.07), 0 0 0 1px rgba(15,23,42,.05);
}
.rr-drive-v2 .rr-drive-nav .rr-drive-navitem.is-active::before{display:none}
.rr-drive-v2 .rr-drive-nav .rr-drive-navrow.is-active{
  background:#FFFFFF;border-radius:8px;
  box-shadow:0 1px 2px rgba(15,23,42,.07), 0 0 0 1px rgba(15,23,42,.05);
}
.rr-drive-v2 .rr-drive-nav .rr-drive-navrow.is-active .rr-drive-navitem.is-active{background:transparent;box-shadow:none}
/* Counts · group label · separators · folder icons · chevrons. */
.rr-drive-v2 .rr-drive-nav .rr-drive-navcnt{color:var(--sidebar-ink-idle)}
.rr-drive-v2 .rr-drive-nav .rr-drive-navitem.is-active .rr-drive-navcnt{color:#1E40AF}
.rr-drive-v2 .rr-drive-nav .rr-drive-navhead{color:var(--sidebar-ink-idle)}
.rr-drive-v2 .rr-drive-nav .rr-drive-navsep{background:var(--sidebar-divider)}
.rr-drive-v2 .rr-drive-nav .rr-drive-navrow .rr-drive-navico{color:var(--sidebar-icon-idle)}
.rr-drive-v2 .rr-drive-nav .rr-drive-navrow.is-active .rr-drive-navico{color:var(--sidebar-icon-active)}
.rr-drive-v2 .rr-drive-nav .rr-drive-navchev{color:var(--sidebar-ink-idle);opacity:.6}
.rr-drive-v2 .rr-drive-nav .rr-drive-navchev:hover{opacity:1;background:var(--sidebar-hover)}
/* Foot — storage card + Admin Console on the soft-blue rail. */
.rr-drive-v2 .rr-drive-nav .rr-drive-nav-foot{border-top:1px solid var(--sidebar-divider)}
.rr-drive-v2 .rr-drive-nav .rr-drive-storage-t{color:var(--sidebar-ink-idle)}
.rr-drive-v2 .rr-drive-nav .rr-drive-store-bar{background:rgba(15,23,42,.10)}
.rr-drive-v2 .rr-drive-nav .rr-drive-store-line{color:var(--sidebar-ink-idle)}
.rr-drive-v2 .rr-drive-nav .rr-drive-navfootbtn{color:var(--sidebar-ink-idle)}
/* Docked app launcher (3×3) — matches the rail's idle glyph. */
.rr-drive-v2 .rr-drive-nav .rr-launcher-dock:not(:empty){border-left-color:var(--sidebar-divider)}
.rr-drive-v2 .rr-drive-nav .rr-al-btn{color:var(--sidebar-icon-idle)}
.rr-drive-v2 .rr-drive-nav .rr-al-btn:hover{background:var(--sidebar-hover);color:var(--sidebar-ink)}

/* ════════════════════════════════════════════════════════════════════════
   Vault enterprise pass A · folder-header anchor, search, toolbar, table rows,
   storage. Pure refinement on the existing layout — 8px rhythm, calm color,
   soft shadows, no heavy borders.
   ════════════════════════════════════════════════════════════════════════ */

/* Folder toolbar — New folder is the only filled button; Star/Customize are
   subtle outlines; Delete is the lone destructive action, grouped at the right. */
.rr-drive-folderbar-acts{display:flex;align-items:center;gap:8px;flex:0 0 auto}
.rr-drive-folderbar-sep{width:1px;align-self:stretch;margin:5px 4px;background:var(--border-subtle)}
.rr-drive-v2 .rr-drive-folderbar-acts .rr-drive-fbtn{background:var(--surface);border:1px solid var(--border-subtle);color:var(--text-muted);box-shadow:none}
.rr-drive-v2 .rr-drive-folderbar-acts .rr-drive-fbtn:hover{background:var(--canvas);border-color:var(--border);color:var(--text)}
.rr-drive-v2 .rr-drive-folderbar-acts .rr-drive-fbtn.is-active{border-color:#f59e0b;color:#b45309;background:var(--surface)}
.rr-drive-v2 .rr-drive-folderbar-acts .rr-drive-fbtn-danger{color:#b42318}
.rr-drive-v2 .rr-drive-folderbar-acts .rr-drive-fbtn-danger:hover{background:var(--red-soft,#fef2f2);border-color:#fecaca;color:#b42318}

/* Search — wider, with a platform ⌘K / Ctrl+K hint chip on the right. */
.rr-drive-v2 .rr-drive-search{max-width:680px}
.rr-drive-search-kbd{flex:0 0 auto;display:inline-flex;align-items:center;height:22px;padding:0 7px;border:1px solid var(--border-subtle);border-radius:6px;background:var(--surface);color:var(--text-subtle);font-size:11px;font-weight:600;font-family:inherit;letter-spacing:.02em;white-space:nowrap}

/* File table — subtle blue selection ring (rounded) + the hover 3-dot overflow.
   The kebab floats at the row's right edge (absolute) so it adds no column width
   and the table keeps its 5-column proportions at any width. */
.rr-drive-v2 .rr-drive-row.is-selected,.rr-drive-v2 .rr-drive-row.is-checked{box-shadow:inset 0 0 0 1px var(--accent-border,rgba(37,99,235,.22))}
.rr-drive-lhead-act{display:none}
.rr-drive-rowact{position:absolute;right:8px;top:0;bottom:0;display:flex;align-items:center;justify-content:flex-end}
.rr-drive-rowkebab{display:inline-flex;align-items:center;justify-content:center;width:30px;height:30px;padding:0;border:0;background:transparent;border-radius:8px;color:var(--text-subtle);cursor:pointer;opacity:0;transition:opacity .14s ease,background-color .14s ease,color .14s ease}
.rr-drive-rowkebab svg{width:18px;height:18px}
.rr-drive-row:hover .rr-drive-rowkebab,.rr-drive-row.is-selected .rr-drive-rowkebab{opacity:1}
.rr-drive-rowkebab:hover{background:var(--surface-hover);color:var(--text)}

/* Storage card · used / quota, then real File + Folder counts. */
.rr-drive-store-counts{display:flex;align-items:baseline;justify-content:space-between;gap:8px;margin-top:4px;font-size:var(--fs-xs);color:var(--text-subtle);font-variant-numeric:tabular-nums}

/* Sidebar — folder counts de-emphasised (quieter, smaller) per the spec. */
.rr-drive-v2 .rr-drive-nav .rr-drive-navcnt{font-size:11px;opacity:.75}

/* ════════════════════════════════════════════════════════════════════════
   Vault enterprise pass B · the right-panel inspector + RouteReady Intelligence.
   Selected document → large icon, Details/Activity tabs, organized metadata, a
   quick-action footer. A driver open → an operational overview (real figures).
   ════════════════════════════════════════════════════════════════════════ */

/* Document inspector — header · tabs · scrolling body · sticky action footer. */
.rr-drive-insp-head{display:flex;align-items:center;gap:12px;padding:16px 16px 12px;flex:0 0 auto}
.rr-drive-insp-ico{flex:0 0 auto;width:44px;height:44px;border-radius:11px;background:var(--canvas);display:flex;align-items:center;justify-content:center;color:var(--text-subtle)}
.rr-drive-insp-ico svg{width:24px;height:24px}
.rr-drive-insp-id{min-width:0}
.rr-drive-insp-name{font-size:var(--fs-md);font-weight:700;color:var(--text);line-height:1.3;word-break:break-word;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.rr-drive-insp-type{font-size:var(--fs-xs);color:var(--text-subtle);margin-top:2px}
.rr-drive-insp-tabs{display:flex;gap:2px;padding:0 12px;border-bottom:1px solid var(--border-subtle);flex:0 0 auto}
.rr-drive-insp-tab{appearance:none;border:0;background:none;font:inherit;font-size:var(--fs-sm);font-weight:600;color:var(--text-subtle);padding:9px 10px;cursor:pointer;border-bottom:2px solid transparent;margin-bottom:-1px;transition:color .16s ease,border-color .16s ease}
.rr-drive-insp-tab:hover{color:var(--text-muted)}
.rr-drive-insp-tab.is-active{color:var(--accent-text);border-bottom-color:var(--accent)}
.rr-drive-insp-body{flex:1;min-height:0;overflow-y:auto;animation:rr-drive-detfade .16s ease}
.rr-drive-insp-foot{flex:0 0 auto;border-top:1px solid var(--border-subtle);padding:12px}
.rr-drive-insp-qa{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.rr-drive-insp-qa-sec{margin-top:8px}
.rr-drive-qa{display:flex;align-items:center;gap:8px;padding:9px 11px;border:1px solid var(--border-subtle);border-radius:9px;background:var(--surface);color:var(--text-muted);font:inherit;font-size:var(--fs-sm);font-weight:500;cursor:pointer;text-align:left;transition:background-color .16s ease,border-color .16s ease,color .16s ease}
.rr-drive-qa svg{width:17px;height:17px;flex:0 0 auto}
.rr-drive-qa span{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.rr-drive-qa:hover{background:var(--canvas);border-color:var(--border);color:var(--text)}
.rr-drive-qa.is-on{border-color:var(--accent-border,rgba(37,99,235,.3));color:var(--accent-text);background:var(--accent-soft)}
.rr-drive-qa-sm{padding:7px 10px;font-size:var(--fs-xs)}
.rr-drive-qa-danger{color:#b42318}
.rr-drive-qa-danger:hover{background:var(--red-soft,#fef2f2);border-color:#fecaca;color:#b42318}

/* Activity tab — a quiet timeline built from the record's real timestamps. */
.rr-drive-act{list-style:none;margin:0;padding:16px}
.rr-drive-act-item{position:relative;display:flex;gap:12px;padding:0 0 16px 4px}
.rr-drive-act-item:last-child{padding-bottom:0}
.rr-drive-act-dot{flex:0 0 auto;width:9px;height:9px;margin-top:4px;border-radius:50%;background:var(--accent);box-shadow:0 0 0 3px var(--accent-soft)}
.rr-drive-act-item:not(:last-child)::before{content:"";position:absolute;left:8px;top:15px;bottom:0;width:1px;background:var(--border-subtle)}
.rr-drive-act-body{min-width:0}
.rr-drive-act-t{font-size:var(--fs-sm);font-weight:500;color:var(--text)}
.rr-drive-act-d{font-size:var(--fs-xs);color:var(--text-subtle);margin-top:1px}

/* RouteReady Intelligence — driver overview inspector (real operational data). */
.rr-drive-intel{display:flex;flex-direction:column;gap:14px;padding:18px 16px;overflow-y:auto}
.rr-drive-intel-head{display:flex;align-items:center;gap:12px}
.rr-drive-intel-ava{flex:0 0 auto;width:44px;height:44px;border-radius:50%;background:var(--accent-soft);color:var(--accent-text);font-size:var(--fs-md);font-weight:700;display:flex;align-items:center;justify-content:center}
.rr-drive-intel-id{min-width:0}
.rr-drive-intel-name{font-size:var(--fs-lg);font-weight:700;color:var(--text);line-height:1.2;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.rr-drive-intel-sub{font-size:10px;color:var(--text-subtle);margin-top:3px;text-transform:uppercase;letter-spacing:.05em;font-weight:700}
.rr-drive-intel-comp{display:flex;align-items:center;gap:9px;padding:11px 13px;border-radius:10px;font-size:var(--fs-sm);font-weight:600}
.rr-drive-intel-comp-dot{flex:0 0 auto;width:8px;height:8px;border-radius:50%;background:currentColor}
.rr-drive-intel-comp.is-ok{background:rgba(16,185,129,.10);color:#047857}
.rr-drive-intel-comp.is-amber{background:#fef3c7;color:#b45309}
.rr-drive-intel-comp.is-red{background:#fee2e2;color:#b42318}
.rr-drive-intel-stats{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.rr-drive-intel-stat{padding:11px 13px;border:1px solid var(--border-subtle);border-radius:10px;background:var(--surface)}
.rr-drive-intel-k{font-size:10px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;color:var(--text-subtle)}
.rr-drive-intel-v{font-size:var(--fs-md);font-weight:700;color:var(--text);margin-top:3px}
.rr-drive-intel-qa{display:flex;flex-direction:column;gap:8px}
.rr-drive-intel-qa .rr-drive-qa{width:100%}

/* ════════════════════════════════════════════════════════════════════════
   Schedule sub-view toolbars · match the action-bar button SIZE (operator
   2026-06-27). The Schedule View / Today bar uses .rr-ab-btn — 36px tall,
   1.5px navy (--sidebar-bg) outline, 8px radius, 13px side padding, 15px icons.
   Requests (.req-toolbar-*), Roster (.sched-kpi-action) and Targets (.rr-tgt-kpi)
   already render the SAME outlined split-button shape but at the wrong size
   (Requests 38px / 1px border, Roster 38px, Targets 32px). Pull all three to the
   .rr-ab-btn box so every Schedule screen's buttons are the same size. Scoped to
   #view-schedule, so the standalone Drivers / Onboarding roster strips are
   untouched. Appended last so it wins the cascade over the per-toolbar rules
   above. Verified with an offline Chromium render measuring each button at 36px
   against the real .rr-ab-btn. */

/* ---- Requests ---- */
#view-schedule.rrx-schedule .req-toolbar-bar select.req-toolbar-filter,
#view-schedule.rrx-schedule .req-toolbar-bar .req-toolbar-act {
  height: 36px !important;
  border-width: 1.5px !important;
  border-color: var(--sidebar-bg, #0F172A) !important;
  border-radius: 8px !important;
  font-size: 14px !important;
}
#view-schedule.rrx-schedule .req-toolbar-bar .req-toolbar-act { padding: 0 13px !important; }
#view-schedule.rrx-schedule .req-toolbar-bar .req-toolbar-act svg { width: 15px !important; height: 15px !important; }
#view-schedule.rrx-schedule .req-toolbar-bar .req-toolbar-primary { border-color: var(--accent) !important; }

/* ---- Roster ---- */
#view-schedule.rrx-schedule #rr-sched-kpis .sched-kpi-action {
  height: 36px !important;
  padding: 0 13px !important;
  border: 1.5px solid var(--sidebar-bg, #0F172A) !important;
  border-radius: 8px !important;
  background: #FFFFFF !important;
  gap: 7px !important;
}
#view-schedule.rrx-schedule #rr-sched-kpis .sched-kpi-action svg { width: 15px !important; height: 15px !important; }
#view-schedule.rrx-schedule #rr-sched-kpis .sched-kpi-action .sched-kpi-val { font-size: 14px !important; }
/* fixed 36px height ⇒ drop the padding-cancel negatives so the divider doesn't overshoot */
#view-schedule.rrx-schedule #rr-sched-kpis .sched-kpi-action .rr-kpi-chev {
  margin-top: 0 !important; margin-bottom: 0 !important;
  padding-left: 10px !important;
}

/* ---- Targets ---- */
#view-schedule.rrx-schedule #rr-sched-targets-kpis .rr-tgt-kpi {
  height: 36px !important;
}
#view-schedule.rrx-schedule #rr-sched-targets-kpis .rr-tgt-kpi-label { font-size: 14px !important; }

/* ════════════════════════════════════════════════════════════════════
   PREMIUM V2 POLISH PASS · Schedule (2026-06-28)
   ─────────────────────────────────────────────────────────────────────
   A visual refinement only — layout, information architecture, workflow,
   navigation structure and the colour palette are all unchanged. Every
   value is drawn from the existing token system (--shadow-*, --s-*, --r-*,
   --rr-*) so depth, spacing and radii stay consistent with the rest of the
   app. The goal is a calm, understated, Fortune-500 / Fluent · Linear feel:
   soft elevation, generous whitespace, restrained motion. Appended to the
   last-loaded sheet so the whole pass lives in one reviewable, revertible
   block instead of scattered edits.
   ════════════════════════════════════════════════════════════════════ */

/* ── Action bar · cleaner control rhythm + breathing room above the grid */
#view-schedule .rr-ab { gap: 12px; margin: 0 0 16px; }

/* ── Toolbar buttons · float on a soft shadow, premium hover + press ──── */
#view-schedule.rrx-schedule .rr-ab-btn {
  box-shadow: var(--shadow-xs);
  transition: background-color .16s ease, border-color .16s ease,
              box-shadow .16s ease, transform .12s ease;
}
#view-schedule.rrx-schedule .rr-ab-btn:not(.rr-ab-primary):hover {
  background: #FCFDFE;
  border-color: rgba(15, 23, 42, .16);
  box-shadow: var(--shadow-sm);
}
/* Gentle compress on press — the same restrained micro-interaction the
   utility rail uses, so clicks feel tactile without bouncing. */
#view-schedule.rrx-schedule .rr-ab-btn:active { transform: scale(.97); box-shadow: var(--shadow-xs); }
#view-schedule.rrx-schedule .rr-ab-primary { box-shadow: var(--shadow-sm); }
#view-schedule.rrx-schedule .rr-ab-primary:active { transform: scale(.97); }

/* ── Coverage · a compact floating status card ───────────────────────── */
#view-schedule.rrx-schedule .rr-ab-coverage {
  gap: 2px;
  padding: 9px 14px;
  background: #FFFFFF;
  border: 1px solid var(--rr-border-primary, #E5E7EB);
  border-radius: 14px;
  box-shadow: var(--shadow-md);
  line-height: 1.2;
}
#view-schedule.rrx-schedule .rr-ab-coverage-main { display: flex; align-items: baseline; gap: 6px; }
#view-schedule.rrx-schedule .rr-ab-cov-num {
  font-size: 18px; font-weight: 700; letter-spacing: -.01em;
  color: var(--rr-fg-primary, #111827); font-variant-numeric: tabular-nums;
}
#view-schedule.rrx-schedule .rr-ab-cov-unit {
  font-size: 11px; font-weight: 600; text-transform: uppercase; letter-spacing: .05em;
  color: var(--rr-fg-secondary, #6B7280);
}
#view-schedule.rrx-schedule .rr-ab-coverage-sub { font-size: 11.5px; margin-top: 1px; }

/* ── Schedule cards (shift chips) · defined tile + soft hover lift ────── */
#view-schedule.rrx-schedule .shift-chip {
  border-radius: 10px !important;
  transition: transform 180ms cubic-bezier(.2, 0, .2, 1),
              box-shadow 180ms cubic-bezier(.2, 0, .2, 1),
              border-color 180ms ease, background-color 180ms ease !important;
}
#view-schedule.rrx-schedule .shift-chip:not(.swap):not(.timeoff):not(.off):not(.open):not(.add-here) {
  box-shadow: var(--shadow-xs) !important;
  padding: 6px 8px !important;
  /* A subtle hairline rendered as an inset outline so it coexists with the
     chip's own borderless fill modes (white / blue / route-colour) instead
     of fighting their !important border rules. The hover lift + richer
     shadow are owned by the existing `.cal-cell:hover …:hover` rule (its
     shadow is upgraded to --shadow-md-hover), so the operator's
     chip-hover-only lift behaviour is preserved. */
  outline: 1px solid rgba(15, 23, 42, .06);
  outline-offset: -1px;
}

/* ── Today's column · a very soft blue wash (blue top indicator kept) ── */
#view-schedule .cal-cell.today,
#view-schedule .cal-cell-head.today { --sch-blue-tint: #F7FAFF; }
#view-schedule .cal-cell.today { background: #F7FAFF; }

/* ── Driver list · calmer name weight + a touch more breathing room ──── */
#view-schedule .cal-row-label { padding-top: 14px; padding-bottom: 14px; }
#view-schedule .cal-row-label-name { font-weight: 600; }
#view-schedule .cal-row-label .avatar-sm { flex: 0 0 auto; }

/* ── Left navigation (global chrome) · stronger selected emphasis ─────
   The rail is the light theme (#EFF6FF) where the active item is a white
   pill with blue ink. Lift that pill a touch more so the current page reads
   clearly, and let the idle icons sit a step lighter so selection stands out
   by contrast — no structural or icon-set change. */
.sidebar .nav-item.active { box-shadow: var(--shadow-sm), 0 0 0 1px rgba(15, 23, 42, .05); }
.sidebar { --sidebar-icon-idle: #94A3B8; }

/* ── Topbar (global chrome) · bell sits a little closer to the avatar ── */
.topbar .hdr-avatar-btn { margin-left: -6px; }
/* ─────────────────────────────────────────────────────────────────── */

/* ── Roster search · "Matches" / "Other drivers" section headers ──────
   Search now PROMOTES matches to the top instead of filtering the rest
   away, so the roster stays full (no big empty space below one result).
   These inline header rows label the two groups; they're inert (no
   driver id) and must not read as clickable data rows. */
.tp-roster-table tbody tr.rr-roster-group { cursor: default; }
.tp-roster-table tbody tr.rr-roster-group:hover { background: transparent; box-shadow: none; }
.tp-roster-table tbody tr.rr-roster-group > td { padding: 15px 16px 7px; border: 0; background: transparent; }
.tp-roster-table tbody tr.rr-roster-group:first-child > td { padding-top: 11px; }
.rr-roster-group-label {
  font-size: 11px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase;
  color: var(--text-muted, #64748b);
}
.rr-roster-group-count {
  display: inline-flex; align-items: center; justify-content: center;
  margin-left: 8px; min-width: 18px; height: 17px; padding: 0 6px;
  border-radius: 9px; background: rgba(15, 23, 42, .06);
  font-size: 10.5px; font-weight: 700; color: var(--text-muted, #64748b); vertical-align: middle;
}
.tp-roster-table tbody tr.rr-roster-group--none > td {
  font-size: 12.5px; font-weight: 500; color: var(--text-subtle, #94a3b8);
  text-transform: none; letter-spacing: 0;
}
/* ─────────────────────────────────────────────────────────────────── */

/* ════════════════════════════════════════════════════════════════════
   ADP SYNC BOX · launcher → "ADP Sync" (#modal-adp-sync). A focused
   connect/sync dialog on the shared .modal-* chrome. ADP-red logo tile,
   a "what syncs" checklist, an OAuth security note, and a green
   "connection healthy" banner once connected (mock state).
   ════════════════════════════════════════════════════════════════════ */
.rr-adp .modal-head{ align-items:center; }
.rr-adp-head{ display:flex; align-items:center; gap:12px; min-width:0; }
.rr-adp-logo{
  flex:0 0 auto; width:44px; height:44px; border-radius:11px;
  display:inline-flex; align-items:center; justify-content:center;
  background:#D0271D; color:#fff; font-weight:800; font-size:13px; letter-spacing:.01em;
  box-shadow:0 1px 2px rgba(15,23,42,.16);
}
.rr-adp-sec-h{
  margin:2px 0 9px; font-size:11.5px; font-weight:700;
  letter-spacing:.04em; text-transform:uppercase; color:var(--text-muted);
}
.rr-adp-list{ list-style:none; margin:0 0 14px; padding:0; display:flex; flex-direction:column; gap:9px; }
.rr-adp-list li{ display:flex; align-items:center; gap:10px; font-size:14px; color:var(--text); }
.rr-adp-list li svg{ flex:0 0 auto; width:18px; height:18px; color:var(--green); }
.rr-adp-secure{
  display:flex; align-items:flex-start; gap:9px;
  padding:10px 12px; border-radius:10px;
  background:var(--canvas); border:1px solid var(--border-subtle);
  font-size:12.5px; line-height:1.45; color:var(--text-muted);
}
.rr-adp-secure svg{ flex:0 0 auto; width:16px; height:16px; color:var(--text-subtle); margin-top:1px; }
.rr-adp-banner{
  display:flex; align-items:center; gap:11px;
  padding:11px 13px; border-radius:11px; margin-bottom:15px;
  background:color-mix(in srgb, var(--green) 9%, #fff);
  border:1px solid color-mix(in srgb, var(--green) 26%, #fff);
}
/* The author display:flex above outranks the UA [hidden] rule, so re-assert
   it (higher specificity) — otherwise the banner shows in the unconnected state. */
.rr-adp-banner[hidden]{ display:none; }
.rr-adp-banner-ico{
  flex:0 0 auto; width:30px; height:30px; border-radius:50%;
  display:inline-flex; align-items:center; justify-content:center;
  background:var(--green); color:#fff;
}
.rr-adp-banner-ico svg{ width:16px; height:16px; }
.rr-adp-banner-t{ margin:0; font-size:13.5px; font-weight:600; color:var(--text); }
.rr-adp-banner-s{ margin:1px 0 0; font-size:12px; color:var(--text-muted); }
/* Import-to-drivers panel (shown once connected + synced). */
.rr-adp-import{
  margin-top:14px; padding:13px; border-radius:11px;
  background:var(--accent-soft); border:1px solid var(--accent-border);
}
.rr-adp-import[hidden]{ display:none; }
.rr-adp-import-h{ font-size:13px; font-weight:600; color:var(--text); }
.rr-adp-import-s{ margin:3px 0 11px; font-size:12.5px; line-height:1.45; color:var(--text-muted); }
.rr-adp-import-s b{ color:var(--accent-text); }
.rr-adp-import-done{ font-size:12.5px; font-weight:600; color:var(--green); }
/* ──────────────────────────────────────────────────────────────────── */

